(window.GIM_TS=window.GIM_TS||{})["Sotah.3"]={"from":72,"a":[["\u0003ככתבו\u0004 בתורה, בשם הויה, \u0003ובמדינה בכינויו,\u0004 בשם אדנות. \u0003במדינה —\u0004 \u0003כהנים נושאים\u0004 (מגביהים) \u0003את ידיהן כנגד כתפיהן\u0004 בשעת הברכה, \u0003ובמקדש\u0004 מרימים אותן \u0003על גבי ראשיהן, חוץ מכהן גדול שאינו מגביה את ידיו למעלה מן הציץ\u0004 מפני שהשם המפורש כתוב עליו, ואין ראוי להגביה ידיו למעלה מן השם. \u0003ר' יהודה אומר: אף כהן גדול מגביה ידיו למעלה מן הציץ, שנאמר: \"וישא אהרן את ידיו אל העם ויברכם\"\u0004 (ויקרא ט, כב).","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 הציווי לכהנים \u0003\"כה תברכו\u0004 את בני ישראל\u0003\"\u0004 (במדבר ו, כג) הרי זה \u0003בלשון הקודש. אתה אומר בלשון הקודש, או אינו אלא בכל לשון?\u0004 — \u0003נאמר כאן\u0004 בברכת כהנים \u0003\"כה תברכו\", ונאמר להלן\u0004 בברכות וקללות \u0003\"אלה יעמדו לברך את העם\"\u0004 (דברים כז, יב), ולומדים מגזירה שווה \"תברכו\" \"לברך\": \u0003מה להלן\u0004 בברכות וקללות למדנו לעיל בתחילת הפרק (סוטה דף לג, א) \u0003בלשון הקודש —\u0004 \u0003אף כאן בלשון הקודש.\u0004","\u0003ר' יהודה אומר: אינו צריך\u0004 ללמוד זאת בגזירה שווה, ש\u0003הרי הוא אומר\u0004 בברכת כהנים \u0003\"כה\"\u0004 = כך, להדגיש: \u0003עד שיאמרו בלשון הזה\u0004 הכתובה בתורה, ולא בשינוי.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003\"כה תברכו\"\u0004 הוא \u0003בעמידה. אתה אומר בעמידה, או אינו אלא אפילו בישיבה? נאמר כאן \"כה תברכו\" ונאמר להלן\u0004 בברכות וקללות \u0003\"אלה יעמדו לברך\", מה להלן בעמידה —\u0004 \u0003אף כאן בעמידה.\u0004","\u0003ר' נתן אומר: אינו צריך\u0004 לגזירה שווה זו, \u0003הרי הוא אומר\u0004 \u0003\"\u0004בעת ההיא הבדיל ה' את שבט לוי... \u0003לשרתו ולברך בשמו\"\u0004 (דברים י, ח), ולומדים מגזירה שווה: \u0003מה\u0004 כהן \u0003משרת\u0004 (\"לשרתו\") עבודתו \u0003בעמידה —\u0004 \u0003אף\u0004 כהן \u0003מברך\u0004 (\"ולברך בשמו\") \u0003בעמידה.\u0004 ושואלים: \u0003ומשרת גופיה מנלן\u0004 \u0005[עצמו מניין לנו]\u0006 שהוא בעמידה — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לעמד לשרת\u0004 בשם ה'\" (דברים יח, ה).","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003\"כה תברכו\" —\u0004 \u0003בנשיאות\u0004 (הגבהת) \u0003כפים. אתה אומר בנשיאות כפים, או אינו אלא שלא בנשיאות כפים? נאמר כאן \"כה תברכו\" ונאמר להלן\u0004 בחנוכת המשכן \u0003\"וישא אהרן את ידו אל העם ויברכם\"\u0004 (ויקרא ט, כב), ולומדים מגזירה שווה: \u0003מה להלן\u0004 ברכת אהרן \u0003בנשיאות כפים\u0004 (\"וישא... את ידיו\") — \u0003אף כאן\u0004 ברכת הכהנים \u0003בנשיאות כפים.\u0004","\u0003קשיא ליה\u0004 \u0005[היה קשה לו]\u0006 \u0003לר' יונתן: אי\u0004 \u0005[אם]\u0006 משם אתה למד, אם כן דייק גם כך: \u0003מה להלן\u0004 בחנוכת המשכן \u0003כהן גדול\u0004 היה מברך, \u0003ו\u0004היה זה \u0003ראש חודש ו\u0004היתה זאת \u0003עבודת צבור,\u0004 שקרבנות ציבור הם שקרבו אז, \u0003אף כאן\u0004 נשיאת כפים אינה נעשית אלא אצל \u0003כהן גדול וראש חודש ועבודת ציבור?\u0004","\u0003ר' נתן אומר: אינו צריך\u0004 ללמוד זאת בגזירה שווה, ש\u0003הרי הוא אומר\u0004 \u0003\"\u0004לעמוד לשרת בשם ה' \u0003הוא ובניו כל הימים\"\u0004 (דברים יח, ה), \u0003מקיש בניו לו; מה הוא\u0004 אהרן \u0003בנשיאות כפים —\u0004 \u0003אף בניו בנשיאות כפים, וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"כל הימים\",\u0004 משמע לא רק בזמן מיוחד. \u0003ו\u0004אף שהפסוק אינו עוסק בברכת כהנים \u0003איתקש\u0004 \u0005[הוקשה,\u0006 הושוותה\u0005]\u0006 בפסוק אחר \u0003ברכה לשירות,\u0004 שנאמר: \"לשרתו ולברך בשמו\" (דברים י, ח).","\u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 מה שנאמר \u0003\"כה תברכו את בני ישראל\"\u0004 — הרי זה \u0003בשם המפורש. אתה אומר בשם המפורש, או אינו אלא בכינוי\u0004 (בשם אדנות)? \u0003תלמוד לומר: \"ושמו את שמי\"\u0004 (במדבר ו, כז) לומר: \u0003שמי המיוחד לי.\u0004","\u0003יכול אף בגבולין\u0004 (מחוץ למקדש) יעשו \u0003כן —\u0004 \u0003נאמר כאן \"ושמו את שמי\", ונאמר להלן\u0004 \u0003\"\u0004המקום אשר יבחר ה'... \u0003לשום את שמו שם\"\u0004 (דברים יב, ה), ולומדים מגזירה שווה זו \u0003מה להלן\u0004 \"לשום את שמו שם\" — כוונתו \u0003בית הבחירה, אף כאן\u0004 \"ושמו את שמי\" המיוחד \u0003בבית הבחירה\u0004 ולא בגבולין.","\u0003ר' יאשיה אומר: אינו צריך\u0004 לגזירה שווה, אלא \u0003הרי הוא אומר \"בכל המקום אשר אזכיר את שמי אבוא אליך\u0004 וברכתיך\u0003\"\u0004 (שמות כ, כא), והדברים מתמיהים: וכי יהא גילוי שכינה \u0003בכל מקום סלקא דעתך\u0004 \u0005[עולה על דעתך]\u0006 לומר? \u0003אלא מקרא זה מסורס הוא,\u0004 שצריך להבינו בשינוי סדר; \u0003בכל מקום אשר אבוא אליך וברכתיך —\u0004 \u0003שם אזכיר את שמי,\u0004 כלומר, ייזכר במפורש. \u0003והיכן אבוא אליך וברכתיך —\u0004 \u0003בבית הבחירה, שם אזכיר את שמי —\u0004 \u0003בבית הבחירה.\u0004","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 ממה שנאמר \u0003\"כה תברכו את בני ישראל\", אין לי אלא\u0004 לברך את \u0003בני ישראל\u0004 בלבד, ואולם לברך \u0003גרים נשים ועבדים משוחררים מנין? תלמוד לומר\u0004 מיד אחר כך: \u0003\"אמור להם\"\u0004 (במדבר ו, כג), והכוונה היא \u0003לכולהו\u0004 \u0005[לכולם],\u0006 לכל קהל ישראל.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003\"כה תברכו\"\u0004 — הברכה צריכה להיות \u0003פנים כנגד פנים,\u0004 כשהקהל מפנה פניו לעומת פני הכהנים. \u0003אתה אומר פנים כנגד פנים, או אינו אלא פנים כנגד עורף? תלמוד לומר: \"אמור להם\" —\u0004 \u0003כאדם האומר לחבירו\u0004 שמדבר עמו פנים אל פנים.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003\"כה תברכו\" —\u0004 \u0003בקול רם. או אינו אלא בלחש? תלמוד לומר: \"אמור להם\" —\u0004 \u0003כאדם שאומר לחבירו.\u0004","\u0003אמר אביי: נקטינן\u0004 \u0005[מוחזקים אנו]\u0006 שכאשר שליח הציבור מזמין את הכהנים לברך, \u0003לשנים קורא \"כהנים\", ול\u0004כהן \u0003אחד\u0004 המברך — \u0003אינו קורא \"כהן\", שנאמר: \"אמור להם\"\u0004 — לכהנים, הרי זה בלשון רבים, \u0003לשנים\u0004 לפחות. \u0003ואמר רב חסדא: נקטינן\u0004 \u0005[מוחזקים אנו]\u0006 ש\u0003כהן קורא \"כהנים\", ואין ישראל קורא \"כהנים\", שנאמר: \"אמור להם\"\u0004 וכוונתו: \u0003אמירה\u0004"],["\u0003משלהם תהא,\u0004 כלומר, של הכהנים, אחד מהם קורא. ומסכמים, \u0003והילכתא כוותיה\u0004 \u0005[והלכה כשיטתו]\u0006 של \u0003אביי\u0004 שלאחד אין קוראים \"כהן\", \u0003ולית הילכתא כוותיה\u0004 \u0005[ואין הלכה כשיטתו]\u0006 של \u0003רב חסדא\u0004 אלא כל אחד ואפילו מישראל, יכול לקרוא לכהנים.","\u0003(סימן מתאו\"ה לברכ\"ה דוכ\"ן בעבוד\"ה כו\"ס מכי\"ר נהנ\"ה בעגל\"ה).\u0004","\u0003אמר ר' יהושע בן לוי: מנין שהקדוש ברוך הוא מתאוה לברכת כהנים —\u0004 \u0003שנאמר:\u0004 \u0003\"ושמו את שמי על בני ישראל ואני אברכם\"\u0004 (במדבר ו, כז), כלומר, שהקדוש ברוך הוא מחכה עד שיברכו הכהנים ורק אז הוא עצמו מברכם. \u0003ואמר ר' יהושע בן לוי: כל כהן שמברך —\u0004 \u0003מתברך\u0004 הוא עצמו משמים, \u0003ושאינו מברך —\u0004 \u0003אין מתברך, שנאמר: \"ואברכה מברכיך\"\u0004 (בראשית יב, ג).","\u0003ואמר ר' יהושע בן לוי: כל כהן שאינו עולה לדוכן\u0004 לברך — \u0003עובר בשלשה\u0004 חיובי \u0003עשה\u0004 שאינו מקיימם: \u0003\"כה תברכו\"\u0004 (במדבר ו, כג), \u0003\"אמור להם\"\u0004 (במדבר ו, כג), \u0003\"ושמו את שמי\"\u0004 (במדבר ו, כז).","\u0003רב אמר:\u0004 זה שלא עולה לדוכן \u0003חוששין\u0004 (יש לחשוש) \u0003שמא בן גרושה או בן חלוצה הוא\u0004 ופסול לכהונה, ולכן לא עלה.","ומעירים: \u0003ולא פליגי\u0004 \u0005[ואין\u0006 הם \u0005חלוקים],\u0006 \u0003הא\u0004 \u0005[\u0006כהן \u0005זה]\u0006 שדיבר עליו ר' יהושע בן לוי — הוא זה \u0003דסליק\u0004 \u0005[שעולה]\u0006 \u0003לפרקים\u0004 מזמן לזמן, שאין מקום לחשוד בו שהוא פסול, אבל הוא עובר על מצוות עשה כאשר אינו עולה, \u0003הא\u0004 \u0005[\u0006כהן \u0005זה]\u0006 שדיבר עליו רב — הוא זה \u0003דלא סליק\u0004 \u0005[שאינו עולה]\u0006 אף \u0003לפרקים\u0004 ונותן מקום לחשוד שאינו כהן כלל.","\u0003ואמר ר' יהושע בן לוי: כל כהן שאינו עולה\u0004 לדוכן \u0003ב\u0004ברכת ה\u0003עבודה\u0004 שבתפילה, \u0003שוב אינו עולה, שנאמר:\u0004 \u0003\"וישא אהרן את ידו אל העם ויברכם וירד מעשת החטאת והעלה והשלמים\"\u0004 (ויקרא ט, כב), \u0003מה להלן\u0004 במשכן, נשא אהרן את כפיו \u0003בעבודה,\u0004 כפי שנאמר שמיד אחר שנשא כפיו ירד מעשות החטאת וכו', \u0003אף כאן\u0004 בתפילה — ברכת כהנים נערכת \u0003בעבודה.\u0004","ושואלים: \u0003איני\u0004 \u0005[וכן הוא]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' אמי ור' אסי\u0004 שהיו כהנים \u0003סלקי\u0004 \u0005[היו עולים]\u0006 גם לאחר מכן! ומשיבים: \u0003ר' אמי ור' אסי מעיקרא הוו עקרי כרעייהו\u0004 \u0005[מתחילה היו עוקרים\u0006 את \u0005רגליהם]\u0006 ללכת לברך כבר בברכת העבודה, ואולם \u0003ממטא\u0004 \u0005[להגיע\u0006 לדוכן\u0005]\u0006 \u0003לא הוה מטו התם\u0004 \u0005[היו מגיעים לשם]\u0006 עד לאחר ברכת העבודה. \u0003וכדתני\u0004 \u0005[וכפי ששנה]\u0006 \u0003ר' אושעיא: לא שנו\u0004 דבר זה שכהן שאינו עולה לדוכן בברכת עבודה שוב אינו מברך, \u0003אלא שלא עקר את רגליו, אבל עקר את רגליו\u0004 לפני שסיים שליח ציבור את הברכה — \u0003עולה\u0004 אפילו לאחר מכן.","\u0003ותנן נמי\u0004 \u0005[ושנינו גם כן]\u0006 בענין זה ששליח ציבור שהוא כהן — אינו מברך ברכת כהנים, אבל \u0003אם הבטחתו\u0004 (מובטח לו) \u0003שנושא את כפיו וחוזר לתפלתו\u0004 בלי בלבול — \u0003רשאי. והוינן\u0004 \u0005[והיינו\u0006 עוסקים ומתקשים\u0005]\u0006 \u0003בה: הא\u0004 \u0005[הרי]\u0006 אם \u0003לא עקר\u0004 ממקומו לעלות לדוכן? \u0003אלא\u0004 צריך לומר \u0003דנד פורתא\u0004 \u0005[שנע,\u0006 שזז \u0005קצת]\u0006 להראות שגם הוא רוצה לעלות, \u0003הכא נמי דעקר פורתא\u0004 \u0005[כאן גם כן\u0006 מדובר \u0005ש\u0006הוא \u0005עוקר מעט]\u0006 ממקומו.","\u0003ואמר ר' יהושע בן לוי: אין נותנין כוס של ברכה לברך\u0004 ברכת המזון \u0003אלא ל\u0004מי שהוא \u0003טוב עין, שנאמר:\u0004 \u0003\"טוב עין הוא יברך כי נתן מלחמו לדל\"\u0004 (משלי כב, ט), \u0003אל תיקרי\u0004 \u0005[תקרא]\u0006 \u0003\"יבורך\" אלא \"יברך\".\u0004","\u0003ואמר ר' יהושע בן לוי: מנין שאפילו עופות מכירין בצרי העין\u0004 (קמצנים) ואינם באים אליהם — \u0003שנאמר:\u0004 \u0003\"כי חנם מזרה הרשת בעיני כל בעל כנף\"\u0004 (משלי א, יז), שמפרש שאף שהציידים הללו שמים מזונות ברשתם — אין העופות באים לאכול מהם.","\u0003ואמר ר' יהושע בן לוי: כל הנהנה מצרי העין עובר בלאו\u0004 (מצות לא תעשה) — \u0003שנאמר:\u0004 \u0003\"אל תלחם\u0004 (תאכל) \u0003את לחם רע עין\u0004 ואל תתאו למטעמותיו. \u0003כי כמו שער בנפשו כן הוא אכול ושתה יאמר לך\u0004 ולבו בל עמך\u0003\"\u0004 (משלי כג, ו-ז). \u0003רב נחמן בר יצחק אמר: עובר בשני לאוין,\u0004 שהרי נאמר שם \u0003\"אל תלחם\", \"ואל תתאו\".\u0004","\u0003ואמר ר' יהושע בן לוי: אין עגלה ערופה באה אלא בשביל צרי העין, שנאמר: \"וענו ואמרו ידינו\u0004","\u0003לא שפכו את הדם הזה\"\u0004 (דברים כא, ז) ומדוע זקני העיר מתוודים וידוי זה? \u0003וכי על לבנו עלתה שזקני בית דין שופכי דמים הם,\u0004 שהם צריכים להודיע שלא הם הרגוהו? \u0003אלא\u0004 הכוונה היא, שהם צריכים לומר ש\u0003לא בא\u0004 ההרוג \u0003לידינו ופטרנוהו, ולא ראינוהו והנחנוהו.\u0004 וכוונתו \u0003לא בא לידינו ופטרנוהו בלא מזונות\u0004 להאכילו, \u0003לא ראינוהו והנחנוהו בלא לוייה\u0004 (ליווי). וצרי העין, שאינם נותנים מזונות — הם שגורמים לאדם שילך למקומות כאלה שעשוי ליהרג בהם.","\u0003אמר אדא אמר ר' שמלאי: בית הכנסת שכולה כהנים —\u0004 \u0003כולן עולין לדוכן.\u0004 ושואלים: \u0003למי מברכין? אמר ר' זירא: לאחיהם שבשדות.\u0004","ושואלים: \u0003איני\u0004 \u0005[\u0006האם \u0005כן הוא]?\u0006 \u0003והתני\u0004 \u0005[והרי שנה]\u0006 \u0003אבא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב מנימין בר חייא:\u0004 ה\u0003עם ש\u0004נמצאים \u0003אחורי כהנים —\u0004 \u0003אינן בכלל ברכה\u0004 של הכהנים! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה] —\u0006 \u0003דאניסי\u0004 \u0005[ש\u0006הם \u0005אנוסים]\u0006 במלאכתם כגון אלו שבשדות, ומשום כך הרי הם בכלל ברכה, \u0003הא\u0004 \u0005[זה] —\u0006 \u0003דלא אניסי\u0004 \u0005[שאינם אנוסים]\u0006 ואינם באים לעמוד פנים בפנים אל הכהנים — אינם בכלל ברכה.","ומקשים על דברי ר' שמלאי: \u0003והתני\u0004 \u0005[והרי שנה]\u0006 \u0003רב שימי מבירתא דשיחורי\u0004 (שם מקום) ברייתא זו: \u0003בית הכנסת שכולה כהנים —\u0004 \u0003מקצתן עולין, ומקצתן עונין \"אמן\"!\u0004","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה] —\u0006 \u0003דאישתייר בי עשרה\u0004 \u0005[שנשאר\u0006 מנין \u0005עשרה]\u0006 כהנים מתברכים בבית הכנסת שאז עולים מקצתם לברך, \u0003הא\u0004 \u0005[זה]—\u0006 ש\u0003לא אשתייר בי עשרה\u0004 \u0005[נשארו\u0006 מנין \u0005עשרה],\u0006 שאין כאן עדה שתענה \"אמן\", מוטב שיעלו כולם ויברכו את העם שבשדות.","\u0003גופא\u0004 \u0005[לגופה]\u0006 של אותה הלכה: \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003אבא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב מנימין בר חייא: עם שאחורי\u0004 ה\u0003כהנים\u0004 בשעת ברכת כהנים \u0003אינן בכלל ברכה.\u0004","ויש כמה שאלות בנושא זה, ותחילה מקדימים: \u0003פשיטא\u0004 \u0005[פשוט\u0006 לנו\u0005]\u0006 כי \u0003אריכי באפי גוצי לא מפסקי\u0004 \u0005[\u0006אנשים \u0005גבוהים בפני נמוכים אינם מפסיקים,\u0006 חוצצים\u0005]\u0006 לענין ברכת כהנים. \u0003תיבה\u0004 שיש בה ספר תורה — \u0003לא מפסקא\u0004 \u0005[מפסיקה]\u0006 גם היא. ואולם \u0003מחיצה\u0004 הקבועה בין הכהנים לעם \u0003מאי\u0004 \u0005[מה]\u0006 דינה? \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ש\u0003אמר ר' יהושע בן לוי: אפילו מחיצה של ברזל אינה מפסקת בין ישראל לאביהם שבשמים\u0004 ומכל מקום הם מתברכים.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: אלה שעומדים ב\u0003צדדין מהו,\u0004 האם הם בכלל ברכה? \u0003אמר אבא מר בר רב אשי: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 תשובה לדבר ממה \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]\u0006 בדיני הזאת מי חטאת לטהרת מי שנטמא במת: \u0003נתכוון\u0004 המזה \u0003להזות לפניו\u0004"],["\u0003והזה\u0004 במקום זה \u0003לאחריו,\u0004 או התכוון להזות \u0003לאחריו והזה לפניו,\u0004 אף על פי שנפלה הזאה על הכלים הצריכים טהרה — \u0003הזאתו פסולה.\u0004 אבל אם התכוון להזות \u0003לפניו והזה על צדדין שב\u0004כיוון \u0003פניו —\u0004 \u0003הזאתו כשרה.\u0004 ומכאן למדים שהצדדים נחשבים כאילו היו לפניו.","\u0003אמר רבא בר רב הונא: כיון שנפתח ספר תורה אסור לספר\u0004 (לדבר) \u0003אפילו בדבר הלכה, שנאמר:\u0004 \u0003\"\u0004ויפתח עזרא הספר לעיני כל העם... \u0003וכפתחו עמדו כל העם\"\u0004 (נחמיה ח, ה), \u0003ואין עמידה אלא שתיקה, שנאמר:\u0004 \u0003\"והוחלתי כי לא ידברו כי עמדו לא ענו עוד\"\u0004 (איוב לב, טז). \u0003ר' זירא אמר\u0004 בשם \u0003רב חסדא, מהכא\u0004 \u0005[מכאן]\u0006 אנחנו למדים דבר זה: \u0003\"ואזני כל העם אל ספר התורה\"\u0004 (נחמיה ח, ג), ולא שמעו כל דיבור אחר.","\u0003ואמר ר' יהושע בן לוי: כל כהן שלא נטל ידיו\u0004 תחילה — \u0003לא ישא את כפיו, שנאמר:\u0004 \u0003\"שאו ידיכם קדש וברכו את ה'\"\u0004 (תהלים קלד, ב) שצריכים לקדש את הידים בנטילה לפני ברכה.","\u0003שאלו תלמידיו את ר' אלעזר בן שמוע: ב\u0004זכות \u0003מה הארכת ימים? אמר להן: מימי לא עשיתי בית הכנסת קפנדריא\u0004 (דרך קיצור ממקום למקום), \u0003ולא פסעתי על ראשי עם קודש,\u0004 כלומר, לא הייתי מהלך בבית המדרש כאשר הלומדים היו יושבים על הארץ, ונראיתי כמהלך על ראשיהם, \u0003ולא נשאתי כפי\u0004 בברכת כהנים \u0003בלא\u0004 להקדים לכך \u0003ברכה.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003מברך\u0004 הכהן לפני נשיאת כפיים? \u0003אמר ר' זירא אמר רב חסדא,\u0004 כך מברך: \u0003\"אשר קדשנו בקדושתו של אהרן וצונו לברך את עמו ישראל באהבה\".\u0004","אומרים: \u0003כי עקר כרעיה\u0004 \u0005[כאשר\u0006 הכהן \u0005עוקר\u0006 את \u0005רגליו]\u0006 והולך לברך \u0003מאי אמר\u0004 \u0005[מה\u0006 הוא \u0005אומר]?\u0006 — \u0003\"יהי רצון מלפניך ה' אלהינו שתהא ברכה זו שצויתנו לברך את עמך ישראל, לא יהא בה מכשול ועון\". וכי מהדר אפיה מציבורא מאי אמר\u0004 \u0005[וכאשר מחזיר\u0006 הכהן \u0005פניו מן הציבור\u0006 בגמר הברכה \u0005מה\u0006 הוא \u0005אומר]?\u0006 \u0003אדבריה\u0004 \u0005[הדריכו]\u0006 \u0003רב חסדא לרב עוקבא, ודרש\u0004 שכך הוא אומר: \u0003\"רבונו של עולם! עשינו מה שגזרת עלינו, עשה עמנו\u0004"],["\u0003מה שהבטחתנו\u0004 \"ושמו את שמי על בני ישראל ואני אברכם\" (במדבר ו, כז). \u0003\"השקיפה ממעון קדשך מן השמים\u0004 וברך את עמך את ישראל\u0003\"\u0004 (דברים כו, טו).","\u0003אמר רב חסדא: אין הכהנים\u0004 הפותחים את כפות ידיהם בשעת הברכה \u0003רשאים לכוף\u0004 (לכפוף) \u0003קישרי\u0004 (פירקי) \u0003אצבעותיהן עד שיחזרו פניהם מן הצבור\u0004 לאחר שסיימו לברך. \u0003אמר ר' זירא אמר רב חסדא: אין הקורא רשאי לקרות \"כהנים\" עד שיכלה \"אמן\" מפי הצבור\u0004 שענו על ברכת ההודאה, כדי שיישמע את קול הכהנים,","\u0003ו\u0004מאותה סיבה \u0003אין הכהנים רשאין להתחיל בברכה עד שיכלה דיבור\u0004 (\"כהנים\") \u0003מפי הקורא, ואין הצבור רשאין לענות \"אמן\" עד שתכלה ברכה מפי הכהנים, ואין הכהנים רשאין להתחיל בברכה אחרת עד שיכלה \"אמן\" מפי הצבור\u0004 על הברכה הקודמת.","\u0003ואמר ר' זירא אמר רב חסדא: אין הכהנים רשאין להחזיר פניהם מן הצבור\u0004 לאחר ברכת כהנים \u0003עד שיתחיל שליח צבור ב\u0004ברכת \u0003\"שים שלום\", ואינן רשאין לעקור רגליהם ולילך\u0004 מן הדוכן \u0003עד שיגמור שליח צבור \"שים שלום\". ו\u0004באופן דומה","\u0003אמר ר' זירא אמר רב חסדא: אין הצבור רשאין לענות \"אמן\" עד שתכלה ברכה מפי הקורא\u0004 בתורה, \u0003ואין הקורא רשאי לקרות בתורה עד שיכלה \"אמן\" מפי הצבור, ואין המתרגם רשאי להתחיל בתרגום עד שיכלה פסוק מפי הקורא, ואין הקורא רשאי להתחיל בפסוק אחר עד שיכלה תרגום מפי המתרגם.\u0004","\u0003אמר ר' תנחום אמר ר' יהושע בן לוי: המפטיר בנביא,\u0004 כלומר, זה הקורא את פרק ההפטרה לאחר קריאת התורה, \u0003צריך שיקרא בתורה\u0004 פסוקים אחדים \u0003תחילה, ואמר ר' תנחום אמר ר' יהושע בן לוי: אין המפטיר רשאי להפטיר בנביא עד שיגלל ספר תורה.\u0004","\u0003ואמר ר' תנחום אמר ר' יהושע בן לוי: אין שליח צבור רשאי להפשיט את התיבה\u0004 שמניחים עליה את ספר התורה, כלומר, להסיר ממנה את הכיסוי המקושט, \u0003בצבור, מפני כבוד צבור\u0004 שלא יצטרכו כל הציבור להמתין לשם כך.","\u0003ואמר ר' תנחום אמר ר' יהושע בן לוי: אין הצבור רשאין לצאת\u0004 מבית הכנסת לאחר הקריאה בתורה \u0003עד שינטל ספר תורה ויניח במקומו,\u0004 כלומר, על מנת להניחו במקומו, שנהגו שהספר יהא מונח בבית שמור סמוך לבית הכנסת. \u0003ושמואל אמר: עד שיצא\u0004 ספר תורה ממש, משום כבוד ספר תורה.","ומעירים: \u0003ולא פליגי\u0004 \u0005[ואין\u0006 הם \u0005חלוקים]\u0006 בהלכה, אלא מדברים במקרים שונים; \u0003הא\u0004 \u0005[זה] —\u0006 \u0003דאיכא פיתחא אחרינא\u0004 \u0005[שיש פתח אחר]\u0006 הרי כשינטל ספר התורה לצאת בפתח אחד, מותר לאנשים לצאת בפתח אחר. \u0003הא\u0004 \u0005[זה] —\u0006 \u0003דליכא פיתחא אחרינא\u0004 \u0005[שאין פתח אחר],\u0006 הרי צריכים לחכות עד שיצא הספר מן הפתח. \u0003אמר רבא:\u0004 החכם \u0003בר אהינא אסברה\u0004 \u0005[הסביר]\u0006 \u0003לי\u0004 את טעמה של הלכה זו, על פי מה שנאמר: \u0003\"אחרי ה' אלהיכם תלכו\"\u0004 (דברים \u0003יג, ה) —\u0004 כלומר, שצריכים ללכת אחרי ספר התורה, ולא לפניו.","ועוד בענין ברכת כהנים. \u0003בזמן שהכהנים מברכים את העם, מה הן,\u0004 העם, \u0003אומרים? אמר ר' זירא אמר רב חסדא:\u0004 אומרים הם \u0003\"ברכו ה' מלאכיו גברי כח\" וגו'\u0004 (תהלים קג, כ), \u0003\"ברכו ה' כל צבאיו משרתיו עשי רצונו\"\u0004 (תהלים קג, כא), \u0003\"ברכו ה' כל מעשיו בכל מקמות ממשלתו ברכי נפשי את ה'\"\u0004 (תהלים קג, כב), כנגד כל ברכה שאומרים הכהנים — אומר העם לשון ברכה מן הכתוב.","\u0003במוספי דשבתא\u0004 \u0005[ב\u0006תפילת ה\u0005מוספים של שבת]\u0006 שהכהנים שבים ומברכים את העם \u0003מה הן,\u0004 העם, \u0003אומרים?\u0004 שאין ראוי שיחזרו ויאמרו אותם דברי הודאה שאמרו קודם. \u0003אמר ר' אסי:\u0004 אומרים \u0003\"שיר המעלות הנה ברכו את ה' כל עבדי ה'\u0004 העומדים בבית ה' בלילות\" (תהלים קלד, א), \u0003\"שאו ידכם קדש וברכו את ה'\"\u0004 (תהלים קלד, ב), \u0003\"ברוך ה' מציון שכן ירושלם\u0004 \u0003הללויה\"\u0004 \u0005(תהלים קלה, כא)\u0006.","ושואלים: \u0003ולימא נמי\u0004 \u0005[ושיאמרו גם כן]\u0006 \u0003\"יברכך ה' מציון\"\u0004 (תהלים קלד, ג) \u0003דכתיב בההוא עניינא\u0004 \u0005[שנאמר באותו ענין],\u0006 כלומר, שיאמרו שלוש לשונות ברכה האמורות רצופות באותו פרק בתהילים! \u0003אמר יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' שמעון בן פזי: מתוך שהתחיל בברכותיו של הקדוש ברוך הוא —\u0004 \u0003מסיים בברכותיו של הקדוש ברוך הוא,\u0004 ואינו מכניס משפט זה שהוא ברכה לישראל.","ושואלים: \u0003במנחתא דתעניתא\u0004 \u0005[במנחה של תענית]\u0006 כשהכהנים מברכים את העם \u0003מאי אמרי\u0004 \u0005[מה אומרים\u0006 העם\u0005]?\u0006 \u0003אמר רב אחא בר יעקב:\u0004 אומרים הם \u0003\"אם עונינו ענו בנו ה' עשה למען שמך\"\u0004 (ירמיה יד, ז), \u0003\"מקוה ישראל מושיעו בעת צרה למה תהיה כגר בארץ\" וגו'\u0004 (ירמיה יד, ח), \u0003\"למה תהיה כאיש נדהם כגבור לא יוכל להושיע\" וגו'\u0004 (ירמיה יד, ט)."],["\u0003ב\u0004תפילת \u0003נעילה דיומא דכיפורי\u0004 \u0005[של יום הכיפורים]\u0006 שגם בה הכהנים מברכים, \u0003מאי אמר\u0004 \u0005[מה אומרים]\u0006 הקהל? \u0003אמר מר זוטרא, ואמרי לה\u0004 \u0005[ו\u0006יש \u0005אומרים]\u0006 \u0003במתניתא\u0004 \u0005[בברייתא\u0006 היא שנויה\u0005]:\u0006 \u0003\"הנה כי כן יברך גבר ירא ה'\"\u0004 (תהלים קכח, ד). \u0003\"יברכך ה' מציון וראה בטוב ירושל ם כל ימי חייך\"\u0004 (תהלים קכח, ה). \u0003\"וראה בנים לבניך שלום על ישראל\"\u0004 (תהלים קכח, ו).","ושואלים: \u0003היכן אומרן\u0004 את כל הפסוקים האלה, שאמרנו שהקהל אומרים בזמן ברכת כהנים? \u0003רב יוסף אמר: בין כל ברכה וברכה\u0004 כלומר, לאחר כל אחת מברכות הכהנים אומרים אותם, \u0003ורב ששת אמר: בהזכרת השם\u0004 שבכל ברכה וברכה.","\u0003פליגי בה\u0004 \u0005[נחלקו בכך]\u0006 \u0003רב מרי ורב זביד; חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר: פסוקא לקבל פסוקא\u0004 \u0005[פסוק לעומת פסוק],\u0006 כלומר, בזמן שהכהנים אומרים פסוק אחד, אומר אחד מהפסוקים שמנינו, \u0003וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר: אכל פסוקא אמר להו לכולהו\u0004 \u0005[על כל פסוק אומר\u0006 הוא \u0005את כולם].\u0006","\u0003אמר ר' חייא בר אבא: כל האומרן\u0004 פסוקים אלו \u0003בגבולין\u0004 (מחוץ למקדש) — \u0003אינו אלא טועה. אמר ר' חנינא בר פפא: תדע\u0004 ש\u0003במקדש\u0004 עצמו \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא מיבעי למימרינהו\u0004 \u0005[\u0006היה \u0005צריך לומר אותם]\u0006 את הפסוקים הללו, שכן \u0003כלום יש לך עבד שמברכין אותו ואינו מאזין,\u0004 אלא מדבר באותה שעה?","לעומת זאת \u0003אמר ר' אחא בר חנינא: תדע\u0004 ש\u0003בגבולין נמי מיבעי למימרינהו\u0004 \u0005[גם כן צריך לומר אותם],\u0006 \u0003כלום יש עבד שמברכין אותו ואין מסביר פנים?\u0004 אלא יש לומר אותם, שבכך הוא כמודה על הברכה שהוא מתברך. \u0003אמר ר' אבהו: מריש הוה אמינא להו\u0004 \u0005[מתחילה הייתי אומר אותם],\u0006 את הפסוקים הללו, \u0003כיון דחזינא ליה\u0004 \u0005[שראיתי אותו]\u0006 את \u0003ר' אבא\u0004 ש\u0003מן עכו דלא אמר להו\u0004 \u0005[שאינו אומר אותם] —\u0006 \u0003אנא נמי לא אמינא להו\u0004 \u0005[אני גם כן איני אומר אותם].\u0006","\u0003ואמר ר' אבהו: מריש הוה אמינא עינותנא אנא\u0004 \u0005[מתחילה הייתי אומר ענוותן אני].\u0006 \u0003כיון דחזינא ליה\u0004 \u0005[שראיתי אותו]\u0006 \u0003לר' אבא\u0004 ש\u0003מן עכו\u0004 ש\u0003אמר איהו חד טעמא\u0004 \u0005[הוא, טעם אחד\u0006 לדברים\u0005]\u0006 \u0003ואמר אמוריה חד טעמא\u0004 \u0005[המתורגמן שלו\u0006 טעם \u0005אחד,\u0006 אחר\u0005]\u0006 \u0003ו\u0004הוא, ר' אבא \u0003לא קפיד\u0004 \u0005[הקפיד] —\u0006 \u0003אמינא\u0004 \u0005[אומר אני]\u0006 \u0003לאו עינותנא אנא\u0004 \u0005[אין אני ענוותן],\u0006 שאני הייתי מקפיד בכגון זה.","ושואלים: \u0003ומאי עינוותנותיה\u0004 \u0005[ומהי ענוותנותו]\u0006 של \u0003ר' אבהו?\u0004 מספרים: ש\u0003אמרה לה דביתהו דאמוריה\u0004 \u0005[אשתו של המתורגמן]\u0006 של \u0003ר' אבהו לדביתיה\u0004 \u0005[לאשתו]\u0006 של \u0003ר' אבהו: הא דידן לא צריך ליה לדידך\u0004 \u0005[זה שלנו,\u0006 כלומר בעלי, \u0005איננו צריך לשלך,\u0006 לבעלך\u0005]\u0006 והוא יכול לומר את כל הדברים מדעת עצמו, \u0003והאי דגחין וזקיף עליה\u0004 \u0005[וזה ש\u0006הוא \u0005מתכופף\u0006 לשמוע את דבריו \u0005ו\u0006אחר כך \u0005מזדקף מעליו\u0006 ואומר אותם לציבור\u0005] —\u0006 \u0003יקרא בעלמא\u0004 \u0005[כבוד בלבד]\u0006 \u0003הוא דעביד ליה\u0004 \u0005[שעושה לו],\u0006 אבל באמת אינו נזקק כלל לדבריו. \u0003אזלא דביתהו\u0004 \u0005[הלכה אשתו]\u0006 \u0003ואמרה ליה\u0004 \u0005[לו]\u0006 \u0003לר' אבהו\u0004 את דבריה של אשת המתורגמן. \u0003אמר לה: ומאי נפקא ליך מינה\u0004 \u0005[ומה יוצא לך מכך]?\u0006 \u0003מיני ומיניה יתקלס עילאה\u0004 \u0005[ממני וממנו יתקלס העליון,\u0006 הקדוש ברוך הוא\u0005]\u0006 ואין זה חשוב מי הוא האומר את הדברים.","\u0003ותו\u0004 \u0005[ועוד]\u0006 דוגמה לענוותנותו, \u0003ר' אבהו אימנו רבנן עליה לממנייה ברישא\u0004 \u0005[נמנו חכמים עליו\u0006 והסכימו \u0005למנותו בראש\u0006 הישיבה\u0005],\u0006 \u0003כיון דחזיה\u0004 \u0005[שראה]\u0006 את \u0003ר' אבא\u0004 ש\u0003מן עכו דנפישי ליה\u0004 \u0005[שמרובים לו]\u0006 \u0003בעלי חובות\u0004 והוא עני, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003איכא רבה\u0004 \u0005[יש\u0006 אדם \u0005גדול\u0006 ממני\u0005]\u0006 והוא ר' אבא, שעל ידי כך רצה לחלצו ממצבו הדחוק.","ועוד מסופר על ענוותנותו של ר' אבהו: \u0003ר' אבהו ור' חייא בר אבא איקלעו לההוא אתרא\u0004 \u0005[הזדמנו למקום אחד],\u0006 \u0003ר' אבהו דרש באגדתא\u0004 \u0005[ב\u0006דברי \u0005אגדה],\u0006 ובאותו זמן \u0003ר' חייא בר אבא דרש בשמעתא\u0004 \u0005[בהלכה].\u0006 \u0003שבקוה כולי עלמא\u0004 \u0005[עזבו הכל]\u0006 \u0003לר' חייא בר אבא, ואזול לגביה\u0004 \u0005[והלכו אצל]\u0006 \u0003ר' אבהו. חלש דעתיה\u0004 \u0005[חלשה דעתו,\u0006 הצטער ונעלב\u0005]\u0006 ר' חייא בר אבא. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אבהו דברי פיוס: \u0003אמשול לך משל למה הדבר דומה: לשני בני אדם, אחד מוכר אבנים טובות ואחד מוכר מיני סידקית\u0004 (דברים קטנים), \u0003על מי קופצין\u0004 רוב הקונים — \u0003לא על זה שמוכר מיני סידקית?\u0004 ואף כאן אתה עוסק בדברים גדולים וחשובים, שאין קופצים מרובים עליהם, ואני עוסק בדברים קטנים, ולכן הכל באים אלי.","\u0003מסופר:\u0004 \u0003כל יומא הוה\u0004 \u0005[בכל יום היה]\u0006 \u0003מלוה ר' חייא בר אבא\u0004 את \u0003ר' אבהו עד אושפיזיה\u0004 \u0005[אכסנייתו]\u0006 \u0003משום יקרא דבי קיסר\u0004 \u0005[כבודו של בית הקיסר]\u0006 שר' אבהו היה מקורב אליו. \u0003ההוא יומא אלויה\u0004 \u0005[באותו יום ליווה אותו]\u0006 \u0003ר' אבהו לר' חייא בר אבא עד אושפיזיה\u0004 \u0005[בית מלונו],\u0006 \u0003ואפילו הכי\u0004 \u0005[כך]\u0006 \u0003לא איתותב דעתיה מיניה\u0004 \u0005[נתיישבה דעתו ממנו],\u0006 שנעלב.","כיון שעסקנו במה שעונה הקהל בזמן ברכת כהנים, דנים בנושא דומה. \u0003בזמן ששליח צבור אומר\u0004 ברכת \u0003מודים, העם מה הם אומרים? אמר רב:\u0004 אומרים הם \u0003\"מודים אנחנו לך ה' אלהינו על שאנו מודים לך\",\u0004 כלומר, על שזכינו לכך. \u0003ושמואל אמר:\u0004 יש להוסיף \u0003\"אלהי כל בשר, על שאנו מודים לך\". ר' סימאי אומר: \"יוצרנו יוצר בראשית על שאנו מודים לך\". נהרדעי אמרי משמיה\u0004 \u0005[\u0006חכמי \u0005נהרדעא אומרים משמו]\u0006 של \u0003ר' סימאי: \"ברכות והודאות לשמך הגדול על שהחייתנו וקיימתנו, על שאנו מודים לך\". רב אחא בר יעקב\u0004 היה \u0003מסיים בה הכי\u0004 \u0003[כך]:\u0004 \u0003\"כן תחיינו ותחננו, ותקבצנו, ותאסוף גליותינו לחצרות קדשך, לשמור חוקיך ולעשות רצונך בלבב שלם, על שאנו מודים לך\".\u0004","\u0003אמר רב פפא: הילכך\u0004 \u0005[לכן]\u0006 כיון שהוסיפו ואמרו חכמים כמה נוסחאות נצרף את כל הנוסחאות ו\u0003נימרינהו לכולהו\u0004 \u0005[נאמר את כולן]\u0006 יחד.","\u0003אמר ר' יצחק: לעולם תהא אימת צבור עליך\u0004 וצריך לנהוג בהם בדרך ארץ, \u0003שהרי כהנים\u0004 בשעה שמברכים את העם \u0003פניהם כלפי העם\u0004 אף על פי שכתוצאה מכך \u0003אחוריהם כלפי שכינה,\u0004 מפני כבוד הציבור.","\u0003רב נחמן אמר: מהכא\u0004 \u0005[מכאן]\u0006 אנו למדים, שנאמר: \u0003\"ויקם דוד המלך על רגליו ויאמר שמעוני אחי ועמי\"\u0004 (דברי הימים א כח, ב), שלא דיבר אליהם בישיבה, אלא קם ועמד על רגליו. \u0003אם\u0004 אמר \u0003\"אחי\" למה\u0004 אמר \u0003\"עמי\", ואם \"עמי\" למה \"אחי\"? אמר ר' אלעזר: אמר להם דוד לישראל: אם אתם שומעין לי —\u0004 \u0003אחי אתם, ואם לאו\u0004 \u0005[לא],\u0006 שאינכם שומעים מרצונכם — \u0003עמי אתם, ואני\u0004 מלך ואני \u0003רודה אתכם במקל\u0004 בכפיה. הרי שאם נהג העם כשורה, נהג בהם דוד בכבוד ובאחווה.","\u0003רבנן אמרי מהכא\u0004 \u0005[חכמים אומרים מכאן],\u0006 שכבוד ציבור גדול: ש\u0003אין הכהנים רשאין לעלות בסנדליהן לדוכן,\u0004 שכן שנינו בברייתא: \u0003וזהו,\u0004 שיעלו הכהנים לברך בלי מנעל, היא \u0003אחת מתשע תקנות שהתקין רבן יוחנן בן זכאי. מאי טעמא\u0004 \u0005[מה טעם\u0006 התקנה\u0005] —\u0006 \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום כבוד צבור,\u0004 שאין זו דרך כבוד להראות לכל את נעליו המלוכלכות? \u0003אמר רב אשי: לא,\u0004 אין זה הטעם, אלא \u0003התם\u0004 \u0005[שם]\u0006 הטעם הוא \u0003שמא נפסקה\u0004 (נקרעה) \u0003לו רצועה בסנדלו והדר אזיל למיקטריה\u0004 \u0005[וחוזר\u0006 ו\u0005הולך לקשור אותה]\u0006 ולא יספיק לעלות לברך, \u0003ואמרי\u0004 \u0005[ויאמרו\u0006 אנשים\u0005]:\u0006 \u0003בן גרושה או בן חלוצה הוא,\u0004 ופסול לעלות לדוכן, ולכן אינו מברך.","שנינו במשנה: \u0003ובמקדש\u0004 אומר את שלושת הפסוקים של ברכת כהנים כ\u0003ברכה אחת.\u0004"],["\u0003וכל כך למה —\u0004 \u0003לפי שאין עונין \"אמן\" במקדש,\u0004 משום כך אין הפסק בין ברכה אחת לשניה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מנין שאין עונין \"אמן\" במקדש —\u0004 \u0003שנאמר: \"קומו ברכו את ה' אלהיכם מן העולם עד העולם\"\u0004 (נחמיה ט, ה), שזו היתה לשון ברכה במקדש. \u0003ומנין שעל כל ברכה וברכה\u0004 שבמקדש אומרים העם דברי \u0003תהלה —\u0004 \u0003שנאמר: \"ויברכו שם כבדך ומרומם על כל ברכה ותהלה\"\u0004 (נחמיה ט, ה), לומר: \u0003על כל ברכה וברכה תן לו תהלה\u0004 לעצמה, אבל \"אמן\" לא היו אומרים.","\u0003ברכות כהן גדול\u0004 ביום הכפורים \u0003כיצד? חזן הכנסת\u0004 (שמש בית הכנסת) שהיה בהר הבית \u0003נוטל ספר תורה ונותנה לו לראש הכנסת\u0004 (פרנס הממונה על בית הכנסת), \u0003וראש הכנסת נותנה לסגן\u0004 הכהן הגדול, \u0003והסגן נותנה לכהן גדול,\u0004","\u0003וכהן גדול עומד ומקבל\u0004 ממנו, \u0003וקורא\u0004 בתורה פרשת \u0003\"אחרי מות\"\u0004 (ויקרא טז, א-לד) \u0003ו\"אך בעשור\"\u0004 (ויקרא כג, כו-לב). \u0003וגולל את התורה ומניחה בחיקו, ואומר: יתר ממה שקריתי לפניכם, כתוב כאן\u0004 בספר התורה. ואת ההמשך \u0003\"ובעשור\"\u0004 (במדבר כט, ז-יא) \u0003שבחומש הפקודים\u0004 (ספר במדבר) \u0003קורא על פה.\u0004","\u0003ומברך עליה\u0004 על התורה \u0003שמנה ברכות:\u0004 ברכה \u0003על התורה, ועל העבודה, ועל ההודייה, ועל מחילת העון, ועל המקדש, ועל ישראל, ועל הכהנים, ועל ירושלים, והשאר תפלה.\u0004","על הסדר הזה, שמכבדים את ראש הכנסת והסגן בקבלת ספר התורה קודם שנותנים אותו לכהן הגדול, מעירים: \u0003שמעת מינה\u0004 \u0005[לומד אתה מכאן]\u0006 ש\u0003חולקין כבוד לתלמיד\u0004 אף \u0003במקום\u0004 המצאו של \u0003הרב.\u0004","\u0003אמר אביי:\u0004 בדרך כלל אין עושים כן, וכאן \u0003כולה משום כבודו\u0004 של \u0003כהן גדול הוא,\u0004 שרואים כמה וכמה מעלות יש עד שמגיעים למעלתו שלו.","שנינו ש\u0003כהן גדול עומד ומקבל וקורא.\u0004 ומעירים: \u0003\"עומד\" —\u0004 \u0003מכלל\u0004 הדברים אתה למד שעד עכשיו \u0003יושב הוא? והאמר מר\u0004 \u0005[והרי אמר החכם]:\u0006 \u0003אין\u0004 רשות \u0003ישיבה בעזרה אלא למלכי בית דוד בלבד, שנאמר: \"ויבא המלך דוד וישב לפני ה' ויאמר מי אנכי\" וגו'\u0004 (שמואל ב ז, יח)!","ומשיבים: \u0003כדאמר\u0004 \u0005[כפי שאמר]\u0006 \u0003רב חסדא\u0004 שהמלך אף שאינו מבית דוד שהיה קורא פרשת \"הקהל\" היה יושב \u0003בעזרת נשים\u0004 והיא לא התקדשה בקדושת מקדש, ושם מותר לשבת, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003בעזרת נשים,\u0004 ושם הכהן הגדול יושב.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו: \u0003והיכן קורין בו\u0004 בספר התורה ביום הכיפורים — \u0003בעזרה, ר' אליעזר בן יעקב אומר: בהר הבית\u0004 קוראים בו, \u0003שנאמר:\u0004"],["\u0003\"ויקרא בו לפני הרחוב אשר לפני שער המים\"\u0004 (נחמיה ח, ג). הרי שלדעת חכמים היו קוראים בעזרה! \u0003אמר רב חסדא:\u0004 אף שם מדובר \u0003בעזרת נשים.\u0004","\u0003ו\u0004עוד שנינו במשנה שהכהן הגדול \u0003קורא \"אחרי מות\" ו\"אך בעשור\". ורמינהי\u0004 \u0005[ומטילים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003מדלגין בנביא\u0004 בקריאה בציבור מקטע לקטע \u0003ואין מדלגין בתורה,\u0004 והרי כאן מדלג הכהן ממקום למקום בקריאתו בתורה!","\u0003אמר אביי: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003כאן\u0004 שאסרו לדלג — הרי זה \u0003בכדי שיפסוק התורגמן\u0004 במקום שיש דילוג ארוך, והמתורגמן צריך להפסיק ולהמתין עד שיגיע הקורא למקום אחר, אסור לדלג, \u0003כאן\u0004 ביום הכיפורים — \u0003בכדי שלא יפסוק התורגמן\u0004 ששתי הפרשיות קרובות ולכן מותר לדלג.","ומקשים, \u0003והא עלה קתני\u0004 \u0005[והרי עליה שנינו]:\u0006 \u0003מדלגין בנביא\u0004 \u0003ואין מדלגין בתורה. ועד כמה מדלגין\u0004 בנביא — \u0003עד כדי שלא יפסוק התורגמן. מכלל\u0004 הדברים אתה למד כי \u0003בתורה כלל\u0004 ו\u0003כלל לא\u0004 מדלגים!","\u0003אלא אמר אביי\u0004 באופן אחר: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003כאן\u0004 כשהוא קורא \u0003בענין אחד\u0004 — מדלג, \u0003כאן\u0004 כשקורא \u0003בשני עניינין\u0004 — אינו מדלג.","\u0003והתניא\u0004 \u0005[ו\u0006אכן \u0005כן שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מדלגין בתורה בענין אחד, ובנביא\u0004 אפילו \u0003בשני עניינין. וכאן וכאן\u0004 אין מדלגים אלא \u0003בכדי שלא יפסוק התורגמן.\u0004","\u0003ואין מדלגין מנביא לנביא\u0004 אפילו בענין אחד. \u0003ובנביא של שנים עשר\u0004 (\"תרי עשר\") \u0003מדלגין, ובלבד שלא ידלג מסוף הספר לתחילתו.\u0004 אלא אם רוצה לצרף קריאת שני נביאים, קורא המוקדם תחילה ואחר כך את המאוחר.","שנינו במשנה: \u0003וגולל את התורה ומניחה בחיקו,\u0004 ואומר: \"יותר ממה שקריתי לפניכם כתוב כאן\". ומסבירים: \u0003וכל כך למה\u0004 הוא אומר — כדי \u0003שלא להוציא לעז על ספר תורה,\u0004 שלא יאמרו שחסר קטע זה בתורה, ומשום כך קרא אותו בעל פה.","עוד שנינו במשנה: \u0003\"ובעשור שבחומש הפקודים קורא על פה\".\u0004 ושואלים: \u0003וליכרכיה לספר וליקרי\u0004 \u0005[ושיכרוך את הספר,\u0006 יגלול אותו, \u0005ויקרא\u0006 בו\u0005]\u0006 פרשה זו מן הכתב! \u0003אמר רב הונא בר יהודה אמר רב ששת: לפי שאין גוללין ספר תורה בצבור,\u0004 מפני כבוד הציבור.","ושואלים: \u0003וליתי\u0004 \u0005[ושיביא]\u0006 \u0003ספר תורה אחרינא וליקרי\u0004 \u0005[אחר ויקרא\u0006 בו\u0005]!\u0006 \u0003רב הונא בר יהודה אמר: משום פגמו של ראשון,\u0004 שנראה אז כאילו היה הספר הראשון פסול. \u0003ר' שמעון בן לקיש אמר: לפי שאין מברכין ברכה שאינה צריכה,\u0004 ואם יביאו ספר חדש יצטרך הכהן לברך עליו ברכה נוספת.","ושואלים: \u0003ומי חיישינן לפגמא\u0004 \u0005[והאם חוששים אנו לפגם],\u0006 שאם מביאים ספר אחר יאמרו שהספר הראשון היה פגום? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יצחק נפחא: ראש חדש טבת שחל להיות בשבת מביא שלש תורות\u0004 (ספרי תורה) \u0003וקורא\u0004 בהן: קריאה \u0003אחת מעניינו של יום\u0004 (פרשת השבוע), \u0003ואחת של ראש חדש, ואחת בשל חנוכה\u0004 ואין חוששים שמא יאמרו כי הראשון היה פגום!","ומשיבים: \u0003תלתא גברי בתלתא סיפרי ליכא פגמא\u0004 \u0005[שלושה אנשים\u0006 הקוראים \u0005בשלושה ספרים\u0006 שונים \u0005אין\u0006 בכך חשש ל\u0005פגם]\u0006 לספר התורה שקראו בו לפני כן, ואולם \u0003חד גברא בתרי סיפרי\u0004 \u0005[איש אחד\u0006 הקורא \u0005בשני ספרים]\u0006 — \u0003איכא פגמא\u0004 \u0005[יש\u0006 חשש ל\u0005פגם]\u0006 בכבוד הספר הראשון.","שנינו במשנה: \u0003\"ומברך עליה שמנה ברכות\" כו'. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003[מברכין] על התורה כדרך שמברכין בבית כנסת, ועל העבודה\u0004 כמו בתפילת שמונה עשרה (\"רצה\"), \u0003ועל ההודאה\u0004 (\"מודים\"), \u0003ועל מחילת עון —\u0004 \u0003כתיקנן\u0004 כמו בתפילת שמונה עשרה. ומברך \u0003על המקדש בפני עצמו, ועל הכהנים בפני עצמן, על ישראל בפני עצמן, ועל ירושלים בפני עצמה.\u0004","\u0003על מה ששנינו:\u0004 \u0003\"והשאר תפלה\" תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 שכך הוא נוסח \u0003השאר תפלה: \"תחנה רנה ובקשה שעמך ישראל צריכין ליוושע\". וחותם\u0004 ברכה זו \u0003ב\"\u0004 ברוך אתה ה' \u0003שומע תפלה\". מכאן ואילך\u0004 לאחר מכן — \u0003כל אחד ואחד מביא ספר תורה מתוך ביתו וקורא בו. וכל כך למה\u0004 מביאים הכל את ספרי התורה — \u0003כדי להראות חזותו\u0004 (מראהו) של הספר \u0003לרבים,\u0004 שיראו הכל את נויו, שיש בכך משום חיבוב והידור המצוה.","\u0003פרשת המלך כיצד\u0004 היא נקראת? \u0003מוצאי יום טוב הראשון של חג\u0004 הסוכות, \u0003בשמיני\u0004 (בשנה השמינית למחזור השמיטה), \u0003במוצאי שביעית\u0004 לאחר שנת השמיטה, \u0003עושין לו\u0004 למלך \u0003בימה של עץ בעזרה, והוא יושב עליה, שנאמר: \"מקץ שבע שנים במעד\u0004 שנת השמיטה\u0003\"\u0004(דברים לא, י).","\u0003חזן\u0004 (שמש) בית \u0003הכנסת\u0004 שבהר הבית \u0003נוטל ספר תורה ונותנה לראש הכנסת, וראש הכנסת נותנה לסגן\u0004 הכהן הגדול, \u0003והסגן נותנה לכהן גדול, וכהן גדול נותנה למלך. והמלך עומד ומקבל, וקורא יושב.\u0004","\u0003אגריפס המלך עמד וקבל וקרא עומד, ושבחוהו חכמים\u0004 על שקרא בעמידה. \u0003וכשהגיע\u0004 בקריאתו \u0003ל\u0004פסוק בפרשת המלך \u0003\"לא תוכל לתת עליך איש נכרי\"\u0004 (דברים יז, טו) \u0003זלגו עיניו דמעות,\u0004 שהרי הוא היה מבית הורדוס שאינם מזרע ישראל. \u0003אמרו לו\u0004 כל העם: \u0003אל תתירא אגריפס, אחינו אתה, אחינו אתה!\u0004","\u0003וקורא מתחילת \"אלה הדברים\"\u0004 (דברים א, א) \u0003עד \"שמע\"\u0004 (דברים ו, ד), \u0003ו\u0004קורא פרשת \u0003\"שמע\"\u0004 (דברים ו, ד-ט), וקורא \u0003\"והיה אם שמע\",\u0004 (דברים יא, יג-כא), \u0003\"עשר תעשר\"\u0004 (דברים יד, כב-כט), \u0003\"כי תכלה לעשר\"\u0004 (דברים כו, יב-טו), \u0003ופרשת המלך\u0004 (דברים יז, יד-כ), \u0003וברכות וקללות\u0004 (דברים פרק כח) \u0003עד שגומר כל הפרשה.\u0004","\u0003ברכות שכהן גדול מברך אותן\u0004 ביום הכיפורים — \u0003המלך מברך אותן\u0004 במעמד זה, \u0003אלא שנותן\u0004 ברכה \u0003של רגלים תחת\u0004 (במקום) הברכה על \u0003מחילת העון.\u0004","ותוהים על דברי המשנה: \u0003ב\u0004יום ה\u0003שמיני\u0004 של חג \u0003סלקא דעתך\u0004 \u0005[עולה על דעתך]\u0006 לומר? הרי אמר שבמוצאי יום טוב ראשון הוא זמן ההקהל, שהמלך קורא! אלא \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003ב\u0004שנה ה\u0003שמינית\u0004 של מחזור השמיטה.","ושואלים: \u0003וכל הני\u0004 \u0005[אלה]\u0006 הדברים הכתובים בפסוק בקביעת תאריך זה, שנאמר בתורה כך: \"מקץ שבע שנים במועד שנת השמיטה בחג הסוכות, בבוא כל ישראל לראות את פני ה' אלקיך\" (דברים לא, י-יא) \u0003למה לי\u0004 (למה צריך אותם)?","ומשיבים: \u0003צריכי\u0004 \u0005[צריכים]\u0006 כולם להיאמר, \u0003דאי כתב רחמנא\u0004 \u0005[שאם היתה כותבת התורה]\u0006 רק \u0003\"מקץ\u0004 שבע שנים\u0003\"\u0004 (דברים לא, י) — \u0003הוה אמינא נימנו מהשתא\u0004 \u0005[הייתי אומר נמנה מעכשיו],\u0006 מזמן שנאמר הדבר, כלומר, מזמן כניסת עם ישראל לארץ, \u0003ואף על גב\u0004 \u0005[ואף על פי]\u0006 ש\u0003לא מתרמי\u0004 \u0005[מזדמן\u0006 הדבר\u0005]\u0006 \u0003בשמיטה,\u0004 על כן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"\u0004במועד שנת ה\u0003שמיטה\".\u0004","\u0003ואי כתב רחמנא\u0004 \u0005[ואילו כתבה התורה]\u0006 רק \u0003\"\u0004מקץ שבע שנים בשנת ה\u0003שמיטה\" —\u0004 \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003בסוף\u0004 שנת ה\u0003שמיטה,\u0004 על כן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"במעד\",\u0004 והמועד הסמוך הוא בחודש תשרי.","\u0003ואי כתב\u0004 \u0005[ואילו כתבה]\u0006 התורה רק \"מקץ שבע שנים \u0003במעד\u0004 שנת השמיטה\", \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי הכוונה היא \u0003מריש שתא\u0004 \u0005[מראש השנה]\u0006 שגם הוא מועד, על כן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 גם \u0003\"בחג הסכות\".\u0004","\u0003ואי כתב רחמנא\u0004 \u0005[ואילו כתבה התורה]\u0006 רק \u0003\"בחג הסכות\" —\u0004 \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003אפילו יום טוב אחרון\u0004 של סוכות, על כן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 גם \u0003\"בבוא כל ישראל\"\u0004 (דברים לא, יא) —"],["\u0003מאתחלתא\u0004 (בהתחלת) ה\u0003מועד\u0004 מיד, כאשר כל ישראל באים.","שנינו במשנה: \u0003וחזן הכנסת נוטל ספר תורה ונותנו לראש הכנסת\u0004 עד שמעבירים למלך. ומעירים: \u0003שמעת מינה\u0004 \u0005[שומע,\u0006 למד \u0005אתה מכאן]\u0006 ש\u0003חולקין כבוד לתלמיד במקום הרב,\u0004 שהרי חולקים כבוד לכל המכובדים הללו בפני המלך! \u0003אמר אביי:\u0004 אין מכאן ראיה, שכאן \u0003כולה משום כבודו\u0004 של \u0003מלך,\u0004 שמראים בכמה מעלות הוא גדול משאר העם.","שנינו במשנה: \u0003והמלך עומד ומקבל וקורא יושב. אגריפס המלך עמד וקיבל וקרא עומד.\u0004 ותוהים: \u0003עומד מכלל\u0004 הדברים אתה למד ש\u0003יושב\u0004 היה עד עכשיו? \u0003והאמר מר\u0004 \u0005[והרי אמר החכם]:\u0006 \u0003אין ישיבה בעזרה אלא למלכי בית דוד בלבד, שנאמר:\u0004 \u0003\"ויבא המלך דוד וישב לפני ה' ויאמר\" וגו'\u0004 (שמואל ב ז, יח)! ומשיבים: \u0003כדאמר\u0004 \u0005[כפי שאמר]\u0006 \u0003רב חסדא\u0004 לענין ישיבת כהן גדול, שמדובר \u0003בעזרת נשים, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003בעזרת נשים.\u0004","ועוד שנינו: אגריפס עמד וקרא \u0003ושבחוהו חכמים.\u0004 ושואלים: \u0003שבחוהו, מכלל דשפיר עבד\u0004 \u0005[מכאן שיפה עשה]?\u0006 \u0003האמר\u0004 \u0005[\u0006ו\u0005הרי אמר]\u0006 \u0003רב אשי: אפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003נשיא שמחל על כבודו כבודו מחול, מלך שמחל על כבודו —\u0004 \u0003אין כבודו מחול, שנאמר:\u0004 \u0003\"שום תשים עליך מלך\"\u0004 (דברים יז, טו), וכוונתו: \u0003שתהא אימתו עליך!\u0004","ומשיבים: כיון שעשה זאת לשם \u0003מצוה\u0004 \u0003—\u0004 \u0003שאני\u0004 \u0005[שונה]\u0006 הדבר ואין בזה זלזול בכבודו.","שנינו: \u0003וכשהגיע\u0004 אגריפס \u0003ל\"לא תוכל לתת\u0004 עליך איש נכרי\u0003\"\u0004 (דברים יז, טו), אמרו לו כל העם: אחינו אתה. \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' נתן: באותה שעה נתחייבו שונאי ישראל\u0004 (בלשון נקיה, כלומר, ישראל) \u0003כלייה,\u0004 ומדוע — מפני \u0003שהחניפו לו לאגריפס.\u0004","\u0003אמר ר' שמעון בן חלפתא: מיום שגבר אגרופה\u0004 (כוחה) \u0003של חנופה —\u0004 \u0003נתעוותו\u0004 (נתעקמו) \u0003הדינין, ונתקלקלו המעשים, ואין אדם יכול לומר לחבירו \"מעשי גדולים ממעשיך\",\u0004 שכן מחניפים לאנשים ושוב אין יודעים מה היא האמת.","\u0003דרש ר' יהודה בר מערבא\u0004 (בן ארץ ישראל), \u0003ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שדרש זאת \u0003ר' שמעון בן פזי: מותר להחניף לרשעים בעולם הזה, שנאמר\u0004 כי לעתיד לבוא \u0003\"לא יקרא עוד לנבל נדיב ולכילי לא יאמר שוע\"\u0004 (ישעיה לב, ה), \u0003מכלל\u0004 הדברים אתה למד כי \u0003בעולם הזה שרי\u0004 \u0005[מותר]\u0006 לעשות כן.","\u0003ר' שמעון בן לקיש אמר,\u0004 יש ראיה לדבר \u0003מהכא\u0004 \u0005[מכאן]:\u0006 שאמר יעקב לעשו \u0003\"\u0004ראיתי פניך \u0003כראת פני אלהים ותרצני\"\u0004 (בראשית לג, י), שהחניף לו ודימה ראייתו לראיה של מעלה.","\u0003ופליגא\u0004 \u0005[וחלוק]\u0006 פירושו של ר' שמעון בן לקיש להתנהגותו של יעקב על זה של \u0003ר' לוי.\u0004 ש\u0003אמר ר' לוי: משל של יעקב ועשו למה הדבר דומה? לאדם שזימן את חבירו והכיר בו\u0004 האורח \u0003שמבקש להורגו, אמר לו\u0004 האורח בתוך דבריו: \u0003טעם תבשיל זה שאני טועם כתבשיל שטעמתי בבית המלך.\u0004 ואז \u0003אמר\u0004 בעל הבית: \u0003ידע ליה מלכא\u0004 \u0005[המלך\u0006 בודאי \u0005מכיר אותו],\u0006 ומתוך כך \u0003מיסתפי ולא קטיל ליה\u0004 \u0005[מפחד ואינו הורג אותו].\u0006 וכן כשיעקב אמר לעשו שפניו כפני אלוקים — רצה לרמוז לו שהוא זוכה לראות פני אלוקים, כדי להפחיד את עשו שלא יפגע בו.","\u0003אמר ר' אלעזר: כל אדם שיש בו חנופה מביא אף\u0004 (זעם) \u0003לעולם, שנאמר: \"וחנפי לב ישימו אף\"\u0004 (איוב לו, יג), \u0003ולא עוד אלא שאין תפלתו נשמעת, שנאמר:\u0004 \u0003\"לא ישועו כי אסרם\"\u0004 (איוב לו, יג).","\u0003(סימן א\"ף עוב\"ר גיהנ\"ם ביד\"ו ניד\"ה גול\"ה).\u0004","\u0003ואמר ר' אלעזר: כל אדם שיש בו חנופה —\u0004 \u0003אפילו עוברין שבמעי אמן מקללין אותו, שנאמר:\u0004 \u0003\"אמר לרשע צדיק אתה יקבהו עמים יזעמוהו לאמים\"\u0004 (משלי כד, כד), \u0003ואין \"קוב\" אלא קללה, שנאמר\u0004 בדברי בלעם, כאשר נמנע מלקלל: \u0003\"\u0004מה אקוב \u0003לא קבה אל\"\u0004 (במדבר כג, ח), \u0003ואין \"לאום\" אלא עוברין, שנאמר\u0004 כשהיו יעקב ועשו במעי רבקה: \u0003\"ולאם מלאם יאמץ\"\u0004 (בראשית כה, כג).","\u0003ואמר ר' אלעזר: כל אדם שיש בו חנופה נופל בגיהנם, שנאמר: \"הוי האמרים לרע טוב ולטוב רע\" וגו'\u0004 (ישעיה ה, כ), \u0003מה כתיב\u0004 \u0005[נאמר]\u0006 \u0003אחריו —\u0004 \u0003\"לכן כאכל קש לשון אש וחשש להבה ירפה\"\u0004 (ישעיה ה, כד). שמפרש שהעושים כן סופם שריפה כקש באש של גיהנם.","\u0003ואמר ר' אלעזר: כל המחניף לחבירו —\u0004 \u0003סוף\u0004 דבר שהוא \u0003נופל בידו, ואם אינו נופל בידו —\u0004 \u0003נופל ביד בניו, ואם אינו נופל ביד בניו —\u0004 \u0003נופל ביד בן בנו, שנאמר:\u0004 \u0003\"ויאמר ירמיה\u0004 הנביא \u0003[לחנניה] אמן כן יעשה ה' יקם ה' את דבריך\"\u0004 (ירמיה כח, ו) והיה בזה חנופה שלא אמר לו במפורש שהוא נביא שקר, \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006"],["\u0003\"ויהי הוא בשער בנימן ושם בעל פקדת ושמו יראייה בן שלמיה בן חנניה ויתפש את ירמיהו הנביא לאמר אל הכשדים אתה נפל. ויאמר (לו) ירמיהו שקר אינני נפל אל\u0004 (על) \u0003הכשדים\", וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויתפש\u0004 (יראייה ב) \u0003ירמיהו ויבאהו אל השרים\"\u0004 (ירמיה לז, יג-יד), והוא היה בן בנו של חנניה בן עזור, ונענש ירמיהו ונתפס ביד נכד זה כעונש על שהחניף לסבו.","","\u0003ואמר ר' אלעזר: כל עדה שיש בה חנופה — הריהי\u0004 \u0003מאוסה כנדה, שנאמר: \"כי עדת חנף גלמוד\"\u0004 (איוב טו, לד), \u0003שכן בכרכי הים קורין לנדה \"גלמודה\".\u0004 ומעירים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש הלשון\u0005]\u0006 \u0003\"גלמודה\"\u0004 — נוטריקון: \u0003גמולה\u0004 (מובדלת, מופרשת) \u0003מבעלה.\u0004 \u0003ואמר ר' אלעזר: כל עדה שיש בה חנופה —\u0004 \u0003לסוף גולה, כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 \u0003\"כי עדת חנף גלמוד\", וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 \u0003\"ואמרת בלבבך מי ילד לי את אלה ואני שכולה וגלמודה גלה וסורה\"\u0004 (ישעיה מט, כא) ולמד מכאן שעם הגלמוד באה גם הגלות. \u0003אמר ר' ירמיה בר אבא: ארבע כיתות\u0004 (ארבעה סוגים) של אנשים \u0003אין מקבלות פני שכינה: כת ליצים, וכת חניפים, וכת שקרים\u0004 (שקרנים), \u0003וכת מספרי לשון הרע.\u0004","וראיה לדבר: \u0003כת ליצים —\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"משך ידו את לצצים\"\u0004 (הושע ז, ה), כלומר הקדוש ברוך הוא כביכול מושך ידו ואינו רוצה להיות איתם. \u0003כת חניפים —\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי לא לפניו חנף יבוא\"\u0004 (איוב יג, טז). \u0003כת שקרים —\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"דבר שקרים לא יכון\u0004 (יתייצב) \u0003לנגד עיני\"\u0004 (תהלים קא, ז).","","\u0003כת מספרי לשון הרע —\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי לא אל חפץ רשע אתה לא יגרך רע\"\u0004 (תהלים ה, ה), ומפרשים: \u0003צדיק אתה ה' —\u0004 \u0003לא יגור במגורך,\u0004 יחד איתך, \u0003רע,\u0004 כלומר מי שמספר לשון הרע. שכן נאמר בהמשך הפסוקים: \"כי אין בפיהו נכונה קירבם הוות קבר פתוח גרונם לשונם יחליקון\" (תהלים ה, י).","","\u0003משוח מלחמה בשעה ש\u0004היה \u0003מדבר אל העם —\u0004 \u0003בלשון הקודש היה מדבר, שנאמר: \"והיה כקרבכם אל המלחמה ונגש הכהן\"\u0004 (דברים כ, ב) — \u0003זה כהן משוח מלחמה\u0004 שנמשח במיוחד לצורך זה, \u0003\"ודבר אל העם\"\u0004 (דברים כ, ב) — \u0003בלשון הקודש.\u0004","\u0003\"ואמר אליהם שמע ישראל\u0004 אתם קרבים היום למלחמה \u0003על איביכם\"\u0004 (דברים כ, ג) — \u0003ולא על אחיכם,\u0004 כלומר, \u0003לא יהודה על שמעון ולא שמעון על בנימין.\u0004 וההבדל הוא \u0003שאם תפלו בידם\u0004 של אחיכם \u0003ירחמו עליכם, כמה שנאמר\u0004 שלאחר המלחמה שהיתה בין יהודה וישראל \u0003\"ויקמו האנשים אשר נקבו בשמות ויחזיקו בשביה וכל מערמיהם הלבישו מן השלל וילבשום וינעלום ויאכלום וישקום ויסכום וינהלום בחמרים לכל כושל ויביאום ירחו עיר התמרים אצל אחיהם וישובו שמרון\" וגו'\u0004 (דברי הימים ב כח, טו). אלא \u0003על אויביכם אתם הולכים, שאם תפלו בידם אין מרחמין עליכם.\u0004","ועוד אומר להם הכהן \u0003\"אל ירך לבבכם אל תיראו ואל תחפזו\u0004 ואל תערצו מפניהם\u0003\"\u0004 (דברים כ, ג), ומפרשים: \u0003\"אל ירך לבבכם\" —\u0004 \u0003מפני צהלת סוסים וצחצוח חרבות\u0004 של האויב, \u0003\"אל תיראו\" —\u0004 \u0003מפני הגפת תריסין\u0004 (הקשת מגינים) \u0003ושפעת\u0004 (רעש) \u0003הקלגסין\u0004 (הנעליים), \u0003\"אל תחפזו\" —\u0004 \u0003מקול קרנות\u0004 (חצוצרות), \u0003\"\u0004ו\u0003אל תערצו\" —\u0004 \u0003מפני קול צווחות,\u0004","\u0003\"כי ה' אלהיכם ההלך עמכם\"\u0004 (דברים כ, ד). זכרו כי \u0003הם באין בנצחונו של בשר ודם, ואתם באים בנצחונו של מקום\u0004 (הקדוש ברוך הוא). \u0003פלשתים באו בנצחונו של גלית, מה היה סופו —\u0004 \u0003לסוף נפל בחרב ונפלו\u0004 הם \u0003עמו. בני עמון באו בנצחונו של שובך, מה היה סופו —\u0004 \u0003לסוף נפל בחרב ו\u0004הם \u0003נפלו עמו. ואתם אי\u0004 (אין) \u0003אתם כן, \"כי ה' אלהיכם ההלך עמכם להלחם לכם\"\u0004 (דברים כ, ד) — \u0003זה מחנה הארון\u0004 שהיה הולך איתם למלחמה.","על האמור במשנה שואלים: \u0003מאי קאמר\u0004 \u0005[מה אמר],\u0006 כלומר, כיצד הוא לומד ממה שנאמר \"ודבר אל העם\" שהיה אומר בלשון הקודש? ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 הדבר נלמד בגזירה שווה, \u0003שנאמר\u0004 כאן: \u0003\"ודבר\", ולהלן אומר: \"משה ידבר והאלהים יעננו בקול\"\u0004 (שמות יט, יט), \u0003מה להלן\u0004 דברי ה' ומשה היו \u0003בלשון הקודש —\u0004 \u0003אף כאן בלשון הקודש.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"ונגש הכהן ודבר אל העם\"\u0004 (דברים כ, ב). \u0003יכול כל כהן שירצה\u0004 עושה זאת — \u0003תלמוד לומר\u0004 באותה פרשה: \u0003\"ודברו השטרים\"\u0004 (דברים כ, ה), \u0003מה שוטרים —\u0004 \u0003בממונה,\u0004 שהשוטר אינו סתם אדם, אלא מי שנתמנה לצורך שמירת הסדר וכפיית הדינים, \u0003אף כהן —\u0004 דווקא \u0003בממונה\u0004 לצורך זה. ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שיעשה זאת דווקא \u0003כהן גדול?\u0004 ומשיבים: \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003שוטר, מה שוטר\u0004 הוא מי \u0003שיש ממונה על גביו\u0004 שהוא השופט — \u0003אף\u0004 ב\u0003כהן\u0004 זה מדובר \u0003שיש ממונה על גביו,\u0004 שהכהן גדול הוא הממונה על משוח המלחמה.","ושואלים: \u0003כהן גדול נמי\u0004 \u0005[גם כן],\u0006 \u0003האיכא\u0004 \u0005[הרי יש]\u0006 \u0003מלך על גביו,\u0004 ומדוע לא ידבר הוא אל העם! ומשיבים: שיש עליו ממונה \u0003בעבודתו קאמר\u0004 \u0005[אמר],\u0006 שאף שהמלך גבוה מהכהן הגדול בשררה, אבל בתפקידו בכהונה הוא הגדול. ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שיהיה המדבר אל העם \u0003סגן\u0004 הכהנים, שהוא השני בגדולה לכהן גדול! ומשיבים: \u0003סגן לאו\u0004 \u0005[לא]\u0006 \u0003ממונה הוא,\u0004 שאין לו בעצם מינוי מסויים של שררה אלא הוא רק ממלא מקום. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' חנינא סגן הכהנים: למה סגן ממונה —\u0004 \u0003שאם אירע בו פסול בכהן גדול נכנס\u0004 הסגן \u0003ומשמש תחתיו,\u0004 אבל כשלעצמו אין לו מינוי מיוחד. נאמר במשוח מלחמה \u0003\"ואמר אלהם שמע ישראל\"\u0004 (דברים כ, ג). ושואלים: \u0003מאי שנא\u0004 \u0005[מה שונה,\u0006 מדוע דווקא\u0005]\u0006 בלשון \u0003\"שמע ישראל\"? אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' שמעון בן יוחי,\u0004 אומר הוא להם דווקא \"שמע ישראל\" כיון ש\u0003אמר להן הקדוש ברוך הוא לישראל: אפילו לא קיימתם אלא קריאת שמע שחרית וערבית —\u0004 \u0003אי\u0004 (אין) \u0003אתם נמסרין בידם\u0004 של אויביכם, וזהו שרומז בלשון \"שמע ישראל\". \u0003על מה ששנינו במשנה בין הדברים הנאמרים על ידי הכהן ליוצאים למלחמה\u0004 : \u0003\"אל ירך לבבכם אל תיראו\" כו', תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003פעמיים מדבר\u0004 הכהן \u0003עמם,\u0004 פעם \u0003אחת\u0004 כשהם נאספים למלחמה \u0003בספר\u0004 (ליד הגבול), \u0003ו\u0004פעם \u0003אחת במלחמה\u0004 בשדה המערכה. \u0003בספר מה הוא אומר —\u0004","",""],["\u0003שמעו דברי מערכי המלחמה,\u0004 ותדעו מי הם הראויים והמותרים לחזור מן המלחמה, \u0003וחזרו\u0004 אלה שצריכים לחזור. \u0003במלחמה מה הוא אומר —\u0004 \u0003\"אל ירך לבבכם אל תיראו ואל תחפזו ואל תערצו\"\u0004 (דברים כ, ג), ומעירים: ארבע אזהרות אלו הם \u0003כנגד ארבעה דברים שאומות העולם עושין: מגיפין\u0004 מקישים בכלי מלחמה, \u0003ומריעין\u0004 בקרנות, \u0003צווחין, ורומסין\u0004 רוקעים ברגלי סוסיהם כדי להפחיד את האוייב.","נאמר במשנה שאומר הכהן אל העם: \u0003פלשתים באו בנצחונו של גלית\u0004 וכו'. כיון שנזכר ענין זה מפרשים את ענין מלחמת דוד בגלית. \u0003גלית, אמר ר' יוחנן:\u0004 נקרא כך משום \u0003שעמד בגילוי פנים\u0004 (בעזות מצח) \u0003לפני הקדוש ברוך הוא, שנאמר:\u0004 \u0003\"ברו\u0004 (בררו) \u0003לכם איש וירד אלי\"\u0004 (שמואל א, יז ח), \u0003ואין \"איש\" אלא הקדוש ברוך הוא, שנאמר:\u0004 \u0003\"ה' איש מלחמה\"\u0004 (שמות טו, ג). \u0003אמר הקדוש ברוך הוא: הריני מפילו על יד בן איש, שנאמר:\u0004 \u0003\"ודוד בן איש אפרתי הזה\"\u0004 (שמואל א, יז יב).","\u0003אמר ר' יוחנן משום ר' מאיר: בשלשה מקומות לכדו פיו לאותו רשע,\u0004 כלומר, שהוציא מפיו דברים שהיה בהם רמז שהוא עצמו עתיד ליפול: \u0003אחד —\u0004 \u0003\"ברו לכם איש וירד אלי\"\u0004 (שמואל א, יז ח), ודייק בלשון \"ירד\", כלומר, שהוא עצמו יהיה למטה. \u0003ואידך\u0004 \u0005[וה\u0006לשון ה\u0005אחר]:\u0006 \u0003\"אם יוכל להלחם אתי והכני\"\u0004 (שמואל א, יז ט), שפתח בלשון שיש בה מפלה לעצמו. \u0003ואידך\u0004 \u0005[והאחר],\u0006 \u0003דקאמר ליה\u0004 \u0005[שאמר לו]\u0006 \u0003לדוד: \"הכלב אנכי כי אתה בא אלי במקלות\"\u0004 (שמואל א, יז מג). ושואלים: \u0003דוד נמי\u0004 \u0005[גם כן]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003\"אתה בא אלי בחרב ובחנית ובכידון\"\u0004 (שמואל א, יז מה)! ומשיבים: \u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר ליה\u0004 \u0005[לו]\u0006 מיד: \u0003\"ואנכי בא אליך בשם ה' צבאות אלהי (ישראל) מערכות ישראל אשר חרפת\"\u0004 (שמואל א, יז מה).","על מה שנאמר \u0003\"ויגש הפלשתי השכם והערב\"\u0004 (שמואל א, יז טז), \u0003אמר ר' יוחנן:\u0004 עשה זאת בכוונה, \u0003כדי לבטלן מקריאת שמע שחרית וערבית\u0004 שזמנה הוא בבוקר ובערב. ועל מה שנאמר \u0003\"ויתיצב ארבעים יום\"\u0004 (שמואל א, יז טז), \u0003אמר ר' יוחנן: כנגד ארבעים יום שנתנה בהן תורה\u0004 שרצה לבטלה.","נאמר \u0003\"ויצא איש הבנים ממחנות פלשתים\u0004 גלית שמו מגת\" (שמואל א, יז ד). ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"בינים\"? אמר רב: שמבונה\u0004 ומושלם ונקי \u0003מכל מום. ושמואל אמר:\u0004 משמעות \"בינים\" — שהוא \u0003בינוני שבאחיו,\u0004 והיו גדולים ממנו. \u0003דבי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' שילא אמר\u0004 החכם: \u0003שהוא עשוי\u0004 חזק \u0003כבנין. ר' יוחנן אמר: בר\u0004 \u0005[בן]\u0006 \u0003מאה פפי וחדא נאנאי\u0004 \u0005[אבות וכלב אחד],\u0006 שנבעלה אמו לכלב, וזה לשון \"בינים\" — שיצא מבין כולם.","\u0003נאמר: \"גלית שמו מגת\"\u0004 (שמואל א, יז ד). \u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב יוסף: שהכל דשין\u0004 (בועלים) \u0003את אמו כגת\u0004 שהכל דשים בה. \u0003כתיב\u0004 \u0005[כתוב]\u0006 על גלית שעלה מ\u0003\"מערות\u0004 פלשתים\" \u0005(שמואל א, יז כג),\u0006 \u0003וקרינן\u0004 \u0005[וקוראים אנו]\u0006 (הקרי הוא) \u0003\"מערכות\u0004 פלשתים \u0003\". תני\u0004 \u0005[שנה]\u0006 \u0003רב יוסף: שהכל הערו באמו\u0004 ובעלוה, ולכן הכתיב הוא \"מערות פלשתים\".","\u0003כתיב\u0004 \u0005[נאמר]\u0006 ששם אמו של גלית היה \u0003\"הרפה\"\u0004 (שמואל ב כא, טז), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 במקום אחר שם דומה \u0003\"ערפה\"\u0004 (רות א, ד), \u0003רב ושמואל\u0004 נחלקו בכך; \u0003חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר: \"הרפה\" שמה, ולמה נקרא שמה \"ערפה\" —\u0004 \u0003שהכל עורפין\u0004 (בועלים) \u0003אותה מאחריה. וחד\u0004 \u0005[ואחד]\u0006 \u0003אמר: \"ערפה\" שמה, ולמה נקרא שמה \"הרפה\" —\u0004 \u0003שהכל דשין אותה כהריפות\u0004 (כחיטים כתושות), \u0003וכן הוא אומר: \"ותקח האשה ותפרש\u0004 את \u0003המסך על פני הבאר ותשטח עליו הרפות\"\u0004 (שמואל ב יז, יט). \u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שתילמד משמעות המלה הזו \u0003מהכא\u0004 \u0005[מכאן],\u0006 ממקום זה: \u0003\"אם תכתוש את האויל במכתש בתוך הרפות בעלי\"\u0004 (משלי כז, כב).","נאמר \u0003\"את ארבעת אלה ילדו להרפה בגת ויפלו ביד דוד וביד עבדיו\"\u0004 (שמואל ב כא, כב), ושואלים: \u0003מאי נינהו\u0004 \u0005[מי\u0006 הם \u0005אלה]?\u0006 \u0003אמר רב חסדא: סף ומדון גלית וישבי בנוב\u0004 (ראה שמואל ב כא, טז-כ).","נאמר שם: \u0003\"ויפלו ביד דוד וביד עבדיו\",\u0004 מדוע? — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ותשק ערפה לחמותה ורות דבקה בה\"\u0004 (רות א, יד), \u0003אמר ר' יצחק, אמר הקדוש ברוך הוא: יבואו בני הנשוקה,\u0004 כלומר, גלית שבא מערפה שנשקה לחמותה אך נפרדה ממנה, \u0003ויפלו ביד בני הדבוקה,\u0004 דוד שבא מרות שדבקה בה. \u0003דרש רבא: בשכר ארבע דמעות שהורידה ערפה על חמותה\u0004 בצער — \u0003זכתה ויצאו ממנה ארבעה גבורים, שנאמר:\u0004 \u0003\"ותשנה קולן ותבכינה עוד\"\u0004 (רות א, יד).","\u0003כתיב\u0004 \u0005[נאמר]\u0006 בגלית: \u0003\"\u0004ו\u0003חץ חניתו\u0004 כמנור אורגים\u0003\"\u0004 (שמואל א יז, ז) \u0003וקרינן\u0004 \u0005[וקוראים אנו]\u0006 על פי המסורת \u0003\"\u0004ו\u0003עץ חניתו\". אמר ר' אלעזר: עדיין לא הגיענו לחצי שבחו של אותו רשע.\u0004 כלומר, אפילו חצי חניתו היה גדול כל כך, ושינו בלשון כדי שלא ייאמר במפורש. \u0003מכאן שאסור לספר בשבחן של רשעים,\u0004 להודיע כמה גיבורים הם. ושואלים: אם כן \u0003ו\u0004ש\u0003לא לפתח ביה\u0004 \u0005[יפתח בו]\u0006 \u0003כלל\u0004 בסיפור גבורתו! ומשיבים: מכל מקום היה צריך לספר משהו כדי \u0003לאודועי שבחיה\u0004 \u0005[להודיע\u0006 את \u0005שבחו]\u0006 של \u0003דוד\u0004 שניצח אותו למרות שגיבור גדול היה גלית.","שנינו במשנה שאמר הכהן לעם: \u0003\"בני עמון באו בנצחונו של שובך כו'\". כתיב\u0004 \u0005[נאמר]\u0006 במקום אחד \u0003\"שובך\"\u0004 (שמואל ב י, יח), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 במקום אחר \u0003\"שופך\"\u0004 (דברי הימים א יט, יח). \u0003רב ושמואל\u0004 נחלקו בכך; \u0003חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר: \"שופך\" שמו, ולמה נקרא שמו \"שובך\"\u0004 — כינוי הוא \u0003ש\u0004היה \u0003עשוי כשובך,\u0004 שהיה גבוה ביותר. \u0003וחד\u0004 \u0005[ואחד]\u0006 \u0003אמר: \"שובך\" שמו, ולמה נקרא שמו \"שופך\" —\u0004 \u0003שכל הרואה אותו נשפך לפניו\u0004 מרוב אימה \u0003כקיתון\u0004 זה של מים.","נאמר \u0003\"\u0004הנני מביא עליכם גוי ממרחק... \u0003אשפתו כקבר פתוח כלם גבורים\"\u0004 (ירמיה ה, טו-טז). \u0003רב ושמואל, ואמרי לה\u0004 \u0005[ו\u0006יש \u0005אומרים]\u0006 \u0003ר' אמי ור' אסי\u0004 נחלקו; \u0003חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר: בשעה שזורקין חץ, עושין\u0004 הם \u0003אשפתות אשפתות\u0004 (ערימות ערימות) \u0003של חללים, ושמא תאמר שאומנין\u0004 (מומחים, בעלי מקצוע) \u0003בקרב\u0004 ולא מחמת כוחם הגדול — \u0003תלמוד לומר: \"כלם גבורים\". וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר: בשעה שעושין צורכיהן עושין אשפתות אשפתות של זבל, ושמא תאמר מפני שחולי מעיים הם —\u0004 \u0003תלמוד לומר: \"כלם גבורים\".\u0004","\u0003אמר רב מרי: שמע מינה\u0004 \u0005[למד מכאן],\u0006 ממאמר זה: \u0003האי מאן דנפיש זיבליה\u0004 \u0005[מי שמרובה הזבל,\u0006 הצואה, \u0003שלו] —\u0004 \u0003חולי מעיים הוא.\u0004 ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה]\u0006 להודיענו שחולה הוא? ומשיבים: \u0003ליטרח בנפשיה\u0004 \u0005[שידאג לעצמו]\u0006 לחפש תרופה, שלא יכביד החולי.","וכיוצא בו על הכתוב \u0003\"דאגה בלב איש ישחנה\"\u0004 (משלי יב, כה) נחלקו \u0003ר' אמי ור' אסי; חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר: ישחנה מדעתו,\u0004 כלומר, ינסה להסיח אותה מליבו, \u0003וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר:\u0004 הכוונה היא \u0003ישיחנה,\u0004 יספרנה \u0003לאחרים.\u0004","ועוד שנינו שאומר הכהן \u0003\"ואתם אי אתם כן\u0004 כי ה' אלוקיכם ההולך עמכם \u0003\"\u0004— זה מחנה הארון. \u0003וכל כך למה\u0004 מכנים את מחנה הארון \"ה' אלוקיכם\"? \u0003מפני שהשם וכל כינויו\u0004 הכתובים בלוחות הברית"],["\u0003מונחין בארון. וכן הוא אומר\u0004 במלחמת מדין: \u0003\"וישלח אתם משה אלף למטה לצבא אתם ואת פינחס\u0004 בן אלעזר הכהן לצבא וכלי הקודש וחצוצרות התרועה בידו\u0003\"\u0004 (במדבר לא, ו). \u0003\"אתם\" —\u0004 \u0003אלו סנהדרין, \"פינחס\" —\u0004 \u0003זה\u0004 כהן \u0003משוח מלחמה, \"וכלי הקדש\" —\u0004 \u0003זה ארון ולוחות שבו, \"וחצצרות התרועה\" —\u0004 \u0003אלו השופרות.\u0004","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003לא לחנם הלך פינחס למלחמה\u0004 במדין, \u0003אלא\u0004 כדי \u0003ליפרע דין אבי אמו\u0004 יוסף, \u0003שנאמר: \"והמדנים מכרו אתו אל מצרים\" וגו'\u0004 (בראשית לז, לו). ושואלים: \u0003למימרא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 ש\u0003פינחס מ\u0004זרעו של \u0003יוסף אתי\u0004 \u0005[בא]\u0006 מצד אמו? \u0003והא כתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ואלעזר בן אהרן לקח לו מבנות פוטיאל לו לאשה\u0004 ותלד לו את פינחס\u0003\"\u0004 (שמות ו, כה), \u0003מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה \u0003דאתי\u0004 \u0005[שבא]\u0006 \u0003מיתרו שפיטם עגלים לעבודה זרה\u0004 ולכן נתכנה \"פוטיאל\"? ומשיבים: \u0003לא,\u0004 הכוונה היא שבא \u0003מיוסף שפיטפט\u0004 (ליגלג) \u0003ביצרו\u0004 ולא נכשל באשת פוטיפר.","ושואלים: \u0003והלא\u0004 ידוע המדרש ש\u0003שבטים\u0004 היו \u0003מבזין אותו\u0004 את פינחס לאחר שהרג את זימרי, והיו אומרים: \u0003ראיתם בן פוטי זה, בן שפיטם אבי אמו עגלים לעבודה זרה, יהרוג נשיא מישראל,\u0004 ואם כן ודאי הריהו מזרע יתרו! ומתרצים: \u0003אלא\u0004 פינחס הוא גם מזרעו של יוסף וגם מזרעו של יתרו. ובאחת משתי דרכים אלה: \u0003אי אבוה דאימיה\u0004 \u0005[אם אבי אמו]\u0006 \u0003מיוסף —\u0004 \u0003אימיה דאימיה\u0004 \u0005[אם אמו]\u0006 \u0003מיתרו, ואי אימיה דאימיה\u0004 \u0005[ואם אם אמו]\u0006 \u0003מיוסף —\u0004 \u0003אבוה דאימיה\u0004 \u0005[אבי אמו]\u0006 \u0003מיתרו.\u0004 ומעירים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן],\u0006 ממה \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"מבנות פוטיאל\",\u0004 לכאורה \"בנות\" \u0003תרי\u0004 \u0005[שתים]\u0006 \u0003משמע,\u0004 אלא לומר ששני האבות נתכנו \"פוטיאל\", כל אחד מסיבה אחרת. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","\u0003\"ודברו השטרים אל העם לאמר מי האיש אשר בנה בית חדש ולא חנכו ילך וישב לביתו\" וגו'\u0004 (דברים כ, ה). \u0003אחד הבונה בית התבן\u0004 (מחסן לתבן), או \u0003בית הבקר\u0004 (אורווה), או \u0003בית העצים,\u0004 או \u0003בית האוצרות.\u0004 וכן \u0003אחד הבונה\u0004 בעצמו, \u0003ואחד הלוקח\u0004 (קונה), \u0003ואחד היורש, ואחד שנתן לו\u0004 הבית ב\u0003מתנה\u0004 — כולם היו חוזרים.","\u0003\"ומי האיש אשר נטע כרם ולא חללו\" וגו'\u0004 (דברים כ, ו) — \u0003אחד הנוטע כרם, ואחד הנוטע\u0004 לפחות \u0003חמשה אילני מאכל\u0004 אחרים, \u0003ואפילו מחמשת המינין\u0004 שאינם כולם ממין אחד — הרי נחשב הדבר לכרם לענין זה. \u0003אחד הנוטע, ואחד המבריך\u0004 (מכניס ענף בארץ כדי לגדלו כעץ חדש בפני עצמו) \u0003ואחד המרכיב\u0004 עצים זה על זה, \u0003ואחד הלוקח\u0004 (קונה), \u0003ואחד היורש, ואחד שנתן לו\u0004 כרם ב\u0003מתנה.\u0004","\u0003\"ומי האיש אשר ארש אשה\u0004 ולא לקחה\u0003\"\u0004 (דברים כ, ז) — \u0003אחד המארס את הבתולה, ואחד המארס את האלמנה. אפילו שומרת יבם\u0004 שמת אחיו בלא ילדים וצריך הוא לייבמה, \u0003ואפילו שמע שמת אחיו במלחמה\u0004 וצריך לייבם את אשתו — \u0003חוזר ובא לו. כל אלו ואלו\u0004 שאמרנו שחוזרים מכל מקום הם הולכים עם שאר אנשי הצבא ו\u0003שומעין\u0004 את \u0003דברי כהן מערכי מלחמה,\u0004 כלומר, מהמקום שבו עורכים את המלחמה בתוך תחום ישראל, \u0003וחוזרין\u0004 למקומם. אבל משרתים את צורכי הצבא, \u0003ומספקין מים ומזון\u0004 לצבא, \u0003ומתקנין את הדרכים.\u0004","\u0003ואלו שאינן חוזרין\u0004 ממערכי המלחמה: \u0003הבונה בית שער\u0004 (כניסה לבית), או \u0003אכסדרה\u0004 (אולם כניסה פתוח) או \u0003מרפסת\u0004 (מקום שעוברים בו), או \u0003הנוטע\u0004 רק \u0003ארבע אילני מאכל\u0004 או \u0003חמשה אילני סרק, המחזיר את גרושתו,\u0004 או שאירס אשה האסורה לו, כגון \u0003אלמנה לכהן גדול, גרושה\u0004 או \u0003חלוצה לכהן הדיוט, ממזרת\u0004 או \u0003נתינה לישראל, בת ישראל לממזר\u0004 או \u0003לנתין —\u0004 \u0003לא היה חוזר. ר' יהודה אומר: אף הבונה בית על מכונו,\u0004 שמחדש בית שהיה קיים כבר — \u0003לא היה חוזר. ר' אליעזר אומר: אף הבונה בית לבינים בשרון לא היה חוזר,\u0004 שבתים אלה לא היו יציבים והיו נופלים מפעם לפעם.","\u0003אלו שאין זזין ממקומן,\u0004 שאינם צריכים אפילו ללכת למערכי המלחמה והם פטורים לגמרי: מי ש\u0003בנה בית וחנכו\u0004 באותה שנה, \u0003נטע כרם וחללו\u0004 בשנה הרביעית, \u0003הנושא את ארוסתו,\u0004 או \u0003הכונס את יבמתו. שנאמר:\u0004 \"כי יקח איש אשה חדשה לא יצא בצבא ולא יעבור עליו לכל דבר \u0003נקי יהיה לביתו שנה אחת\u0004 ושימח את אשתו אשר לקח\" (דברים כד, ה), ודורשים: \u0003\"לביתו\" —\u0004 \u0003זה ביתו\u0004 שבנה, \u0003\"יהיה\"\u0004 שהוא לשון ריבוי — \u0003זה כרמו, \"ושמח את אשתו\" —\u0004 \u0003זו אשתו, \"אשר לקח\" —\u0004 \u0003להביא\u0004 (לרבות) \u0003את יבמתו,\u0004 שאף על פי שאינה אשתו לגמרי — לקוחתו היא. והם פטורים לגמרי, ואף \u0003אין מספיקין\u0004 (מספקים) \u0003(להם),\u0004 לאנשי הצבא, \u0003מים ומזון, ואין\u0004 הם \u0003מתקנין את הדרכים.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מה שנאמר \u0003\"ודברו השטרים...\u0004 מי האיש אשר בנה \u0003\"\u0004וכו' (דברים כ, ה), \u0003יכול\u0004 שאומרים \u0003דברים של עצמן\u0004 ולא של כהן המשוח? — \u0003כשהוא אומר \"ויספו השטרים\"\u0004 (דברים כ, ח) — \u0003הרי דברים של עצמן אמור,\u0004 שעד עכשיו לא הם דיברו ועכשיו מוסיפים משל עצמם, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003מה אני מקיים\u0004 את דברי הכתוב \u0003\"ודברו השטרים\" —\u0004 \u0003בדברי משוח מלחמה הכתוב מדבר,\u0004 שהשוטרים משמיעים את דבריו. \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד?\u0004 — \u0003כהן מדבר\u0004 בקול נמוך \u0003ושוטר משמיע\u0004 לעם בקול רם את דברי הכהן.","\u0003תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]:\u0006 \u0003כהן מדבר ושוטר משמיע, ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003כהן מדבר וכהן משמיע, ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא שלישית \u0005אחרת]:\u0006 \u0003שוטר מדבר ושוטר משמיע. אמר אביי: הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 אנחנו מיישבים את הברייתות האלה? \u0003מ\u0004מה שנאמר \u0003\"ונגש\"\u0004 (דברים כ, ב) \u0003ועד \"ודברו\"\u0004 (דברים כ, ה), שמעורר את העם לצאת למלחמה ולא לפחד — \u0003כהן מדבר וכהן\u0004 אחר \u0003משמיע, מ\"ודברו\" עד \"ויספו\",\u0004 שמונה שם כל אלה החוזרים מן המערכה בגלל ענייני שמחה — \u0003כהן מדבר ושוטר משמיע, מ\"ויספו\" ואילך\u0004 לגבי הירא ורך הלבב — \u0003שוטר מדבר ושוטר\u0004 אחר \u0003משמיע.\u0004","שנינו במשנה בין הדברים הנאמרים ליוצאים למלחמה: \u0003\"מי האיש אשר בנה בית חדש\" כו'\u0004 (דברים כ, \u0003ה).\u0004 \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"אשר בנה\", אין לי אלא אשר בנה\u0004 ממש, ואולם אם \u0003לקח\u0004 (קנה) או \u0003ירש\u0004 או ש\u0003ניתן לו במתנה מנין\u0004 שאף הוא חוזר — \u0003תלמוד לומר: \"מי האיש אשר בנה\"\u0004 שהוא לשון ריבוי — לרבות את כולם.","\u0003\"בית\", אין לי אלא בית\u0004 מגורים, \u0003מנין לרבות בית התבן, ובית הבקר, ובית העצים, ובית האוצרות —\u0004 \u0003תלמוד לומר: \"אשר בנה\"\u0004 וכוונתו לרבות כל שבנה, \u0003מכל מקום. יכול שאני מרבה אף הבונה בית שער אכסדרה ומרפסת —\u0004 \u0003תלמוד לומר: \"בית\",\u0004 כלומר, \u0003מה בית\u0004 שצריך להיות \u0003הראוי לדירה\u0004 גם אם אין גרים בו — \u0003אף כל הראוי לדירה.\u0004","\u0003ר' אליעזר בן יעקב אומר: \"בית\"\u0004 הוא \u0003כמשמעו,\u0004 בית למגורי אדם דווקא, וכיון שלא נאמר \u0003\"לא חנך\"\u0004 אלא \u0003\"ולא חנכו\"\u0004 הרי זה למעט — \u0003פרט לגזלן\u0004 שהבית איננו שלו. ושואלים: \u0003לימא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 שדברים אלה \u0003דלא\u0004 \u0005[שאינם]\u0006 \u0003כ\u0004דעת \u0003ר' יוסי הגלילי, דאי\u0004 \u0005[שאם]\u0006 כשיטת \u0003ר' יוסי הגלילי —\u0004 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמר:\u0004 מה שנאמר \u0003\"\u0004הירא \u0003ורך הלבב\"\u0004 (דברים כ, ח) \u0003זה המתיירא\u0004"],["\u0003מעבירות שבידו,\u0004 שאם הוא עבריין, כגון גזלן, חוזר מן המלחמה משום שהוא עבריין!","ומשיבים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 כשיטת \u0003ר' יוסי הגלילי,\u0004 מדובר במקרה \u0003כגון דעבד\u0004 \u0005[שעשה]\u0006 \u0003תשובה ויהב דמי\u0004 \u0005[ונתן כסף]\u0006 עבור הבית שגזל, ולכן צריך היה להשמיענו שאף על פי כן אינו חוזר משום הבית הגזול. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 ששילם את דמי הבית \u0003הוה ליה\u0004 \u0005[נעשה לו,\u0006 הריהו\u0005]\u0006 כ\u0003לוקח וליהדר\u0004 \u0005[ויחזור]\u0006 ממערכי המלחמה בתור קונה בית! ומשיבים: \u0003כיון דמעיקרא\u0004 \u0005[שמתחילה]\u0006 \u0003בתורת גזילה אתא לידיה\u0004 \u0005[בא\u0006 הדבר \u0005לידו] —\u0006 \u0003לא\u0004 יחזור.","עוד שנינו במשנה בין הדברים הנאמרים ליוצאים למלחמה: \u0003\"ומי האיש אשר נטע כרם\" כו'\u0004 (דברים כ, ו). \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"אשר נטע\" —\u0004 \u0003אין לי אלא נטע\u0004 ממש, ואולם אם \u0003לקח\u0004 (קנה) או \u0003ירש\u0004 או \u0003ניתן לו במתנה, מנין\u0004 שגם הוא חוזר ממערכי המלחמה — \u0003תלמוד לומר: \"ומי האיש אשר נטע\u0004","\u0003כרם\"\u0004 שהוא לשון ריבוי. \u0003אין לי אלא כרם\u0004 של עצי גפן, \u0003מנין לרבות חמשה אילני מאכל ואפילו משאר מינין\u0004 שאף עליו חוזר — \u0003תלמוד לומר \"אשר נטע\"\u0004 — לרבות מיני אילנות אחרים. \u0003יכול שאני מרבה\u0004 אף \u0003הנוטע\u0004 רק \u0003ארבעה אילני מאכל,\u0004 או אפילו \u0003חמשה אילני סרק —\u0004 \u0003תלמוד לומר: \"כרם\"\u0004 למעט דבר שאינו בגודל של כרם או שאינו עושה פרי ככרם.","\u0003ר' אליעזר בן יעקב אומר: כרם\u0004 הוא \u0003כמשמעו\u0004 דווקא כרם של גפנים ולא דבר אחר. ומזה שלא נכתב \u0003\"לא חילל\",\u0004 ונכתב \u0003\"ולא חללו\"\u0004 (דברים כ, ו) למדנו: דווקא זה שנטע כרם, \u0003פרט למבריך ולמרכיב\u0004 שהם אינם חוזרים. ומקשים: \u0003והא אנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה\u0005]:\u0006 \u0003אחד הנוטע ואחד המבריך ואחד המרכיב\u0004 כולם חוזרים! \u0003אמר ר' זירא אמר רב חסדא: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003כאן בהרכבת איסור\u0004 — אינו חוזר, \u0003כאן בהרכבת היתר\u0004 — חוזר.","ושואלים: \u0003האי\u0004 \u0005[זו]\u0006 \u0003הרכבת היתר\u0004 שחוזר בגללה \u0003היכי דמי\u0004 \u0005[כיצד היא בדיוק]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמרכיב \u0003ילדה בילדה\u0004 (נטיעה צעירה בנטיעה צעירה) אחרת — \u0003תיפוק ליה דבעי מיהדר\u0004 \u0005[תצא,\u0006 תילמד \u0005לו ש\u0006הוא \u0005צריך לחזור]\u0006 \u0003משום ילדה ראשונה\u0004 שעדיין לא נתחללה ולא משום הענף שהרכיב עליה! \u0003אלא\u0004 כשהרכיב \u0003ילדה בזקינה —\u0004 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אבהו: ילדה שסיבכה,\u0004 כלומר, הרכיב אותה \u0003בזקינה —\u0004 \u0003בטלה ילדה בזקינה ואין בה דין ערלה\u0004 ואף כאן לא תיחשב זו כנטיעה חדשה, ולא יחזור!","\u0003אמר ר' ירמיה: לעולם\u0004 תפרש שחוזר מערכי המלחמה כשהרכיב \u0003ילדה בילדה, ו\u0004מדוע אינו חוזר משום הראשונה — \u0003כגון\u0004 ש\u0003נטע להך קמייתא\u0004 \u0005[את זו הראשונה]\u0006 \u0003לסייג\u0004 (לגדר) או \u0003ל\u0004שם \u0003קורות,\u0004 ואחר כך הרכיב עליה נטיעה אחרת לשם פירות. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הנוטע\u0004 אילנות \u0003לסייג ול\u0004עשות מהם \u0003קורות —\u0004 \u0003פטור מן הערלה\u0004 ושואלים:","\u0003ומאי שנא\u0004 \u0005[ומה שונה]\u0006 \u0003ילדה בזקינה\u0004 שהיא \u0003בטלה\u0004 בה, \u0003ומאי שנא\u0004 \u0005[ומה שונה]\u0006 \u0003ילדה בילדה\u0004 ש\u0003לא בטלה?\u0004","ומשיבים: \u0003התם אי מימליך עלה\u0004 \u0005[שם,\u0006 בנטיעה זקינה, \u0005אם היה רוצה להימלך עליה]\u0006 ותיחשב כנטיעה ילדה החייבת בערלה — \u0003לאו\u0004 \u0005[לא]\u0006 \u0003בת מיהדר\u0004 \u0005[חזרה]\u0006 \u0003היא, הכא\u0004 \u0005[כאן],\u0006 בנוטע לסייג ולקורות, \u0003אי מימליך עלה\u0004 \u0005[אם\u0006 רוצה \u0005להימלך עליה]\u0006 ולייעד אותה לפירות — \u0003בת מיהדר\u0004 \u0005[חזרה]\u0006 \u0003היא\u0004 ותתחייב בערלה, \u0003[דהא מעיקרא לפירי קיימא\u0004 \u0005[שהרי מתחילה לפירות\u0006 היא \u0005עומדת]\u0006\u0003],\u0004 \u0003מידי דהוה\u0004 \u0005[כמו שהוא\u0006 הדין\u0005]\u0006 באילנות ש\u0003עלו מאיליהן\u0004 החייבים בערלה אף שלא ניטעו בכוונה לשם פירות. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 אילנות פרי ש\u0003עלו מאיליהן,\u0004 אף על פי שלא נטעם בעצמו — \u0003חייבין בערלה.\u0004","ושואלים: לשם מה צריך להעמיד בנוטע לקורות, \u0003ולוקמה\u0004 \u0005[ושיעמידנה]\u0006 את הרכבת ההיתר שבגללה חוזרים מערכי המלחמה \u0003בכרם של שני שותפין,\u0004 והרכיב אחד מהם את שלו בנטיעה של חבירו \u0003דהאי הדר אדידיה והאי הדר אדידיה\u0004 \u0005[שזה חוזר על\u0006 הנטיעה \u0005שלו וזה חוזר על שלו]?\u0006 מתוך שאלה זו \u0003אמר רב פפא: זאת אומרת כרם של שני שותפין —\u0004 \u0003אין חוזרין עליו מערכי המלחמה.\u0004","ושואלים: \u0003ומאי שנא\u0004 \u0005[ו\u0006ב\u0005מה שונה]\u0006 דין זה \u0003מחמשה אחין ומת אחד מהן במלחמה,\u0004 ש\u0003כולן חוזרין\u0004 מפני שכל אחד מהם ראוי לייבם את אשת האח המת, ואף כאן שייכת לשניהם הילדה שהרכיב? ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 \u0003כל חד וחד קרינא ביה\u0004 \u0005[אחד ואחד\u0006 מהם \u0005קוראים אנו בו]\u0006 \u0003\"אשתו\",\u0004 \u0003שהרי אם ישאנה אחד מהם תהיה זו אשתו גמורה,\u0004 \u0003הכא\u0004 \u0005[כאן] —\u0006 \u0003כל חד וחד לא קרינא ביה\u0004 \u0005[אחד ואחד אין אנו קוראים בו]\u0006 \u0003\"כרמו\",\u0004 שהרי אין הכרם מיוחד לאחד מהם.","\u0003רב נחמן בר יצחק אמר,\u0004 כך יש ליישב את הסתירה בין המשנה לברייתא לגבי הרכבה: כשאמרו במשנה שחוזר בהרכבה, מדובר \u0003במבריך אילן בירק, והאי תנא הוא\u0004 \u0005[ו\u0006שיטת \u0005תנא זה היא],\u0006 המתיר הרכבת אילן בירק. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003המבריך אילן בירק, רבן שמעון בן גמליאל מתיר משום\u0004 (בשם) \u0003ר' יהודה בן גמדא איש כפר עכו, וחכמים אוסרין.\u0004 הרי שלשיטת ר' יהודה בן גמדא יחזור הלה מערכי המלחמה בגלל האילן שהבריך אף שמשום הירק אינו חוזר.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשם \u0003ר' יוחנן: הא מני\u0004 \u0005[\u0006שיטה \u0005זו\u0006 שהמרכיב אינו חוזר מערכי המלחמה \u0005כמי היא] —\u0006 דעת \u0003ר' אליעזר בן יעקב היא.\u0004 וראיה לדבר: האם \u0003לא אמר ר' אליעזר בן יעקב התם\u0004 \u0005[שם]\u0006 \u0003\"כרם\" כמשמעו\u0004 דווקא? \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003\"נטע\" כמשמעו,\u0004 ולכן \u0003נוטע —\u0004 \u0003אין\u0004 \u0005[כן]\u0006 חוזר, \u0003מבריך ומרכיב —\u0004 \u0003לא.\u0004","כיון שהובאו דברים שאמר ר' יוחנן משמו של ר' אליעזר בן יעקב, מביאים עוד דברים שמסר ר' יוחנן בשמו, ובענין אחר. \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי אמר\u0004 בשם \u0003ר' יוחנן משום ר' אליעזר בן יעקב: ילדה\u0004 (גפן צעירה) שהיא \u0003פחותה\u0004 בגובהה \u0003מטפח\u0004 — גזרו חכמים ש\u0003חייבת בערלה כל שנותיה\u0004 אפילו לאחר שנות הערלה, משום \u0003דמתחזיא\u0004 \u0005[שנראית]\u0006 \u0003כבת שתא\u0004 \u0005[שנה]\u0006 ואם יתירוה באכילה יבואו לאכול גם פירות ערלה ממש. \u0003והני מילי\u0004 \u0005[ודברים אלה]\u0006 אמורים דווקא בכרם קטן ביותר שעשוי \u0003שתים\u0004 (שתי גפנים) \u0003כנגד שתים, ואחת יוצאה זנב\u0004 (באמצע, ממולן). \u0003אבל\u0004 אם \u0003כוליה\u0004 \u0005[כל]\u0006 ה\u0003כרם\u0004 כך הוא — \u0003קלא אית ליה\u0004 \u0005[קול יש לו]\u0006 ויודעים שהכרם כבר יצא מזמן הערלה.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי אמר\u0004 בשם \u0003ר' יוחנן משום\u0004 (בשם) \u0003ר' אליעזר בן יעקב: מת תופס ארבע אמות לקריאת שמע,\u0004 שבתוך ארבע אמות מן המת אסור לקרוא קריאת שמע, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לעג לרש חרף עשהו\"\u0004 (משלי יז, ה), שכיון שהמת אינו יכול לקיים מצוות הרי זה שמקיים מצווה לידו נחשב כלועג לו.","\u0003אמר ר' יצחק אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' אליעזר בן יעקב: חורגתא\u0004 (בת חורגת, כגון בת אשת האב מבעל אחר) \u0003הגדילה בין האחין,\u0004 אף על פי שאינה אסורה להם מן הדין משום אחות, שהרי אינה אחותם — מכל מקום \u0003אסורה לינשא לאחין, דמתחזיא כי אחתייהו\u0004 \u0005[ש\u0006היא \u0005נראית כאחותם].\u0006 ומעירים: \u0003ולא היא,\u0004 אין ההלכה כן, כי \u0003קלא אית ליה למילתא\u0004 \u0005[קול יש לו לדבר],\u0006 שדבר זה שאין היא אחותם נודע לרבים, ואין מקום לחשוש.","\u0003ואמר ר' יצחק אמר ר' יוחנן משום ר' אליעזר בן יעקב: לקט שכחה ופאה שעשאן\u0004 (אסף אותן) \u0003בגורן —\u0004 \u0003הוקבעו למעשר,\u0004 וצריך להפריש מהן מעשרות, למרות שכרגיל אין מפרישים מעשרות ממתנות עניים, משום שסבורים האנשים שמפירות שדהו עשה גורן זו. \u0003אמר עולא: לא אמרן\u0004 \u0005[אמרנו]\u0006 הלכה זו \u0003אלא\u0004 כשהיתה זו גורן \u0003בשדה, אבל בעיר —\u0004 \u0003קלא אית ליה למלתא\u0004 \u0005[קול יש לו לדבר],\u0006 שרואים כיצד הביאם מעט מעט ממקומות שונים ויודעים שהן מתנות עניים, ואינו צריך להפריש מהן מעשר.","\u0003ואמר ר' יצחק אמר ר' יוחנן משום ר' אליעזר בן יעקב: ילדה\u0004 (גפן צעירה) \u0003הפחותה\u0004 בגובהה \u0003מטפח —\u0004 \u0003אינה מקדשת\u0004 (אוסרת) \u0003את הזרעים\u0004 שזורעים סמוך לה משום כלאי הכרם שמפני קוטנה אינה קרויה כרם. ושוב מצמצמים את הדבר: \u0003והני מילי\u0004 \u0005[ודברים אלה]\u0006 אמורים דווקא שהיה כרם זה של \u0003שתים כנגד שתים ואחת יוצאה זנב, אבל כולי\u0004 \u0005[כל]\u0006 ה\u0003כרם\u0004 עשוי כך — \u0003מקדיש\u0004 \u0005[אוסר].\u0006","\u0003ואמר ר' יצחק אמר ר' יוחנן משום ר' אליעזר בן יעקב:\u0004"],["\u0003מת תופס ארבע אמות לטומאה,\u0004 שגזרו חכמים שכל הנמצא בתוך ארבע אמות סמוך למת יהיה טמא, כדי שלא יבואו כהנים ואוכלי טהרות להתקרב אליו ממש ויאהילו עליו וייטמאו. \u0003ותנא תונא\u0004 \u0005[ו\u0006כן \u0005שנה התנא שלנו]\u0006 במשנה: \u0003חצר הקבר\u0004 (הצמודה לקבר) — \u0003העומד בתוכה טהור, והוא שיהו בה\u0004 בחצר \u0003ארבע אמות\u0004 על ארבע אמות שאז היא נחשבת כמקום לעצמה ואין לגזור בכך, אלו \u0003דברי בית שמאי. בית הלל אומרים:\u0004 די שיהיו בה \u0003ארבעה טפחים. במה דברים אמורים\u0004 שדי שיהא בה ארבעה טפחים — \u0003שפתחה\u0004 של החצר \u0003מלמעלה\u0004 ויורדים לתוכה, שאין כאן חשש שיאהיל על הקבר וייטמא, \u0003אבל\u0004 היה \u0003פתחה מן הצד —\u0004 \u0003דברי הכל ארבע אמות.\u0004","ותוהים: \u0003כלפי לייא\u0004 \u0005[לאן]\u0006 הדברים אמורים?! כלומר, ההיפך הוא המסתבר: \u0003אדרבא,\u0004 אם היה הפתח \u0003מן הצד מידריד ונפיק\u0004 \u0005[נשמט ויוצא]\u0006 בקלות ואינו מתקרב לטומאה, אבל אם היה הפתח \u0003מלמעלה —\u0004 \u0003אי אפשר\u0004 ש\u0003לא\u0004 יהיה \u0003מאהיל\u0004 על הקבר תוך כדי טיפוס ויציאה מן החצר. \u0003אלא\u0004 כך צריך לומר: \u0003במה דברים אמורים —\u0004 \u0003שפתחה מן הצד, אבל\u0004 אם \u0003פתחה מלמעלה,\u0004 צריך שיהא גודל החצר \u0003ארבע אמות\u0004 לכל הדעות. ומעירים: \u0003והני מילי\u0004 \u0005[ודברים אלה]\u0006 שיכול אדם להיות סמוך למת, אמורים ב\u0003חצר הקבר דמסיימא מחיצתא\u0004 \u0005[שמוגדרות מחיצותיה],\u0006 \u0003אבל מת בעלמא\u0004 \u0005[סתם]\u0006 שאינו נמצא במקום מוגדר בגבולותיו — בודאי \u0003תפיס\u0004 \u0005[תופס]\u0006 ארבע אמות סביבו.","עוד שנינו במשנה בין הדברים הנאמרים ליוצאים למלחמה: \u0003\"\u0004ו\u0003מי האיש אשר ארש אשה\u0004 ולא לקחה ילך וישוב לביתו\u0003\"\u0004 (דברים כ, ז). \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"אשר ארס\" —\u0004 \u0003אחד המארס את הבתולה, ואחד המארס את האלמנה, ואחד שומרת יבם. ואפילו\u0004 היו \u0003חמשה אחין ומת אחד מהם במלחמה\u0004 וצריך אחד האחים הנותרים לייבם את אשתו — \u0003כולן חוזרין\u0004 בשבילה. ועוד, היה יכול לומר \u0003\"לא לקח\"\u0004 ונאמר \u0003\"ולא לקחה\"\u0004 הרי זה למעט: \u0003פרט לאלמנה לכהן גדול, גרושה\u0004 או \u0003חלוצה לכהן הדיוט, ממזרת\u0004 או \u0003נתינה לישראל,\u0004 או \u0003בת ישראל לממזר\u0004 או \u0003לנתין,\u0004 שכולם הם עוברי עבירה וחייבים לגרש את נשותיהם, ואינם חוזרים מן המלחמה.","ושואלים: \u0003לימא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 שהלכה זו ש\u0003לא כ\u0004שיטת \u0003ר' יוסי הגלילי\u0004 היא, \u0003דאי\u0004 \u0005[שאם]\u0006 כשיטת \u0003ר' יוסי הגלילי\u0004 \u0005היא —\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 הוא \u0003אמר\u0004 לפרש את דברי הכתוב \u0003\"הירא ורך הלבב\"\u0004 (דברים כ, ח) — \u0003זה המתיירא מעבירות שבידו,\u0004 ואם כן אלו שנשאו נשים בעבירה הריהם חוזרים מן המלחמה בתור עבריינים?","ומשיבים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא כשיטת \u0003ר' יוסי הגלילי,\u0004 יש לומר שאינם חוזרים \u0003כ\u0004דברי \u0003רבה.\u0004 ש\u0003אמר רבה: לעולם אינו חייב\u0004 על כל הנשים האלה מלקות \u0003עד שיבעול,\u0004 ולא בקידושי כסף ושטר בלבד. \u0003מה טעם\u0004 הדבר — שנאמר בכהן גדול \"אלמנה גרושה וחללה זונה את אלה לא יקח... ולא יחלל זרעו בעמיו\" (ויקרא כא, יד-טו), הרי שנאסר ב\u0003\"לא יקח\" —\u0004 \u0003משום \"לא יחלל\u0004 זרעו\", \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003אינו לוקה עד שיבעול,\u0004 שהרי אין היא וזרעה מתחללים עד שיבוא עליה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 הסדר בכתובים אלה הוא \u0003\"אשר בנה\"\u0004 (דברים כ, ה), ואחר כך \u0003\"אשר נטע\"\u0004 (דברים כ, \u0003ו), ולבסוף\u0004 \u0003\"אשר ארש\"\u0004 (דברים כ, \u0003ז).\u0004 \u0003לימדה תורה דרך ארץ\u0004 לאדם: \u0003שיבנה אדם בית ו\u0004אחר כך \u0003יטע כרם, ואחר כך ישא אשה. ואף שלמה אמר בחכמתו: \"הכן בחוץ מלאכתך ועתדה בשדה לך אחר ובנית ביתך\"\u0004 (משלי כד, כז). \u0003\"הכן בחוץ מלאכתך\" —\u0004 \u0003זה בית, \"ועתדה בשדה לך\" —\u0004 \u0003זה כרם, \"אחר ובנית\u0004 \u0003ביתך\" —\u0004 \u0003זו אשה.\u0004","\u0003דבר אחר,\u0004 נדרש הכתוב לענין לימוד התורה: \u0003\"הכן בחוץ מלאכתך\" —\u0004 \u0003זה מקרא, \"ועתדה בשדה לך\" —\u0004 \u0003זה משנה, \"אחר ובנית ביתך\" —\u0004 \u0003זה גמרא,\u0004 כלומר, העיון והדיון בדברי חכמים. \u0003דבר אחר: \"הכן בחוץ מלאכתך\" —\u0004 \u0003זה מקרא ומשנה, \"ועתדה בשדה לך\" —\u0004 \u0003זה גמרא, \"אחר ובנית ביתך\" —\u0004 \u0003אלו מעשים טובים. ר' אליעזר בנו של ר' יוסי הגלילי אומר: \"הכן בחוץ מלאכתך\" —\u0004 \u0003זה מקרא ומשנה וגמרא, \"ועתדה בשדה לך\" —\u0004 \u0003אלו מעשים טובים, \"אחר ובנית ביתך\" —\u0004 \u0003דרוש וקבל שכר\u0004 שאחר כך יש מקום שיהא אדם דורש ומחדש בתורה.","שנינו במשנה, \u0003ואלו שאינן חוזרין: הבונה בית שער כו',\u0004 ור' יהודה אומר: אף הבונה בית על מכונו אינו חוזר. \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003אם הוסיף בו דימוס\u0004 (נידבך, שורה של אבנים) \u0003אחד\u0004 יתר על הבית הקודם — \u0003חוזר,\u0004 שהרי זה כבניה חדשה, ולא אמר ר' יהודה אלא כשלא שינה בו דבר. עוד שנינו במשנה, \u0003ר' אליעזר אומר: אף הבונה בית לבנים בשרון לא היה חוזר. תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003מפני שמחדשין אותו פעמים בשבוע\u0004 (בשבע שנים), ואם כן אין זה בנין של קבע.","שנינו במשנה, \u0003ואלו שאין זזין ממקומן: בנה בית חדש וחנכו וכו'. תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 על הכתוב \"כי יקח איש אשה חדשה לא יצא בצבא ולא יעבור עליו לכל דבר\" (דברים כד, ה): \u0003\"אשה חדשה\" —\u0004 \u0003אין לי אלא אשה חדשה\u0004 שהיא בתולה שנישאה לו, ואולם אם נשא \u0003אלמנה וגרושה מנין\u0004 שאף הוא אינו יוצא בצבא — \u0003תלמוד לומר: \"אשה\", מכל מקום. אם כן, מה תלמוד לומר \"אשה חדשה\" —\u0004 \u0003מי שחדשה לו, יצא מחזיר גרושתו שאין\u0004 היא \u0003חדשה לו.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"לא יצא בצבא\"\u0004 (דברים כד, ה). \u0003יכול בצבא הוא\u0004 ש\u0003לא יצא, אבל יספיק מים ומזון\u0004 לחיילים, \u0003ויתקן הדרכים —\u0004 \u0003תלמוד לומר: \"ולא יעבר עליו לכל דבר\"\u0004 (דברים כד, ה). \u0003יכול שאני מרבה אף הבונה בית ולא חנכו,\u0004 ואת זה ש\u0003נטע כרם ולא חללו,\u0004 וכן את זה ש\u0003ארס אשה ולא לקחה\u0004 שגם הם לא יעשו דבר — \u0003תלמוד לומר: \"עליו\",\u0004 לדייק ולמעט: \u0003עליו אי אתה מעביר\u0004 שום עבודה, \u0003אבל אתה מעביר על אחרים.\u0004 ושואלים: \u0003ומאחר\u0004 ש\u0003כתב\u0004 בתורה \u0003\"לא יעבור\"\u0004 שנפטר מכל שעבוד, \u0003\"לא יצא בצבא\" למה לי?\u0004 ומשיבים: \u0003לעבור עליו בשני לאוין\u0004 (מצוות לא תעשה); משום \"לא יעבור\" ומשום \"לא יצא\", אם יוצא לצבא.","\u0003\"ויספו השטרים לדבר אל העם\u0004 מי האיש הירא ורך הלבב ילך וישוב לביתו\u0003\"\u0004 (דברים כ, ח). \u0003ר' עקיבא אומר: \"הירא ורך הלבב\"\u0004 הוא \u0003כמשמעו\u0004 — מי \u0003שאינו יכול לעמוד בקשרי המלחמה ולראות חרב שלופה,\u0004 מפני שנופלת עליו אימה. \u0003ר' יוסי הגלילי אומר: \"הירא ורך הלבב\" —\u0004 \u0003זהו המתיירא מן העבירות שבידו, לפיכך תלתה לו התורה\u0004 (נתנה לו מקום לתלות) \u0003את כל אלו\u0004 הסיבות שבגללן נפטרים מלצאת לצבא, משום בית וכרם וכיוצא בהן \u0003שיחזור בגללן,\u0004 שלא ידעו הכל שהוא חוזר משום עבירות שבידו ויחשבו שחוזר משום אחת הסיבות האחרות.","\u0003ר' יוסי אומר:\u0004 מי שנשא אשה בעבירה, כגון \u0003אלמנה לכהן גדול, גרושה\u0004 או \u0003חלוצה לכהן הדיוט, ממזרת\u0004 או \u0003נתינה לישראל, בת ישראל לממזר\u0004 או \u0003לנתין —\u0004 \u0003הרי הוא הירא ורך הלבב\u0004 שמפני שיש בידו עבירות — מפחד שמא ייפגע במלחמה, ומתיירא משום כך.","\u0003\"והיה ככלת השטרים לדבר אל העם ופקדו שרי צבאות בראש העם\"\u0004 (דברים כ, ט). \u0003ובעקיבו\u0004 (בסופו) \u0003של עם, מעמידין זקיפין\u0004 (שומרים) \u0003לפניהם, ו\u0004זקיפין \u0003אחרים מאחוריהם, וכשילין\u0004 (מוטות) \u0003של ברזל בידיהן, וכל המבקש לחזור\u0004 ולברוח מן המלחמה — \u0003הרשות בידו\u0004 של הזקיף \u0003לקפח\u0004 (להכות ולשבור) \u0003את שוקיו.\u0004"],["\u0003שתחילת ניסה\u0004 (בריחה) \u0003נפילה,\u0004 כלומר, שהבריחה גורמת למפלה במלחמה, \u0003שנאמר: \"נס ישראל לפני פלשתים וגם מגפה גדולה היתה בעם\"\u0004 (שמואל א ד, יז), \u0003ו\u0004כן \u0003להלן הוא אומר: \"וינסו אנשי ישראל מפני פלשתים ויפלו חללים\" וגו'\u0004 (שמואל א לא, א).","ומוסיפים: \u0003במה דברים אמורים,\u0004 כל דינים אלה, מי הולך ומי איננו הולך למלחמה — דווקא \u0003במלחמות הרשות, אבל במלחמות מצוה —\u0004 \u0003הכל יוצאין\u0004 למלחמה, \u0003אפילו חתן מחדרו וכלה מחופתה.\u0004 \u0003אמר ר' יהודה: במה דברים אמורים —\u0004 \u0003במלחמות מצוה, אבל במלחמות חובה —\u0004 \u0003הכל יוצאין, אפילו חתן מחדרו וכלה מחופתה.\u0004","שואלים: \u0003מאי איכא\u0004 \u0005[מה,\u0006 איזה הבדל \u0005יש]\u0006 \u0003בין\u0004 שיטת \u0003ר' יוסי ל\u0004שיטת \u0003ר' יוסי הגלילי?\u0004 שלכאורה הם מסכימים לאותו דבר, ש\"ירא ורך הלבב\" הוא עבריין! ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל לגבי \u0003עבירה דרבנן\u0004 \u0005[שמדברי סופרים],\u0006 שלדעת ר' יוסי הגלילי חוזר, ולדעת ר' יוסי אינו חוזר אלא על עבירה מן התורה, כגון איסור אלמנה לכהן גדול.","ומעירים: \u0003כמאן אזלא הא דתניא\u0004 \u0005[כ\u0006שיטת \u0005מי הולכת\u0006 ברייתא \u0005זו ששנינו]:\u0006 \u0003שח\u0004 (דיבר) \u0003בין תפילה לתפילה,\u0004 בין הנחת תפילין של יד להנחת תפילין של ראש — \u0003עבירה היא בידו, וחוזר עליה מעורכי המלחמה. כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 היא הלכה זו — \u0003כ\u0004שיטת \u0003ר' יוסי הגלילי\u0004 שאף על עבירה קלה חוזר.","ושואלים: \u0003מאן תנא להא דתנו רבנן\u0004 \u0005[מי שנה את זו ששנו חכמים]:\u0006 \u0003שמע קול קרנות\u0004 (חצוצרות) \u0003והרתיע\u0004 (רעד), שמע \u0003הגפת תריסין\u0004 (הקשת מגינים) \u0003והרתיע,\u0004 שמע \u0003צחצוח חרבות ומים\u0004 (מי רגליים) \u0003שותתין לו על ברכיו\u0004 מחמת הפחד — \u0003חוזר\u0004 מן המלחמה. \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 — \u0003לימא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 ששיטת \u0003ר' עקיבא היא\u0004 המפרש \"הירא ורך הלבב\" כמשמעו \u0003ולא\u0004 שיטת \u0003ר' יוסי הגלילי?\u0004 ומשיבים: \u0003בהא\u0004 \u0005[בזה]\u0006 \u0003אפילו ר' יוסי הגלילי מודה\u0004 שחוזר, \u0003משום דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ולא ימס את לבב אחיו כלבבו\"\u0004 (דברים כ, ח) שאדם שהכל רואים בו שהוא מפחד מאד — משפיע ומפחיד גם אחרים. שנינו במשנה: \u0003\"והיה ככלת השטרים...\"\u0004(דברים כ, ט) שתחילת ניסה נפילה. על לשון המשנה תוהים: \u0003האי\u0004 \u0005[זה,\u0006 הלשון\u0005]\u0006 \u0003מפני שתחילת ניסה נפילה,\u0004 להיפך, \u0003מפני שתחילת נפילה ניסה מבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר! ומתקנים, אכן, \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003מפני שתחילת נפילה ניסה,\u0004 וזו כוונת המשנה. על מה ששנינו במשנה \u0003\"במה דברים אמורים במלחמות הרשות\" כו', אמר ר' יוחנן:\u0004 מלחמת \u0003רשות דרבנן\u0004 \u0005[ש\u0006אמרו \u0005חכמים]\u0006 \u0003זו היא\u0004 מלחמת \u0003מצוה\u0004 שעליה דיבר \u0003ר' יהודה,\u0004 ואילו מלחמת \u0003מצוה דרבנן\u0004 \u0005[ש\u0006אומרים \u0005חכמים]\u0006 \u0003זו היא\u0004 מלחמת \u0003חובה\u0004 שעליה דיבר \u0003ר' יהודה.\u0004","","","ולפי זה בא ר' יהודה רק לומר שגם מלחמות שחכמים קוראים להן רשות — הריהן מלחמות מצוה, \u0003אמר רבא: מלחמות יהושע לכבש\u0004 את הארץ — \u0003דברי הכל\u0004 מלחמות \u0003חובה\u0004 היו, \u0003מלחמות בית דוד\u0004 שעשה לפי יוזמתו \u0003ל\u0004שם \u0003רווחה\u0004 והגדלת תחום ישראל — \u0003דברי הכל רשות\u0004 היו. \u0003כי פליגי\u0004 \u0005[כאשר\u0006 הם \u0005נחלקו]\u0006 הרי זה כשנלחמים \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003גוים\u0004 ש\u0003לא ליתי עלייהו\u0004 \u0005[יבואו עליהם],\u0006 כלומר, כאשר יוזמים מלחמה כדי למנוע מן הגוים להתקיפם. \u0003מר\u0004 \u0005[חכם זה,\u0006 ר' יהודה\u0005]\u0006 \u0003קרי\u0004 \u0005[קורא]\u0006 \u0003לה\u0004 מלחמת \u0003מצוה ומר\u0004 \u0005[וחכם זה,\u0006 חכמים\u0005]\u0006 \u0003קרי\u0004 \u0005[קורא]\u0006 לה \u0003רשות.\u0004 ומה ההבדל אם כך או כך קוראים לזה — \u0003נפקא מינה\u0004 \u0005[יוצא מזה]\u0006 \u0003ל\u0004ענין \u0003עוסק במצוה שפטור מן המצוה,\u0004 שלדעת ר' יהודה מצוה היא, ולכן גם הנלחם במלחמה כזו פטור ממצוה אחרת. \u0003א משנה\u0004 הזקנים המתוודים על \u0003עגלה ערופה, בלשון הקודש\u0004 הם אומרים, \u0003שנאמר: \"כי ימצא חלל באדמה\u0004 אשר ה' אלוהיך נותן לך לרשתה נופל בשדה לא נודע מי הכהו \u0003ויצאו זקניך ושפטיך.\u0004 כפר לעמך ישראל\u0003\"\u0004 (דברים כא, א-ב). וכיצד נעשים הדברים: \u0003שלשה מבית דין הגדול שבירושלים היו יוצאין, ר' יהודה אומר: חמשה\u0004 היו יוצאים, \u0003שנאמר \"זקניך\"\u0004 בלשון רבים — הרי \u0003שנים\u0004 לפחות, \u0003\"ושפטיך\" —\u0004 עוד \u0003שנים, ואין בית דין שקול,\u0004 שאין עושים בית דין שיהיה בו מספר זוגי של חברים כדי שאפשר יהא להכריע על פי הרוב בכל מקרה של מחלוקת, ולכן \u0003מוסיפין עליהן עוד אחד.\u0004","","","\u0003נמצא\u0004 ההרוג \u0003טמון בגל\u0004 של אבנים, \u0003או תלוי באילן, או\u0004 היה \u0003צף על פני המים —\u0004 \u0003לא היו עורפין\u0004 את העגלה, \u0003שנאמר: \"\u0004כי ימצא חלל \u0003באדמה\"\u0004 (דברים כא, א-ב) — \u0003ולא טמון בגל, \"נפל\"\u0004 — כלומר, מוטל על הארץ \u0003ולא תלוי באילן, \"בשדה\" —\u0004 \u0003ולא צף על פני המים.\u0004 \u0003נמצא\u0004 ההרוג \u0003סמוך לספר\u0004 (גבול המדינה) \u0003או\u0004 סמוך \u0003לעיר שרובה גוים, או לעיר שאין בה בית דין —\u0004 \u0003לא היו עורפין.\u0004 ועוד אמרו \u0003אין מודדין אלא לעיר שיש בה בית דין,\u0004 והערים שאין בהן בית דין אינן נחשבות.","","על המשפט הראשון במשנה שואלים: \u0003מאי קאמר\u0004 \u0005[מה אמר]\u0006 שהרי לכאורה רצה להביא ראיה שעגלה ערופה בלשון הקודש, ואין הפסוק המובא ראיה לכך! \u0003אמר ר' אבהו, הכי קאמר\u0004 \u0005[כך אמר]:\u0006 וידוי הזקנים על העגלה הערופה בלשון הקודש הוא נאמר, \u0003שנאמר: \"וענו ואמרו\"\u0004 (דברים כא, ז) \u0003ולהלן הוא אומר \"וענו הלוים ואמרו\" וגו'\u0004 (דברים כז, יד), \u0003מה\u0004 לשון \u0003\"ענייה\" האמורה להלן\u0004 בלויים — \u0003בלשון הקודש\u0004 היא, \u0003אף כאן בלשון הקודש. ו\u0004לאחר מכן מסבירה המשנה \u0003סדר עגלה ערופה כיצד —\u0004 \u0003\"כי ימצא חלל באדמה... ויצאו זקניך ושפטיך\" —\u0004 \u0003שלשה מבית דין הגדול שבירושלים היו יוצאין.\u0004 ושנינו ש\u0003ר' יהודה אומר חמשה\u0004 \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"ויצאו זקניך ושפטיך\". \"זקניך\" —\u0004 \u0003שנים, \"ושפטיך\" —\u0004 \u0003שנים, ואין בית דין שקול, מוסיפין עליהן עוד אחד, הרי כאן חמשה,\u0004 אלו \u0003דברי ר' יהודה. ר' שמעון אומר: \"זקניך\"\u0004 הם \u0003שנים, ואין בית דין שקול, מוסיפין עליהן עוד אחד, הרי כאן שלשה.\u0004","","","ושואלים: \u0003ור' שמעון נמי\u0004 \u0005[גם כן],\u0006 \u0003הא כתיב\u0004 \u0005[הרי נאמר]\u0006 גם \u0003\"ושפטיך\"!\u0004 ומשיבים: הביטוי \u0003ההוא מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 כדי \u0003ל\u0004למוד שיהיו אלה \u0003מיוחדין שבשופטיך,\u0004 לא זקנים = חכמים סתם, אלא דווקא חכמים מסנהדרין גדולה. \u0003ור' יהודה\u0004 משיב על כך: \u0003מ\u0004מה שהיה יכול לכתוב רק \u0003\"זקני\"\u0004 וכתב \u0003\"זקניך\"\u0004 ללמד שהם מיוחדים שבזקני ישראל — משם \u0003נפקא\u0004 \u0005[יוצא\u0006 הדבר\u0005].\u0006 ואומרים, \u0003ור' שמעון\u0004 משיב על כך: \u0003אי כתב רחמנא\u0004 \u0005[אילו\u0006 היתה \u0005כותבת התורה]\u0006 \u0003\"זקני\"\u0004 בלבד — \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003אפילו זקני השוק,\u0004 כלומר, סתם אנשים מכובדים, על כן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"זקניך\"\u0004 ללמד שדרושים לכך חכמים, הנחשבים בעיני הכל לזקנים. \u0003ואי כתב רחמנא\u0004 \u0005[ואילו כתבה התורה]\u0006 \u0003\"זקניך\"\u0004 בלבד — \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003אפילו סנהדרי קטנה,\u0004 על כן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"ושפטיך\",\u0004 ללמד — \u0003למיוחדין שבשופטיך,\u0004 כלומר, מסנהדרין גדולה.","","\u0003ור' יהודה גמר\u0004 \u0005[למד]\u0006 דבר זה בגזירה שווה \u0003\"זקני\" \"זקני\"\u0004 \u0003מ\u0004מה שנאמר בקרבן שמביאים סנהדרין על העלם דבר של ציבור \u0003\"זקני העדה\"\u0004 (ויקרא ד, טו), \u0003מה להלן\u0004 זקני העדה הם \u0003מיוחדין שבעדה\u0004 שהם סנהדרין גדולה — \u0003אף כאן מיוחדין שבעדה.\u0004","ושואלים: \u0003אי גמר\u0004 \u0005[אם\u0006 הוא \u0005לומד]\u0006 בגזירה שווה, אם כן \u0003לגמרה לכולה מילתא מהתם\u0004 \u0005[שילמד את כל הענין משם],\u0006 גם שצריכים חמישה דיינים, ואם כן \u0003\"זקניך ושפטיך\" למה לי? אלא\u0004 צריך לומר שלדעת ר' יהודה אף דבר זה אין למדים מגזירה שווה, ומשום כך למד הוא מ\"זקניך\" — שיהיו שניים, מ\"שופטיך\" — שיהיו מיוחדין שבשופטיך, \u0003וי\"ו\u0004 של המלה \u0003\"ושפטיך\" למנינא\u0004 \u0005[למנין]\u0006 בא, להוסיף עוד שניים. \u0003ו\u0004לעומת זאת \u0003ר' שמעון\u0004"],["\u0003וי\"ו לא משמע ליה\u0004 \u0005[נשמע לו]\u0006 כמקור לדרוש ממנו. אלא \u0003מאי קאמר רחמנא\u0004 \u0005[מה אומרת התורה]\u0006 במלה \"ושופטיך\" — \u0003המיוחדין שבשופטיך.\u0004 ומקשים: \u0003אלא מעתה\u0004 שדורשים כל לשון רבים שבפסוק להביא שני זקנים, הרי כתוב בהמשך (דברים כא, ב): \u0003\"ויצאו\"\u0004 ואם כן הרי עוד \u0003שנים, \"ומדדו\"\u0004 — עוד \u0003שנים,\u0004 ואם כן \u0003ל\u0004דברי \u0003ר' יהודה —\u0004 \u0003הרי כאן תשעה,\u0004 ו\u0003לר' שמעון הרי כאן שבעה!\u0004","ומשיבים: הכתוב \u0003ההוא\u0004 \"ויצאו... ומדדו\" \u0003מיבעי ליה לכדתניא\u0004 \u0005[צריך אותו לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003\"ויצאו\"\u0004 יש בכך הדגשה — \u0003הן ולא שלוחיהן,\u0004 כלומר, שלענין זה אינם יכולים לעשות שליח, אלא הם עצמם צריכים לצאת, \u0003\"ומדדו\" —\u0004 \u0003שאפילו נמצא\u0004 המת \u0003בעליל\u0004 (בבירור, בגלוי) סמוך \u0003לעיר\u0004 זו \u0003היו מודדין, שמצוה\u0004 מיוחדת היא \u0003לעסוק במדידה\u0004 זו.","ומעירים: \u0003מתניתין\u0004 \u0005[משנתנו\u0006 זו\u0005]\u0006 הריהי ש\u0003לא כ\u0004שיטת \u0003ר' אליעזר בן יעקב. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אליעזר בן יעקב אומר: \"זקניך\" —\u0004 \u0003זו סנהדרין, \"שפטיך\" —\u0004 \u0003זה מלך וכהן גדול.\u0004 וכיצד יודעים ששנים אלו נקראים \"שופטים\", \u0003מלך —\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"מלך במשפט יעמיד ארץ\"\u0004 (משלי כט, ד), \u0003כהן גדול —\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \"כי יפלא ממך דבר למשפט... \u0003ובאת אל הכהנים הלוים ואל השפט אשר יהיה\u0004 בימים ההם\" (דברים יז, ח-ט).","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים: \u0003ר' אליעזר בן יעקב במלך וכהן גדול\u0004 בלבד \u0003הוא דפליג\u0004 \u0005[שחולק],\u0006 שלדעתו גם הם צריכים לבוא למדידה, \u0003אבל בסנהדרי אי\u0004 \u0005[או]\u0006 \u0003כ\u0004דעת \u0003ר' יהודה אי\u0004 \u0005[או]\u0006 \u0003כ\u0004דעת \u0003ר' שמעון סבירא ליה\u0004 \u0005[סבור הוא]\u0006 שדי בשלושה או בחמישה, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003בסנהדרי נמי פליג\u0004 \u0005[גם כן חולק\u0006 הוא\u0005],\u0006 וסבור שאין המצוה מתקיימת \u0003עד דאיכא כולה סנהדרי\u0004 \u0005[שישנה כל הסנהדרין]?\u0006","\u0003אמר רב יוסף: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו: \u0003מצאן זקן ממרא\u0004 את הסנהדרין לא במקומם בלשכת הגזית אלא \u0003אבי פגי\u0004 (בבית פגי) שהיא סמוכה לירושלים \u0003והמרה עליהן\u0004 שחלק על דעתם שם, \u0003יכול תהא המראתו המראה\u0004 ויענש על כך — \u0003תלמוד לומר: \"וקמת ועלית אל המקום\"\u0004 (דברים יז, ח), \u0003מלמד שהמקום\u0004 בו יושבים הסנהדרין \u0003גורם\u0004 לדין זה של זקן ממרא שיחול.","ונברר: \u0003דנפוק\u0004 \u0005[שיצאו]\u0006 מהם מחכמי הסנהדרין \u0003כמה\u0004 לבית פגי? \u0003אילימא דנפוק\u0004 \u0005[אם תאמר שיצאו]\u0006 \u0003מקצתן,\u0004 אולם במקרה כזה אין מתחילה סברה להחשיבו כזקן ממרא, \u0003דלמא הנך דאיכא גואי כוותיה סבירא להו\u0004 \u0005[שמא אלה שנמצאים בפנים\u0006 ממקומם בלשכת הגזית — \u0005כמותו סבורים הם]\u0006 והוא מבטא את דעת הרוב! \u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 \u0003דנפוק כולהו\u0004 \u0005[שיצאו כולם].\u0006","ומעתה נברר: \u0003ולמאי\u0004 \u0005[ולמה]\u0006 לאיזו סיבה יצאו? \u0003אי\u0004 \u0005[אם]\u0006 \u0003לדבר הרשות —\u0004 \u0003מי מצו נפקי\u0004 \u0005[האם יכולים\u0006 הם \u0005לצאת]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"שררך אגן הסהר אל יחסר המזג\"\u0004 (שיר השירים ז, ג) שדרשו אותו על סנהדרין שהם שרי ישראל היושבים בחצי עיגול כחצי סהר, ולמדו מן המילים \"אל יחסר המזג\" \u0003שאם נצרך אחד מהם\u0004 מן הסנהדרין הגדולה \u0003לצאת, אם יש שם\u0004 בלשכת הגזית עדיין \u0003עשרים ושלשה כנגד\u0004 מנין של \u0003סנהדרי קטנה —\u0004 \u0003יוצא, ואם לאו\u0004 \u0005[לא] —\u0006 \u0003אינו יוצא.\u0004 משמע שחברי הסנהדרין אינם רשאים לצאת כולם לדבר הרשות!","\u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שיצאו \u0003לדבר מצוה.\u0004 ובוודאי \u0003למאי\u0004 \u0005[למה]\u0006 יצאו? \u0003לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 \u0003למדידת עגלה, ו\u0004שיטת \u0003ר' אליעזר בן יעקב היא?\u0004 ואם כן נוכיח מכאן שר' אליעזר בן יעקב סבור שסנהדרין כולה צריכה לצאת למדידה בדין עגלה ערופה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: לא,\u0004 אין זו הוכחה, \u0003דלמא\u0004 \u0005[שמא]\u0006 למצוה אחרת יצאו — \u0003להוסיף על העיר ועל העזרות. כדתנן\u0004 \u0005[כפי ששנינו\u0006 במשנה\u0005]:\u0006 \u0003אין מוסיפין\u0004 שטח מקודש \u0003על העיר\u0004 (ירושלים) \u0003ועל העזרות\u0004 של המקדש \u0003אלא ב\u0004נוכחות \u0003בית דין של שבעים ואחד.\u0004","\u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב יוסף\u0004 בדעת ר' אליעזר בן יעקב: \u0003מצאן\u0004 זקן ממרא את הסנהדרין \u0003אבית פגי והמרה עליהן, כגון שיצאו למדידת עגלה או להוסיף על העיר ועל העזרות, יכול תהא המראתו המראה —\u0004 \u0003תלמוד לומר: \"וקמת ועלית\", מלמד שהמקום גורם,\u0004 הרי שסנהדרין כולה יוצאת למדידת עגלה.","שנינו במשנה שאם \u0003נמצא\u0004 ההרוג \u0003טמון בגל או תלוי באילן\u0004 לא היו עורפים. מציעים: \u0003לימא מתניתין\u0004 \u0005[\u0006האם \u0005לומר\u0006 ש\u0005משנתנו]\u0006 זו כשיטת \u0003ר' יהודה היא ולא\u0004 כשיטת \u0003רבנן\u0004 \u0005[חכמים].\u0006 ומה ענין מחלוקת זו — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 נאמר: \u0003\"ושכחת עמר בשדה\"\u0004 (דברים כד, יט) — \u0003פרט לטמון,\u0004 שאם היה העומר טמון ומכוסה, אף ששכחו אין בו דין שיכחה, אלו \u0003דברי ר' יהודה. וחכמים אומרים:\u0004 \u0003\"בשדה\" —\u0004 \u0003לרבות את הטמון.\u0004 ואף כאן נאמר שלשיטת חכמים באה המלה \"באדמה\" לרבות הרוג שהיה טמון באדמה?","\u0003אמר רב: אפילו תימא רבנן\u0004 \u0005[תאמר\u0006 שמשנתנו כשיטת \u0005חכמים] —\u0006 אינם דורשים את שתי המילים \"באדמה\" ו\"בשדה\" בדרך אחת. כי \u0003הכא מענייניה דקרא, התם מענייניה דקרא\u0004 \u0005[כאן מעניינו של הכתוב\u0006 הם דורשים ו\u0005שם מעניינו של הכתוב\u0006 הם דורשים\u0005].\u0006","כאן, כיון \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"כי ימצא חלל\"\u0004 (דברים כא, א), משמעות הכתוב היא \u0003היכא דמשתכח\u0004 \u0005[ב\u0006כל \u0005מקום ש\u0006הוא \u0005נמצא]\u0006 וכשחוזר ואומר \u0003\"באדמה\"\u0004 יש לפרש זאת כלשון מיעוט — \u0003פרט לטמון. ו\u0004אילו \u0003התם מענייניה דקרא\u0004 \u0005[ושם\u0006 במצות שיכחה, נדרשים הכתובים \u0005מעניינו של הכתוב],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי תקצר קצירך בשדך ושכחת עמר\"\u0004 (דברים כד, יט), \u0003שכחה דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003קציר, מה קציר\u0004 נעשה בדבר הנמצא \u0003בגלוי —\u0004 \u0003אף שכחה\u0004 בדבר הנמצא \u0003בגלוי,\u0004 ולכן מה ש\u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"בשדה\"\u0004 — הרי זה בא \u0003לרבות את הטמון.\u0004","כיון שהזכרנו דרך זו של מדרש הכתוב, שואלים: \u0003לר' יהודה נמי תיפוק ליה\u0004 \u0005[גם כן תצא,\u0006 תילמד \u0005לו]\u0006 ההלכה שאמר שאין הטמון בכלל \u0003משכחה דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003קציר,\u0004 ומכאן ילמד ואינו צריך לדרוש את המלה \"בשדה\"! ומשיבים: \u0003אין הכי נמי\u0004 \u0005[כן, כך\u0006 הוא \u0005גם כן].\u0006","ושואלים: \u0003ואלא \"בשדה\",\u0004 שהוא לשון מיעוט או ריבוי \u0003למה לי?\u0004 ומשיבים: \u0003מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 הדבר \u0003לרבות שכחת קמה,\u0004 שגם אם שכח לקצור חלק מן הקמה, אף שעדיין מחוברת היא לאדמה — הרי זו שיכחה. ושואלים: \u0003ורבנן שכחת קמה מנא להו\u0004 \u0005[מניין להם]?\u0006 ומשיבים: \u0003נפקא להו\u0004 \u0005[יוצאת,\u0006 נלמדת \u0005להם]\u0006 הלכה זו \u0003מ\"כי תקצר קצירך בשדך\u0004 ושכחת\u0003\"\u0004אפילו שכח מקצת שדהו.","ושואלים: \u0003ור' יהודה\u0004 מה הוא עושה בפסוק זה? ומשיבים: \u0003מיבעי ליה\u0004 \u0005[צריך אותו]\u0006 \u0003ל\u0004כפי שאמר \u0003ר' אבהו\u0004 בשם \u0003ר' אלעזר.\u0004 ש\u0003אמר ר' אבהו אמר ר' אלעזר: פרט לשצפו\u0004 (עפו, נפלו) \u0003עומרין\u0004 משדהו \u0003לתוך שדה חבירו,\u0004 שאינם נקראים בכך שיכחה. \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מהיכן לומדים הם הלכה זו? \u0003מ\u0004מה שהיה יכול לכתוב \u0003\"בשדה\"\u0004 ונאמר \u0003\"בשדך\",\u0004 משמע: שלך ולא של אחר. ושואלים: \u0003ור' יהודה\u0004 מה למד הוא מדיוק זה? ומשיבים: הדיוק של \u0003\"בשדה\" \"בשדך\" לא משמע ליה\u0004 \u0005[אינו נשמע לו]\u0006 כדבר שאפשר ללמוד ממנו.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה: צפו עומרין לתוך שדהו,\u0004 כגון שמוטל עומר אחד על גבי חבירו, או על גבי דבר אחר, \u0003מהו\u0004 הדין? והשאלה היא: \u0003אויר\u0004 (חלל) ה\u0003שדה כשדה דמי\u0004 \u0005[נחשב],\u0006 והריהם שיכחה, \u0003או לאו\u0004 \u0005[לא]\u0006 \u0003כשדה דמי\u0004 \u0005[נחשב]\u0006 ואינם שיכחה?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב כהנא לרב פפי, ואמרי לה\u0004 \u0005[ו\u0006יש \u0005אומרים]\u0006 שאמר זאת \u0003רב כהנא לרב זביד: תפשוט ליה\u0004 \u0005[תפתור לו]\u0006 את הבעיה \u0003מ\u0004דברי \u0003ר' אבהו\u0004 ש\u0003אמר\u0004 בשם \u0003ר' אלעזר,\u0004 ש\u0003אמר: פרט לשצפו עומרין לתוך שדה חבירו.\u0004 ונלמד מדיוק הדברים: לתוך שדה של \u0003חבירו —\u0004 \u0003אין\u0004 \u0005[כן]\u0006 אין זו שיכחה, \u0003לתוך שדהו\u0004 שלו — \u0003לא\u0004 והרי זה שיכחה.","ודוחים: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 שאתה מדייק במילים הללו ולומד מהן לשלול מה שלא נאמר במפורש, הרי יכול הייתי גם לומר: \u0003לתוך שדה חבירו, צפו —\u0004 \u0003אין\u0004 \u0005[כן],\u0006 אבל אם היו \u0003מונחין\u0004 בשדה חבירו — \u0003לא?\u0004 וכי אפשר לומר כך, \u0003והא בעינן\u0004 \u0005[והרי צריכים אנו]\u0006 \u0003\"בשדך\" וליכא\u0004 \u0005[ואין כאן]!\u0006","\u0003אלא\u0004 חייב אתה לומר ש\u0003לתוך שדה חבירו\u0004 לאו דווקא צפים, מוטלים על דבר אחר, אלא \u0003ואפילו מונחין\u0004 על הקרקע, \u0003והאי דקאמר\u0004 \u0005[וזה שאמר]\u0006 \u0003צפו\u0004 הרי זה משום \u0003דלא משכחת לה\u0004 \u0005[שאין אתה מוצא אותה]\u0006 מציאות שעומרים יהיו בשדה אחר \u0003אלא בצפו,\u0004 שנפלו לשם, ואם כן אין להוכיח משם דבר לענין צפו בתוך שדהו שלו.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממקום אחר: \u0003עומר שהחזיק בו\u0004 כדי \u0003להוליכו לעיר, והניחו על גבי חבירו\u0004 (עומר אחר), \u0003ושכחו\u0004 את שני העומרים — העומר \u0003התחתון שכחה, והעליון אינו שכחה. ר' שמעון בן יהודה אומר משום\u0004 (בשם) \u0003ר' שמעון: שניהם אינן שכחה, התחתון מפני שהוא טמון, והעליון מפני שהוא צף.\u0004 ומכאן נלמד: \u0003עד כאן לא\u0004 שמענו כי \u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003אלא ב\u0004עומר \u0003תחתון, אבל בעליון —\u0004 \u0003דברי הכל לא הואי\u0004 \u0005[אינה]\u0006 \u0003שכחה,\u0004 משמע שכיון שהוא צף, כלומר, אינו נמצא על הקרקע אלא בחלל השדה, משנה את דינו ופטור משיכחה!","ודוחים: \u0003שאני התם כיון דאחזיק ביה\u0004 \u0005[שונה שם\u0006 הדין \u0005מכיון שהחזיק בו]\u0006 להוליכו העירה \u0003זכה ביה\u0004 \u0005[בו]\u0006 בעל הבית, ולא משום שהוא צף. ומקשים: \u0003אי הכי, מאי איריא\u0004 \u0005[אם כך, מדוע מדובר]\u0006 דווקא במקרה שהניחו \u0003על גבי חבירו? אפילו בשדה נמי\u0004 \u0005[גם כן]\u0006 יהיה אותו דין! ומשיבים: \u0003אין הכי נמי\u0004 \u0005[כן, כך\u0006 הוא \u0005גם כן],\u0006 \u0003והאי דקתני\u0004 \u0005[וזה ששנה]\u0006 \u0003\"על גבי חבירו\",\u0004 לא לענין העומר העליון נאמר אלא \u0003משום תחתון,\u0004 שנחלקו אם נחשב לטמון.","ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 ר' שמעון \u0003\"מפני שהוא צף\" קאמר\u0004 \u0005[אמר]!\u0006 ועונים: \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003\"מפני שהוא כצף\",\u0004 כלומר, העומר העליון נחשב כאילו לא הונח כלל אלא מצוי בידיו.","יום אחד \u0003אמר אביי: הריני\u0004 חריף ובקי \u0003כבן עזאי בשוקי טבריא\u0004 (טבריה), ואענה על כל שאלה שאשאל. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ההוא מדרבנן\u0004 \u0005[אחד החכמים]\u0006 \u0003לאביי\u0004 בענין עגלה ערופה: היו \u0003שני חללים\u0004 (הרוגים) מונחים \u0003זה על גבי זה, מהיכן,\u0004 מאיזה מהם, \u0003הוא מודד\u0004 את המרחק לערים שסביבותיהם?","וצדדי השאלה: האם אומרים ש\u0003מין במינו הוי\u0004 \u0005[הריהו\u0006 נחשב\u0005]\u0006 ל\u0003טמון, ומין במינו לא הוי\u0004 \u0005[אינו\u0006 נחשב\u0005]\u0006 ל\u0003צף,\u0004 ולכן המת התחתון אינו נחשב כיון שהוא טמון, \u0003ומעליון\u0004 הוא \u0003מודד. או דלמא\u0004 \u0005[שמא]\u0006 \u0003מין במינו הוי\u0004 \u0005[הריהו\u0006 נחשב\u0005]\u0006 \u0003צף, ומין במינו לא הוי\u0004 \u0005[אינו\u0006 נחשב\u0005]\u0006 \u0003טמון, ו\u0004לכן \u0003מתחתון\u0004 הוא \u0003מודד.\u0004","\u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003מין במינו הוי\u0004 \u0005[הריהו]\u0006 \u0003טמון, ומין במינו הוי\u0004 \u0005[הריהו]\u0006 \u0003צף, ו\u0004לכן \u0003לא מתחתון\u0004 הוא \u0003מודד ולא מעליון\u0004 הוא \u0003מודד,\u0004 שבגלל בעיה זו אין כאן אפשרות למדוד כלל?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי:"],["\u0003תניתוה\u0004 \u0005[שניתם אותה]\u0006 בברייתא את התשובה לשאלתכם: \u0003עומר שהחזיק בו להוליכו לעיר והניחו על גבי חבירו ושכחו —\u0004 \u0003התחתון שכחה והעליון אינו שכחה. ר' שמעון בן יהודה אומר משום\u0004 (בשם) \u0003ר' שמעון: שניהן אינן שכחה, התחתון מפני שהוא טמון, והעליון מפני שהוא צף. סברוה\u0004 \u0005[סברו\u0006 הלומדים\u0005]\u0006 כהנחה ראשונה \u0003דהני תנאי\u0004 \u0005[שהתנאים הללו],\u0006 חכמים ור' שמעון, בעיקרו של דבר \u0003כר' יהודה סבירא להו\u0004 \u0005[סבורים הם]\u0006 ש\u0003אמר: \"בשדה\" —\u0004 \u0003פרט לטמון.\u0004","ולפי זה \u0003מאי לאו בהא קא מיפלגי\u0004 \u0005[האם לא ב\u0006דבר \u0005זה\u0006 הם \u0005חלוקים],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 ר' שמעון, \u0005סבר]\u0006 \u0003מין במינו הוי\u0004 \u0005[הריהו]\u0006 \u0003טמון\u0004 ולכן העומר התחתון איננו שיכחה, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 חכמים, \u0005סבור]\u0006 \u0003לא הוי\u0004 \u0005[אינו]\u0006 \u0003טמון\u0004 והריהו שיכחה. ונמצא שבעיה זו שהעלו כבר נידונה על ידי התנאים.","ודוחים: \u0003לא, אי\u0004 \u0005[אם]\u0006 \u0003כ\u0004שיטת \u0003ר' יהודה סבירא להו\u0004 \u0005[סבורים הם]\u0006 אפשר לומר \u0003דכולי עלמא\u0004 \u0005[שלדעת הכל]\u0006 \u0003מין במינו הוי\u0004 \u0005[הריהו]\u0006 \u0003טמון, והכא\u0004 \u0005[וכאן]\u0006 \u0003בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של \u0003ר' יהודה ורבנן\u0004 \u0005[חכמים]\u0006 ביחס לטמון \u0003קמיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005],\u0006 \u0003דרבנן כרבנן\u0004 \u0005[שחכמים\u0006 שכאן, סבורים \u0005כשיטת חכמים\u0006 שם\u0005]\u0006 שחייב בשיכחה אף על טמון. \u0003ור' שמעון בן יהודה\u0004 סבור \u0003כ\u0004שיטת \u0003ר' יהודה\u0004 שפטור.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שמחלוקתם היא לגבי עצם דין טמון \u0003מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 חלקו בעומר שהיה \u0003על גבי חבירו? אפילו\u0004 היה מכוסה \u0003בעפר ובצרור\u0004 (אבן) \u0003נמי\u0004 \u0005[גם כן]!\u0006 ומשיבים: \u0003אין הכי נמי\u0004 \u0005[כן, כך\u0006 הוא \u0005גם כן]\u0006 שהם חלוקים בכל טמון, \u0003ו\u0004זה שנאמרה מחלוקת זו בעומר שעל גבי חבירו בא הדבר \u0003להודיעך כחו\u0004 של \u0003ר' יהודה\u0004 ש\u0003אמר: אפילו מין במינו הוי\u0004 \u0005[הריהו\u0006 נחשב\u0005]\u0006 \u0003טמון\u0004 וכל שכן כשטמון בדבר אחר.","ושוב לענין עגלה ערופה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 על הכתוב \"כי ימצא חלל באדמה... נופל בשדה\" (דברים כא, א): \u0003\"חלל\"\u0004 — זה הרוג בחרב \u0003ולא חנוק, \"חלל\"\u0004 — מת \u0003ולא מפרפר\u0004 שאינו מת לגמרי, שאם מצאו אותו כשעודו מפרפר אין בו דין זה, \u0003\"באדמה\" —\u0004 \u0003ולא טמון בגל\u0004 אבנים, \u0003\"נפל\" —\u0004 \u0003ולא תלוי באילן, \"בשדה\" —\u0004 \u0003ולא צף על פני המים. ר' אלעזר אומר: בכולן, אם היה חלל\u0004 (הרוג בחרב) — \u0003עורפין,\u0004 ואין מתחשבים במקום הימצאו.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' יוסי בר יהודה, אמרו לו\u0004 חכמים \u0003לר' אלעזר: אי\u0004 (אין) \u0003אתה מודה שאם היה חנוק ומוטל באשפה שאין עורפין? אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003חלל\u0004 האמור בכתוב הוא בלשון מדוייקת וכוונתו: \u0003ולא חנוק.\u0004 ואם כן \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 יש לדקדק בלשון: \u0003\"באדמה\" —\u0004 \u0003ולא טמון בגל, \"נפל\" —\u0004 \u0003ולא תלוי באילן, \"בשדה\" —\u0004 \u0003ולא צף על גבי מים. ור' אלעזר\u0004 סבור כי אין ממעטים דבר מלשון הפסוק, אמנם \u0003\"חלל\" יתירא כתיב\u0004 \u0005[יתר,\u0006 נוסף, \u0005כתוב]\u0006 בפרשה, ומפני שהדבר מודגש במיוחד אנו למדים ממנו למעט חנוק שאין עורפין בגללו.","שנינו במשנה: \u0003נמצא סמוך לספר\u0004 (גבול המדינה) \u0003או לעיר שרובה גוים\u0004 — לא היו עורפים, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי ימצא\"\u0004 (דברים כא, א) — \u0003פרט למצוי,\u0004 ובמקומות כאלה מצויים הרוגים.","עוד שנינו: \u0003או\u0004 שנמצא סמוך \u0003לעיר שאין בה בית דין\u0004 שלא היו מודדים אליה. ומסבירים: משום \u0003דבעינא\u0004 \u0005[שצריכים אנו]\u0006 \u0003\"זקני\u0004 (חכמי) \u0003העיר\u0004 ההיא\" (דברים כא, ג) \u0003וליכא\u0004 \u0005[ואין\u0006 כאן\u0005].\u0006 עוד שנינו: \u0003אין מודדין אלא לעיר\u0004 שיש בה בית דין. ואומרים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר, \u0003כיון דתנא\u0004 \u0005[ששנה]\u0006 \u0003לעיר שאין בה בית דין\u0004 אין מודדים — \u0003אנא ידענא\u0004 \u0005[אני יודע]\u0006 ש\u0003אין מודדין אלא לעיר שיש בה בית דין!\u0004","ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003מנין שאם נמצא\u0004 המת \u0003סמוך לעיר שאין בה בית דין, שמניחין אותה\u0004 ואין מחשיבים אותה \u0003ומודדין לעיר שיש בה בית דין —\u0004 \u0003תלמוד לומר: \"ולקחו זקני העיר ההוא\"\u0004 (דברים כא, ג) — \u0003מכל מקום\u0004 ואף שאין היא העיר הקרובה ביותר — מודדים אליה.","\u0003נמצא\u0004 החלל \u0003מכוון\u0004 (במרחק שווה בדיוק) \u0003בין שתי עיירות —\u0004 \u0003שתיהן מביאות שתי עגלות,\u0004 אלו \u0003דברי ר' אליעזר. ו\u0004עוד: \u0003אין ירושלים מביאה עגלה ערופה. נמצא ראשו\u0004 של המת \u0003במקום אחד וגופו במקום אחר —\u0004 \u0003מוליכין הראש אצל הגוף\u0004 ומודדים ממנו, אלו \u0003דברי ר' אליעזר. ר' עקיבא אומר:\u0004 מוליכים את \u0003הגוף אצל הראש. מאין\u0004 בדיוק, מאיזו נקודה בגוף \u0003היו מודדין? ר' אליעזר אומר: מטיבורו, ר' עקיבא אומר: מחוטמו, ר' אליעזר בן יעקב אומר: ממקום שנעשה חלל,\u0004 והוא \u0003מצוארו.\u0004","\u0003ד גמרא\u0004 ומבררים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' אליעזר\u0004 ביחס למת הנמצא מכוון בין שתי עיירות — \u0003קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 מצד אחד ש\u0003אפשר לצמצם,\u0004 שיש לכוון מידה שתהיה שווה בדיוק, \u0003ו\u0004מה שנאמר \u0003\"קרובה\"\u0004 אינו דווקא, אלא \u0003ואפילו קרובות,\u0004 כלומר, יותר מאחת.","טעם הלכה זו ששנינו במשנה, \u0003ואין ירושלים מביאה עגלה ערופה\u0004 הוא — ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"\u0004כי ימצא חלל באדמה אשר ה' אלוקיך נותן לך \u0003לרשתה\"\u0004 (\u0003דברים כא, א),\u0004 \u0003וקסבר\u0004 \u0005[וסבור]\u0006 תנא זה ש\u0003ירושלים לא נתחלקה\u0004 בחלוקת הארץ \u0003לשבטים\u0004 ולא היתה למורשה לשום אדם מישראל אלא נחלת הכלל, ואם כן אין מתקיים בה כתוב זה.","על המחלוקת ששנינו במשנה בענין \u0003נמצא ראשו במקום\u0004 אחד וגופו במקום אחר, שואלים: \u0003במאי קמפלגי\u0004 \u0005[במה,\u0006 באיזה ענין הם \u0005חלוקים]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 כי \u0003לענין מדידה קמיפלגי\u0004 \u0005[\u0006הם \u0005חלוקים]\u0006 אם למדוד מן הראש או מן הגוף, \u0003הא מדקתני סיפא\u0004 \u0005[הרי ממה ששנה\u0006 ב\u0005סוף]\u0006 \u0003\"מאין היו מודדין\", מכלל\u0004 הדברים אתה למד \u0003דרישא\u0004 \u0005[ש\u0006ב\u0005תחילה]\u0006 \u0003לא במדידה עסקינן\u0004 \u0005[אנו עוסקים]!\u0006 \u0003אמר ר' יצחק:\u0004 מחלוקת זו היא לענין אחר, \u0003ב\u0004דין \u0003מת מצוה קנה מקומו,\u0004 שאם מצאו אדם מת קוברים אותו במקום שנמצא בו \u0003קמיפלגי\u0004 \u0005[\u0006הם \u0005חלוקים],\u0006","\u0003והכי קאמר\u0004 \u0005[וכך אמר]:\u0006 \u0003לקוברו —\u0004 \u0003קנה\u0004 החלל את \u0003מקומו\u0004 ושם קוברים אותו, \u0003והיכא\u0004 \u0005[והיכן]\u0006 ש\u0003נמצא ראשו במקום אחד וגופו במקום אחר —\u0004 \u0003מוליכין הראש אצל הגוף\u0004 ושם קוברים אותו, אלו \u0003דברי ר' אליעזר. ר' עקיבא אומר:\u0004 מוליכים \u0003הגוף אצל הראש.\u0004 ומסבירים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון הם \u0005חלוקים] —\u0006 \u0003מר סבר:\u0004 \u0005[חכם זה,\u0006 ר' אליעזר, \u0005סבור]\u0006 \u0003גופיה בדוכתיה נפיל, רישא דנאדי ונפיל\u0004 \u0005[גופו במקומו נפל,\u0006 ואילו \u0005הראש ש\u0006הוא \u0005נייד\u0006 התגלגל \u0005ונפל],\u0006 \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' עקיבא, \u0005סבור]:\u0006 \u0003רישא היכא דנפיל נפיל, גופא הוא דרהיט אזיל\u0004 \u0005[הראש במקום שנפל נפל,\u0006 \u0005והגוף הוא שרץ והלך\u0006 הלאה\u0005],\u0006 ולכן צריכים להביא את הגוף אצל הראש.","שנינו במשנה שנחלקו בשאלה: \u0003מאין היו מודדין.\u0004 ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזו סברה הם \u0005חלוקים]?\u0006 ומסבירים: \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' עקיבא, \u0005סבור]:\u0006 \u0003עיקר חיותא באפיה\u0004 \u0005[החיות\u0006 של אדם \u0005באפו]\u0006 \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' אליעזר, \u0005סבור]:\u0006 \u0003עיקר חיותא בטיבוריה\u0004 \u0005[החיות\u0006 של אדם \u0005בטבורו].\u0006","ומציעים: \u0003לימא כי הני תנאי\u0004 \u0005[\u0006האם \u0005לומר כי\u0006 מחלוקת זו היא \u0005כ\u0006שיטת \u0005התנאים הללו]\u0006 שנחלקו בענין אחר: \u0003מהיכן הולד נוצר —\u0004 \u0003מראשו, וכן הוא אומר: \"ממעי אמי אתה גוזי\"\u0004 (תהלים עא, ו), \u0003ואומר\u0004 ראיה ש\"גוזי\" שייך לראש: \u0003\"גזי נזרך והשליכי\" וגו'\u0004 (ירמיה ז, כט). \u0003אבא שאול אומר: מטיבורו\u0004 הוא נוצר, \u0003ומשלח שרשו אילך ואילך,\u0004 ולכאורה חולקים באותו נושא, היכן עיקר החיות.","ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהתנאים במשנתנו כולם סבורים כ\u0003אבא שאול,\u0004 אולם \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[\u0006ש\u0005אמר]\u0006 \u0003אבא שאול אלא לענין יצירה, דכי מיתצר\u0004 \u0005[שכאשר נוצר]\u0006 ה\u0003ולד —\u0004 \u0003ממציעתיה מיתצר\u0004 \u0005[מאמצעו\u0006 הוא \u0005נוצר],\u0006 \u0003אבל לענין חיותא\u0004 \u0005[החיים] —\u0006 \u0003דכולי עלמא באפיה\u0004 \u0005[הכל\u0006 מודים ש\u0005באפו]\u0006 \u0003הוא, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כל אשר נשמת רוח חיים באפיו\" וגו'\u0004 (בראשית ז, כב).","שנינו במשנה שעל אותו ענין \u0003ר' אליעזר בן יעקב אומר:\u0004 מודדים \u0003ממקום שנעשה חלל —\u0004 \u0003מצוארו.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' אליעזר בן יעקב?\u0004 ומשיבים: \u0003כדכתיב\u0004 \u0005[כפי שנאמר]:\u0006 \u0003\"לתת אותך אל צוארי חללי רשעים\"\u0004 (יחזקאל כא, לד), משמע שעניינו של חלל קשור בצוואר.","לאחר המדידה \u0003נפטרו זקני ירושלים והלכו להן. זקני אותה העיר\u0004 שנמצאה קרובה \u0003מביאין עגלת בקר אשר לא משכה בעול, ואין המום פוסל בה,\u0004 שלא נאמר שצריכה להיות תמימה, \u0003ומורידין אותה לנחל איתן. \"איתן\" —\u0004 \u0003כמשמעו, קשה\u0004 שזורם בחוזקה. ומעירים: \u0003אף על פי שאינו איתן —\u0004 \u0003כשר\u0004 בדיעבד. \u0003ועורפין אותה בקופיץ\u0004 (בסכין גדולה) \u0003מאחוריה. ומקומה,\u0004 המקום שבו ערפו אותה, \u0003אסור מלזרוע ומלעבוד\u0004 בו עבודת אדמה, אבל \u0003מותר\u0004 לעשות שם שימושים אחרים, כגון לעמוד \u0003לסרוק שם פשתן\u0004 או \u0003לנקר\u0004 (לנקות ולסתת) \u0003שם אבנים.\u0004","\u0003זקני אותה העיר רוחצין את ידיהן במים במקום עריפה של עגלה, ואומרים \"ידינו לא שפכו את הדם הזה ועינינו לא ראו\"\u0004 (דברים כא, ז). ומסבירים: \u0003וכי על דעתינו עלתה שזקני בית דין שופכי דמים הן\u0004 שהם צריכים להתוודות על כך? \u0003אלא\u0004 הכוונה היא \u0003שלא בא\u0004 אותו אדם שנהרג \u0003על ידינו ופטרנוהו בלא מזון, ולא ראינוהו והנחנוהו בלא לוייה,\u0004 שדאגו לו לכל צרכיו, ואינם אשמים אפילו בעקיפין בגרימת מותו."],["\u0003והכהנים אומרים: \"כפר לעמך ישראל אשר פדית ה' ואל תתן דם נקי בקרב עמך ישראל\"\u0004 (דברים כא, ח). \u0003לא היו צריכין לומר\u0004 את סוף הפסוק \u0003\"ונכפר להם הדם\"\u0004 כי דבר זה אינו חלק מדברי הכהנים, \u0003אלא רוח הקודש מבשרתן: אימתי שתעשו ככה —\u0004 \u0003הדם מתכפר להם.\u0004","שנינו במשנה שאין המום פוסל בעגלה. ושואלים: \u0003ויהא מום פוסל בעגלה מקל וחומר: ומה פרה\u0004 אדומה \u0003שאין\u0004 מנין \u0003השנים\u0004 שלה \u0003פוסלות בה\u0004 ואפשר להביא אותה בכל גיל שהוא, בכל זאת \u0003מום פוסל בה, עגלה ששנים פוסלות בה\u0004 שאינה כשירה אלא כשהיא צעירה — \u0003אינו דין שיהא מום פוסל בה!\u0004 ומשיבים: \u0003שאני התם\u0004 \u0005[שונה\u0006 הדבר \u0005שם\u0006 בפרה אדומה\u0005]\u0006 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"אשר אין בה מום\"\u0004 (במדבר יט, ב), ויש כאן לשון מיעוט: \u0003בה\u0004 דווקא \u0003מום פוסל, ואין מום פוסל בעגלה.\u0004","ושואלים: \u0003אלא מעתה\u0004 שלשון \"בה\" ממעטת דבר שיכול להילמד בקל וחומר \u0003לא יהו שאר עבודות\u0004 שעובדים בפרה אדומה, חוץ ממשא \u0003פוסלות בה.\u0004 שאף שיש ללמוד דבר זה בקל וחומר מעגלה ערופה, מכל מקום נאמרה שם לשון מיעוט — \"אשר לא עובד בה\" (דברים כא, ג), לומר שדווקא \"בה\" בעגלה, פוסלות כל העבודות ולא בפרה.","\u0003אלמה\u0004 \u0005[מדוע]\u0006 \u0003אמר רב יהודה אמר רב:\u0004 אם \u0003הניח עליה עודה\u0004 (חבילה) \u0003של שקין\u0004 — מיד \u0003פסולה\u0004 הפרה האדומה משום שעבד בה, \u0003ובעגלה\u0004 ערופה אינה נפסלת בעבודה \u0003עד שתמשוך\u0004 ותטלטל את העול, שהרי נאמר בה \"אשר לא משכה בעול\" (דברים כא, ג)! ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 דין זה ב\u0003פרה דילפינן\u0004 \u0005[שלמדים אנו]\u0006 אותו בגזירה שווה \u0003\"על\" \"על\" מעגלה.\u0004","ומקשים: אם כן \u0003עגלה נמי תיתי\u0004 \u0005[גם כן תבוא,\u0006 תילמד\u0005]\u0006 באותה גזירה שווה \u0003\"על\" \"על\" מפרה\u0004 ויהיו מומים פוסלים בה! ומשיבים: \u0003הא מיעט רחמנא\u0004 \u0005[הרי מיעטה התורה]\u0006 דבר זה על ידי המלה \u0003\"בה\",\u0004 לומר שפסול זה של מום הוא דווקא בפרה ולא בעגלה.","ומקשים: \u0003בעגלה נמי כתיב\u0004 \u0005[גם כן נאמר]\u0006 \u0003\"בה\",\u0004 ואם כן נאמר שדווקא בה יהיו שאר עבודות פוסלות ולא בפרה אדומה! ומשיבים: \u0003ההוא\u0004 \u0005[אותו\u0006 כתוב\u0005]\u0006 (\"בה\") \u0003מיבעי ליה למעוטי\u0004 \u0005[צריך אותו למעט]\u0006 \u0003קדשים\u0004 קרבנות ש\u0003לא פסלה בהו\u0004 \u0005[פוסלת בהם]\u0006 \u0003עבודה\u0004 שאפשר להקריב גם בעל חיים שנעבדה בו עבודה. כי \u0003סלקא דעתך אמינא ליתי\u0004 \u0005[יעלה על דעתך לומר שיבוא,\u0006 יילמד\u0005]\u0006 הדבר \u0003בקל וחומר מעגלה\u0004 ערופה, וכך נלמד: \u0003ומה עגלה שאין מום פוסל בה\u0004 בכל זאת \u0003עבודה פוסלת בה, קדשים שמום פוסל בהן —\u0004 \u0003אינו דין שעבודה פוסלת בהן?\u0004 לכך נאמר \"בה\" — שדווקא עגלה נפסלת בעבודה.","על הקל וחומר הזה מעירים: \u0003איכא למיפרך\u0004 \u0005[יש\u0006 מקום \u0005לשבור,\u0006 להקשות עליו\u0005]:\u0006 \u0003מה לעגלה —\u0004 \u0003שכן שנים פוסלות בה\u0004 שאם הזקינה שוב אינה קרויה עגלה! ודוחים: \u0003אטו קדשים מי ליכא דפסלי בהו\u0004 \u0005[האם\u0006 ב\u0005קדשים אין\u0006 כאלה \u0005שפוסלים בהם]\u0006 \u0003שנים?\u0004 שהרי יש כמה קדשים שמביאים דווקא עד גיל שנה או עד גיל שנתיים, ו\u0003כי איצטריך קרא\u0004 \u0005[וכאשר נצרך הכתוב]\u0006 למעט פסול עבודה בקדשים הרי זה \u0003להנך\u0004 \u0005[לאותם]\u0006 \u0003קדשים דפסלה בהו\u0004 \u0005[שפוסלים בהם]\u0006 \u0003שנים.\u0004","ומקשים: \u0003וקדשים\u0004 ש\u0003לא פסלה בהו\u0004 \u0005[פוסלת בהם]\u0006 \u0003עבודה מהכא נפקא\u0004 \u0005[מכאן\u0006 מפסוק זה הוא \u0005יוצא,\u0006 נלמד\u0005]?\u0006 הלא \u0003מהתם נפקא\u0004 \u0005[משם,\u0006 ממקום אחר, \u0005יוצא],\u0006 שנאמר: \u0003\"עורת או שבור או חרוץ או יבלת או גרב או ילפת לא תקריבו אלה לה'\"\u0004 (ויקרא כב, כב), והרי זה מיעוט: \u0003אלה אי\u0004 (אין) \u0003אתה מקריב, אבל אתה מקריב קדשים שנעבדה בהן עבודה!\u0004 ומשיבים: \u0003איצטריך\u0004 \u0005[נצרך\u0006 הדבר\u0005]\u0006 להיאמר בשני המקומות, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שמותר להקריב קדשים שעבדו בהם נאמרו רק \u0003היכא\u0004 \u0005[במקום]\u0006 ש\u0003עבד בהן עבודת היתר, אבל\u0004 אם עבד בהם \u0003עבודת איסור\u0004 כגון עבודה בשבת \u0003אימא ליתסרו\u0004 \u0005[אמור שייאסרו]\u0006 להקרבה, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 הדבר להיאמר פעמיים.","ושואלים: \u0003והא נמי מהכא נפקא\u0004 \u0005[ו\u0006הרי דין \u0005זה\u0006 שאין עבודת איסור פוסלת בקדשים \u0005גם כן —\u0006 \u0005מכאן,\u0006 מפסוק אחר הוא \u0005יוצא],\u0006 שנאמר בענין הקרבת בעלי מומים \u0003\"ומיד בן נכר לא תקריבו את לחם אלהיכם מכל אלה\"\u0004 (ויקרא כב, כה), וההדגשה \"אלה\" באה ללמד: \u0003אלה,\u0004 בעלי המומים, \u0003אי אתה מקריב, אבל אתה מקריב קדשים שנעבדה בהן עבודה\u0004 ולמרות שמן הסתם גוי עשה בהם גם עבודת איסור!","ומשיבים: \u0003איצטריך\u0004 \u0005[נצרך]\u0006 הדבר לדין נוסף, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הני מילי היכא\u0004 \u0005[דברים אלה\u0006 שעבודה אינה פוסלת בהם, אמורים \u0005במקום]\u0006 ש\u0003עבד בהן כשהן חולין\u0004 ואחר כך הקדישם לקרבן, \u0003אבל עבד בהן כשהן\u0004 כבר \u0003קדשים —\u0004 \u0003אימא ליתסרו\u0004 \u0005[אמור שייאסרו],\u0006 על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמר הדבר פעם נוספת.","\u0003גופא\u0004 \u0005[לגופה]\u0006 של אותה הלכה שהזכרנו, \u0003אמר רב יהודה אמר רב:\u0004 פרה אדומה, אם \u0003הניח עליה עודה\u0004 (חבילה) \u0003של שקין —\u0004 \u0003פסולה,\u0004 \u0003ובעגלה\u0004 ערופה אינה פסולה \u0003עד שתמשוך. מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא: נאמר בפרה אדומה \u0003\"\u0004אשר לא עלה עליה \u0003על\"\u0004 (במדבר יט, ב), \u0003אין לי אלא עול\u0004 בלבד, \u0003שאר עבודות מנין? אמרת: קל וחומר, ומה עגלה שאין מום פוסל בה —\u0004 \u0003שאר עבודות פוסלות בה, פרה\u0004 אדומה \u0003שמום פוסל בה —\u0004 \u0003אינו דין ששאר עבודות פוסלין בה?\u0004","\u0003ואם נפשך לומר\u0004 לפרוך קל וחומר זה — למד דבר זה מגזירה שווה: \u0003נאמר כאן\u0004 בפרה אדומה \u0003\"על\" ונאמר להלן\u0004 בעגלה ערופה \u0003\"על\"\u0004 (דברים כא, ג), \u0003מה להלן\u0004 בעגלה \u0003שאר עבודות פוסלות בה —\u0004 \u0003אף כאן\u0004 בפרה \u0003שאר עבודות פוסלות.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אם נפשך לומר\",\u0004 כלומר, מה היתה הפירכא שהיתה לו על הקל וחומר הזה, שבגללה הוצרך לגזירה שווה? ומסבירים: \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003איכא למיפרך\u0004 \u0005[יש\u0006 מקום \u0005לפרוך,\u0006 לשבור\u0005]\u0006 את הקל וחומר ולומר: \u0003מה לעגלה —\u0004 \u0003שכן שנים פוסלות בה,\u0004 מה שאין כן בפרה. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 אפשר לומר: \u0003קדשים יוכיחו, שמום פוסל בהן ואין עבודה פוסלת בהן,\u0004 ואם כן הקל וחומר יכול להיפרך משני צדדים, על כן למדים בגזירה שווה:","\u0003נאמר כאן \"על\" ונאמר להלן \"על\", מה להלן\u0004 בעגלה \u0003שאר עבודות —\u0004 \u0003אף כאן\u0004 בפרה \u0003שאר עבודות.\u0004 ושואלים על דרשה זו: \u0003וממקום שבאתה,\u0004 כלומר, מהמקום שממנו למדת, מעגלה ערופה, אתה לומד גם דבר אחר, \u0003מה להלן\u0004 בעגלה אינה נפסלת בעבודת משא \u0003עד שתמשוך\u0004 בעול, \u0003אף כאן\u0004 בפרה \u0003עד שתמשוך,\u0004 ובניגוד לדברי רב!","ומשיבים: \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא, דאיכא דמייתי לה\u0004 \u0005[שיש שמביאים,\u0006 לומדים הלכה \u0005זו]\u0006 שעבודה פוסלת בפרה בגזירה שווה \u0003מעגלה\u0004 ואינם פוסלים עד שתמשוך בעול, \u0003איכא דמייתי לה מגופה דפרה\u0004 \u0005[יש שמביאים,\u0006 לומדים \u0005אותה מפרה עצמה],\u0006 והם פוסלים גם אם לא משכה בעול.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 בענין פרה אדומה: \u0003\"על\", אין לי אלא עול\u0004 שפוסל בה, \u0003שאר עבודות מנין —\u0004 \u0003תלמוד לומר: \"אשר לא עלה עליה על\"\u0004 (במדבר יט, ב) \u0003מכל מקום,\u0004 לרבות כל עבודה. \u0003אם כן מה תלמוד לומר \"על\",\u0004 אם לא רק עול פוסל אלא גם שאר העבודות — ללמד: \u0003עול\u0004 שמניחים עליה \u0003פוסל\u0004 אותה \u0003בין בשעת עבודה בין שלא בשעת עבודה\u0004 אלא בהנחה בלבד, \u0003שאר עבודות אין פוסלות אלא בשעת עבודה\u0004 ולפי שיטה זאת פסק רב.","ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 ודרוש פסוק זה עצמו באופן אחר: \u0003\"אשר לא עלה עליה\"\u0004 — הרי זה \u0003כלל\u0004 ואוסר כל עבודה, \u0003\"על\" —\u0004 \u0003פרט,\u0004 הרי יש כאן \u0003כלל ופרט,\u0004 ולפי כללי מדרש ההלכה \u0003אין בכלל אלא מה שבפרט,\u0004 ונאמר: \u0003עול —\u0004 \u0003אין\u0004 \u0005[כן],\u0006 \u0003מידי אחרינא\u0004 \u0005[דבר אחר] —\u0006 \u0003לא!\u0004 ומתרצים: \u0003\"אשר\u0004 לא עלה \u0003\"\u0004— לשון \u0003רבויא\u0004 \u0005[ריבוי]\u0006 \u0003הוא\u0004 ואינו מדין כלל ופרט.","ומעירים: \u0003ותניא נמי\u0004 \u0005[ושנויה גם כן\u0006 ברייתא\u0005]\u0006 ל\u0003גבי עגלה כי האי גוונא\u0004 \u0005[כגון זה]:\u0006 \u0003\"על\", אין לי אלא עול, שאר עבודות מנין —\u0004 \u0003תלמוד לומר: \"אשר לא עבד בה\"\u0004 (דברים כא, ג) \u0003מכל מקום. אם כן מה תלמוד לומר \"על\"\u0004 — ללמד: \u0003עול פוסל בין בשעת עבודה בין שלא בשעת עבודה, שאר עבודות אין פוסלות אלא בשעת עבודה.\u0004","ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 \u0003\"אשר לא עבד בה\"\u0004 הרי זה \u0003כלל, \"על\"\u0004 הוא \u0003פרט,\u0004 ונדרוש: \u0003כלל ופרט, אין בכלל אלא מה שבפרט: עול —\u0004 \u0003אין\u0004 \u0005[כן],\u0006 \u0003מידי אחרינא\u0004 \u0005[דבר אחר] —\u0006 \u0003לא!\u0004 ומתרצים: \u0003\"אשר\u0004 לא עובד בה \u0003\"\u0004לשון \u0003רבויא\u0004 \u0005[ריבוי]\u0006 \u0003הוא.\u0004","\u0003אמר ר' אבהו: בעי מיניה\u0004 \u0005[שאלתי אותו]\u0006 \u0003מר' יוחנן: משיכת עול\u0004 זו הפוסלת עגלה \u0003בכמה,\u0004 מה שיעורה, המרחק שהיא צריכה למשוך בעול כדי להיפסל? \u0003אמר לי: כמלא\u0004 (כשיעור) גודל ה\u0003עול. איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 האם מדובר פה \u0003לארכו\u0004 של עול \u0003או לרחבו? אמר להו\u0004 \u0005[להם]\u0006 \u0003ההוא מרבנן\u0004 \u0005[אחד החכמים]\u0006 \u0003ור' יעקב שמיה\u0004 \u0005[שמו]:\u0006 \u0003לדידי מפרשא לי מיניה\u0004 \u0005[לי נתפרש\u0006 הדבר \u0005ממנו]\u0006 מ\u0003ר' יוחנן\u0004 עצמו: \u0003משיכת עול לרחבו\u0004 שהיא \u0003טפח.\u0004","ושואלים: כיון שאמר שיעור קצוב לזה, \u0003ולימא\u0004 \u0005[ושיאמר]\u0006 רק \u0003טפח\u0004 ומדוע הוסיף איפוא כמלוא העול? ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 כי \u0003שיעורא\u0004 \u0005[שיעורו]\u0006 של \u0003עול\u0004 ברוחבו — \u0003טפח הוי\u0004 \u0005[הוא].\u0006 \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה] —\u0006 \u0003למקח וממכר,\u0004 שיכול הקונה לחזור בו אם אין רוחבו של העול מגיע לטפח.","\u0003אמר ר' יוחנן בן שאול, מפני מה אמרה תורה: הביא עגלה בנחל? אמר הקדוש ברוך הוא: יבא דבר שלא עשה פירות,\u0004 כלומר, העגלה הזאת שלא ילדה עדיין \u0003ויערף במקום שאין עושה פירות\u0004 בנחל איתן, \u0003ויכפר על מי שלא הניחו\u0004 להרוג \u0003לעשות פירות.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 הם\u0005]\u0006 \u0003פירות\u0004 אלה שלא הניחו לו לעשות? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003פריה ורביה,\u0004 שלא הניחו לו להוליד עוד ילדים — \u0003אלא מעתה\u0004 על חלל \u0003זקן ו\u0004על חלל \u0003סריס הכי נמי דלא ערפינן\u0004 \u0005[כך גם כן\u0006 תאמר \u0005שאין עורפים]\u0006 את העגלה, שהרי אינם יכולים להוליד עוד ילדים?! \u0003אלא\u0004 הכוונה היא \u0003מצות,\u0004 ופירות אלה ודאי לא הניחו לו לעשות.","\u0003שנינו במשנה:\u0004 \u0003ומורידין אותה אל נחל איתן. \"איתן\" כמשמעו, קשה. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מנין לאיתן שהוא קשה —\u0004 \u0003שנאמר:\u0004"],["\u0003\"איתן מושבך ושים בסלע קנך\"\u0004 (במדבר כד, כא), \u0003ואומר: \"שמעו הרים את ריב ה' והאתנים מסדי ארץ\"\u0004 (מיכה ו, ב) ומן ההקבלה שבתוך הפסוקים אפשר ללמוד ש\"איתן\" הוא קשה, כמו סלע או הר. \u0003אחרים אומרים: מנין ל\"איתן\" שהוא ישן —\u0004 \u0003שנאמר: \"גוי איתן הוא, גוי מעולם הוא\"\u0004 (ירמיה ה, טו).","שנינו: \u0003\"ועורפין אותה בקופיץ מאחוריה\".\u0004 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003גמר\u0004 \u0005[למד]\u0006 בגזירה שווה \u0003עריפה עריפה מחטאת העוף\u0004 שגם בה נזכר שורש \"ערף\" (\"ומלק את ראשו ממול ערפו\". ויקרא ה, ח), שעריפה אינה אלא מן העורף.","עוד שנינו במשנה: \u0003\"ומקומה,\u0004 מקום עריפת העגלה, \u0003אסור מלזרוע ומליעבד\". תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מה שנאמר \u0003\"אשר לא יעבד בו ולא יזרע\"\u0004 (דברים כא, ד), מדובר \u0003לשעבר,\u0004 כלומר, מקום שלא עבדו ולא זרעו בו קודם לכן, אלו \u0003דברי ר' יאשיה. ר' יונתן אומר: להבא,\u0004 כלומר, שאסור לזרוע ולעבוד בו מאז והלאה.","\u0003רבא אמר: להבא —\u0004 \u0003דכולי עלמא לא פליגי\u0004 \u0005[הכל אינם חולקים]\u0006 שאסור בזריעה ועבודה, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ולא יזרע\"\u0004 בלשון עתיד, \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה לגבי \u0003לשעבר. ר' יאשיה\u0004 האוסר מקום שנעבד בעבר, \u0003סבר: מי כתיב\u0004 \u0005[האם כתוב]\u0006 בלשון ציווי לעתיד \u0003\"ולא יעובד\"? ור' יונתן\u0004 אומר: \u0003מי כתיב\u0004 \u0005[האם כתוב]\u0006 בלשון עבר \u0003\"אשר לא נעבד\"? ור' יאשיה\u0004 אומר על כך: \u0003\"אשר\" —\u0004 \u0003לשעבר משמע, ור' יונתן\u0004 סבור כי \u0003\"אשר\"\u0004 לשון \u0003רבויא\u0004 \u0005[ריבוי]\u0006 \u0003הוא,\u0004 כפי שיתבאר להלן, ואין במשמעותו לשון עבר.","שנינו במשנה ש\u0003מותר לסרוק שם פשתן ולנקר שם אבנים. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מה שנאמר \u0003\"אשר לא יעבד בו ולא יזרע\" —\u0004 \u0003אין לי אלא זריעה, שאר עבודות\u0004 שאסור גם כן לעשות בו \u0003מנין? תלמוד לומר: \"אשר לא יעבד בו\" מכל מקום.\u0004","\u0003אם כן מה תלמוד לומר \"ולא יזרע\"\u0004 אחרי שאמר כבר בלשון כללית \"לא יעבד\"? \u0003לומר לך: מה זריעה מיוחדת שהיא\u0004 מלאכה \u0003בגופה של קרקע אף כל\u0004 מלאכה \u0003שהיא\u0004 דווקא \u0003בגופה של קרקע\u0004 — אסורה, \u0003יצא סריקת פשתן וניקור אבנים שאינן\u0004 מלאכות הנעשות \u0003בגופה של קרקע.\u0004","ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 ודרוש את הפסוק אחרת: \u0003\"אשר לא יעבד בו\"\u0004 הוא \u0003כלל, \"ולא יזרע\"\u0004 הרי \u0003פרט,\u0004 ואמרו חכמים שכל מקום בו נאמרו \u0003כלל ופרט —\u0004 \u0003אין בכלל אלא מה שבפרט; זריעה —\u0004 \u0003אין\u0004 \u0005[כן]\u0006 אסורה, \u0003מידי אחרינא\u0004 \u0005[דבר אחר] —\u0006 \u0003לא!\u0004 ומתרצים: \u0003\"אשר\"\u0004 לשון \u0003רבויא\u0004 \u0005[ריבוי]\u0006 \u0003הוא,\u0004 שבא לרבות כל מלאכה, ולא בא הפרט אלא להגדיר את סוגי המלאכות האסורות.","שנינו: \u0003\"זקני העיר רוחצין ידיהן\" כו'. תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 נאמר: \u0003\"וכל זקני העיר ההיא הקרבים אל החלל ירחצו את ידיהם על העגלה הערופה בנחל\"\u0004 (דברים כא, ו). \u0003שאין תלמוד,\u0004 לא צריך היה, \u0003לומר \"הערופה\"\u0004 שהרי בעגלה זו אנו מדברים, \u0003ומה תלמוד לומר \"הערופה\"\u0004 — הכוונה היא שירחצו את ידיהם \u0003על מקום עריפתה של עגלה.\u0004","\u0003עוד שנינו במשנה על הנאמר\u0004 \u0003\"ואמרו ידינו לא שפכו את הדם הזה ועינינו לא ראו\", וכי על לבנו עלתה שבית דין שופכין דמים\u0004 שצריכים הם לומר שאינם כאלה? \u0003אלא, לא בא לידינו ופטרנוהו\u0004 והכוונה היא: \u0003בלא מזונות ולא ראינוהו והנחנוהו —\u0004 \u0003בלא לויה\u0004 שלא גרמו לכך אף בעקיפין.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003היה ר' מאיר אומר: כופין ללויה,\u0004 כלומר, כופים את מי שאינו רוצה ללוות את חבירו, שילווהו, כיון \u0003ששכר הלויה אין לה שיעור,\u0004 וראיה לדבר \u0003שנאמר: \"ויראו השמרים איש יוצא מן העיר ויאמרו לו הראנו נא את מבוא העיר ועשינו עמך חסד\"\u0004 (שופטים א, כד) \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויראם את מבוא העיר\"\u0004 (שופטים א, כה), \u0003ומה חסד עשו עמו —\u0004 \u0003שכל אותה העיר הרגו לפי חרב, ואותו האיש ומשפחתו שלחו.\u0004","ונאמר: \u0003\"וילך האיש ארץ החתים ויבן עיר ויקרא שמה לוז הוא שמה עד היום הזה\"\u0004 (שופטים א, כו) ועל כך \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003היא לוז שצובעין בה תכלת, היא לוז שבא סנחריב\u0004 שהגלה עמים רבים ממקום למקום \u0003ולא בלבלה\u0004 ולא הגלה אותה ממקומה, בא \u0003נבוכדנצר\u0004 שכבש והחריב ארצות רבות \u0003ולא החריבה, ואף מלאך המות אין לו רשות לעבור בה. אלא זקנים שבה, בזמן שדעתן קצה עליהן\u0004 בחייהם, \u0003יוצאין חוץ לחומה והן מתים.\u0004","\u0003והלא דברים קל וחומר: ומה כנעני זה שלא דיבר בפיו\u0004 ולא אמר במפורש היכן מבוא העיר, \u0003ולא הלך ברגליו\u0004 אלא רק הראה להם את הדרך — \u0003גרם הצלה לו ולזרעו עד סוף כל הדורות,\u0004 \u0003מי שעושה לויה\u0004 לחבירו \u0003ברגליו על אחת כמה וכמה\u0004 ששכרו גדול.","ושואלים: \u0003במה הראה להם\u0004 אותו איש את הדרך לעיר? \u0003חזקיה אמר: בפיו עקם להם,\u0004 כלומר, על ידי עקימת פיו, בתנועות שפתיו, הראה להם היכן המבוא, \u0003ר' יוחנן אמר: באצבעו\u0004 בלבד \u0003הראה להם. תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' יוחנן: בשביל שכנעני זה הראה באצבעו, גרם הצלה לו ולזרעו עד סוף כל הדורות.\u0004","\u0003אמר ר' יהושע בן לוי: המהלך בדרך ואין לו לויה,\u0004 שאין מי שילווה אותו — \u0003יעסוק בתורה, שנאמר\u0004 בדברי תורה: \u0003\"כי לוית חן הם לראשך וענקים לגרגרתיך\"\u0004 (משלי א, ט). \u0003ו\u0004עוד \u0003אמר ר' יהושע בן לוי: בשביל ארבעה פסיעות שלוה פרעה לאברהם, שנאמר: \"ויצו עליו פרעה אנשים\" וגו'\u0004 (בראשית יב, כ) \u0003נשתעבד בבניו ארבע מאות שנה שנאמר: \"ועבדום וענו אתם ארבע מאות שנה\"\u0004 (בראשית טו, יג). \u0003אמר רב יהודה אמר רב: כל המלוה את חבירו ארבע אמות בעיר —\u0004 \u0003אינו ניזוק\u0004 באותו ליווי. מסופר: \u0003רבינא אלויה\u0004 \u0005[ליווהו]\u0006 \u0003לרבא בר יצחק ארבע אמות בעיר, מטא לידיה היזיקא ואיתציל\u0004 \u0005[הגיע לידיו היזק וניצל\u0006 ממנו\u0005].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הרב\u0004 מלווה \u0003לתלמיד —\u0004 \u0003עד עיבורה\u0004 (קצה האחרון) \u0003של עיר, חבר לחבר\u0004 מלווה אותו \u0003עד תחום שבת\u0004 של אותה עיר (שהוא מיל), \u0003תלמיד לרב —\u0004 \u0003אין לו שיעור\u0004 ללוותו. ושואלים: \u0003וכמה?\u0004 הרי בודאי אין מדובר פה שילווה אותו כל דרכו. \u0003אמר רב ששת: עד פרסה,\u0004 שהיא ארבעה מילין. ומעירים: \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 שיעור זה \u0003אלא\u0004 ללוות את \u0003רבו שאינו מובהק, אבל\u0004 את \u0003רבו מובהק\u0004 מלווה \u0003שלשה פרסאות.\u0004","מסופר: \u0003רב כהנא אלויה\u0004 \u0005[ליווהו]\u0006 \u0003לרב שימי בר אשי מ\u0004העיר \u0003פום נהרא עד בי ציניתא\u0004 \u0005[\u0006מקום \u0005הדקלים]\u0006 של \u0003בבל. כי מטו התם\u0004 \u0005[כאשר הגיעו לשם]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב כהנא לרב שימי בר אשי: \u0003ודאי דאמריתו הני ציניתא\u0004 \u0005[ה\u0006אם \u0005נכון\u0006 הוא \u0005שאתם אומרים\u0006 ש\u0005אותם דקלים]\u0006 של \u0003בבל משני\u0004 \u0005[משנותיו,\u0006 מימיו\u0005]\u0006 של \u0003אדם הראשון איתנהו\u0004 \u0005[ישנם]\u0006 שם?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב שימי בר אשי: \u0003אדכרתן מלתא\u0004 \u0005[הזכרת לי\u0006 על ידי כך \u0005דבר]\u0006 ש\u0003אמר ר' יוסי בר' חנינא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"בארץ לא עבר בה איש ולא ישב אדם שם\"\u0004 (ירמיה ב, ו), ולכאורה תמוה: \u0003וכי מאחר שלא עבר\u0004 בה איש — \u0003היכן ישב (ומאחר שלא ישב היכן עבר)\u0004 ומה צורך בתוספת זו בכתוב? \u0003אלא\u0004 הכוונה היא: \u0003ארץ שגזר עליה אדם הראשון לישוב —\u0004 \u0003נתישבה, ארץ שלא גזר עליה אדם הראשון —\u0004 \u0003לא נתישבה.\u0004","וכיוצא בו מסופר ש\u0003רב מרדכי אלויה\u0004 \u0005[ליווהו]\u0006 \u0003לרב אשי מ\u0004העיר \u0003הגרוניא ועד בי כיפי, ואמרי לה\u0004 \u0005[ו\u0006יש \u0005אומרים]\u0006 \u0003עד בי דורא\u0004 ליווה אותו.","\u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' מאיר: כל שאינו מלוה\u0004 את חבירו \u0003ו\u0004אינו \u0003מתלוה\u0004 שאינו מוכן שילווהו — \u0003כאילו שופך דמים,\u0004 וראיה לדבר \u0003שאילמלי ליווהו אנשי יריחו לאלישע לא גירה דובים לתינוקות, שנאמר:\u0004 \u0003\"ויעל משם בית אל והוא עלה בדרך ונערים קטנים יצאו מן העיר ויתקלסו בו ויאמרו לו עלה קרח עלה קרח\"\u0004 (מלכים ב ב, כג), שאילו היו מלווים אותו היו מגרשים את הנערים הקטנים.","אגב כך מפרשים מה כוונת דבריהם, \u0003אמרו לו: עלה\u0004 צא מכאן, \u0003שהקרחת עלינו את המקום,\u0004 שגרמת לנו נזק, משום שהם היו מתפרנסים מהספקת מים טובים ליריחו והוא המתיק את המים שבתוך העיר, ולא היה עוד צורך בהם. ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"ונערים קטנים\"\u0004 שלכאורה צריך היה לכתוב או נערים או קטנים (ילדים)? \u0003אמר ר' אלעזר\u0004 הכוונה היא: \"נערים\" — \u0003שמנוערים מן המצות, \"קטנים\" —\u0004 \u0003שהיו מקטני אמנה\u0004 שלא האמינו שתבוא להם פרנסה ממקום אחר. \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003נערים היו,\u0004 כלומר, גדולים בשנים \u0003ובזבזו\u0004 (וביזו) \u0003עצמן כקטנים.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב יוסף: ודלמא\u0004 \u0005[ושמא]\u0006 \u0003על שם מקומן\u0004 נקראו נערים? \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"וארם יצאו גדודים וישבו מארץ ישראל נערה קטנה\"\u0004 (מלכים ב ה, ב), \u0003וקשיא לן\u0004 \u0005[ו\u0006היה \u0005קשה לנו]:\u0006 \"\u0003נערה\" ו\"קטנה\",\u0004 כיצד יכולים שני הדברים להיות יחד? \u0003ואמר ר' פדת: קטנה\u0004 ש\u0003מן\u0004 העיר \u0003נעורן,\u0004 ואף פה נפרש כך! ומשיבים: אי אפשר לומר כן, כי \u0003התם\u0004 \u0005[שם]\u0006 \u0003לא מפרש מקומה,\u0004 ולכן אפשר לומר ש\"נערה\" פירושה מהעיר נעורן, אבל \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003מפורש מקומן\u0004 שהם מיריחו.","עוד נאמר שם \u0003\"ויפן אחריו ויראם ויקללם בשם ה'\"\u0004 (מלכים ב ב, כד). ושואלים: \u0003מה ראה? אמר רב: ראה ממש,\u0004 כלומר, הביט, נעץ עיניו בהם. \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005],\u0006 \u0003רבן שמעון בן גמליאל אומר: כל מקום\u0004 שנאמר \u0003שנתנו חכמים עיניהם\u0004 באדם מסויים — \u0003או\u0004 שנגרמה לו \u0003מיתה, או\u0004 שנגרם לו \u0003עוני. ושמואל אמר: ראה\u0004 את מהותם, \u0003שכולן נתעברה בהן אמן ביום הכיפורים\u0004 שאסור בתשמיש המיטה.","\u0003ור' יצחק נפחא אמר: בלורית ראה להן,\u0004 שהם מגדלים שער \u0003כגוים. ור' יוחנן אמר: ראה שלא היתה בהן לחלוחית של מצוה.\u0004 ושואלים על פירושו של ר' יוחנן: אם זאת היתה הסיבה שקללם, \u0003ודלמא בזרעייהו ניהוה הוה\u0004 \u0005[ושמא בזרעם תהיה]\u0006 לחלוחית של מצוה? \u0003אמר ר' אלעזר:\u0004 ראה בנבואה שלא תהיה לחלוחית של מצוה \u0003לא בם ולא בזרעם עד סוף כל הדורות.\u0004","נאמר \u0003\"ותצאנה שתים דבים מן היער ותבקענה מהם ארבעים ושני ילדים\"\u0004 (מלכים ב ב, כד)"],["\u0003רב ושמואל\u0004 נחלקו בכך, \u0003חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר: נס\u0004 היה זה. \u0003וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר: נס בתוך נס.\u0004 ומסבירים: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שהיה זה \u0003נס —\u0004 \u0003יער הוה\u0004 \u0005[היה]\u0006 באותו מקום, אבל \u0003דובים לא הוו\u0004 \u0005[היו]\u0006 שם ונעשה נס ונוצרו. \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שהיה זה \u0003נס בתוך נס —\u0004 \u0003לא יער הוה\u0004 \u0005[היה]\u0006 שם \u0003ולא דובים הוו\u0004 \u0005[היו]\u0006 שם. ושואלים: ולמה הוצרך לעשות נס בתוך נס? \u0003וליהוי\u0004 \u0005[ושיהיו]\u0006 \u0003דובים ו\u0004ש\u0003לא ליהוי\u0004 \u0005[יהיה]\u0006 \u0003יער\u0004 שעצם היער לא היה בו נס כלל! ומסבירים: \u0003דבעיתי\u0004 \u0005[ש\u0006הדובים \u0005מפחדים]\u0006 בשטח גלוי. אבל בתוך היער, שהוא מקומם, הם מתנפלים אפילו על בני אדם.","\u0003אמר ר' חנינא: בשביל ארבעים ושנים קרבנות שהקריב בלק מלך מואב\u0004 כאשר ביקש בלעם לקלל את ישראל \u0003הובקעו מישראל ארבעים ושנים ילדים\u0004 באותו מעשה עם אלישע. ושואלים: \u0003איני\u0004 \u0005[\u0006וכי \u0005כן הוא]?\u0006 האם לכך הביאו הקרבנות שהקריב?","\u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יהודה אמר רב: לעולם יעסוק אדם בתורה ובמצות, ואף על פי\u0004 שעוסק בהם \u0003שלא לשמה. שמתוך שלא לשמה בא לשמה. ש\u0004הרי \u0003בשכר ארבעים ושנים קרבנות שהקריב בלק מלך מואב זכה ויצתה\u0004 (יצאה) \u0003ממנו רות שיצא ממנו שלמה\u0004 שהקריב גם הוא הרבה קרבנות, \u0003שכתוב ביה\u0004 \u0005[בו]\u0006 \u0003\"אלף עלות יעלה שלמה\"\u0004 (מלכים א ג, ד). \u0003ו\u0004כן \u0003אמר ר' יוסי בן חוני: רות בתו של עגלון בנו של בלק היתה!\u0004 ומשיבים: \u0003תאותו מיהא\u0004 \u0005[על כל פנים]\u0006 \u0003לקללה הוי\u0004 \u0005[היתה]\u0006 ולכן גרם הדבר גם קללה.","נאמר שם: \u0003\"ויאמרו אנשי העיר אל אלישע הנה נא מושב העיר טוב כאשר אדני ראה\u0004 והמים רעים והארץ משכלת\u0003\"\u0004 (מלכים ב ב, יט), ושואלים: \u0003וכי מאחר\u0004 ש\u0003מים רעים וארץ משכלת, אלא מה טובתה? אמר ר' חנין: חן מקום על יושביו,\u0004 שלמרות החסרונות אנשים אוהבים את מקומם. \u0003אמר ר' יוחנן: שלשה חינות הן\u0004 שפועלות בצורה דומה: \u0003חן מקום על יושביו, חן אשה על בעלה\u0004 למרות שיכולים להיות בה חסרונות, \u0003חן מקח על מקחו\u0004 חן של הדבר על זה שקנה אותו, שהוא טוב בעיניו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שלשה חלאין חלה אלישע: אחד\u0004 כעונש על \u0003שגירה דובים בתינוקות, ואחד\u0004 נענש על \u0003שדחפו לגחזי בשתי ידים\u0004 ולא הניח לו דרך לחזור בו, \u0003ואחד שמת בו, שנאמר\u0004 בו חולי שלוש פעמים: \u0003\"ואלישע חלה את חליו אשר ימות בו\"\u0004 (מלכים ב יג, יד).","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003לעולם תהא שמאל דוחה וימין מקרבת\u0004 שגם אם דוחים תלמיד, עדיין צריכים לתת לו פתח לחזור בו, \u0003לא כאלישע שדחפו לגחזי בשתי ידיו, ולא כיהושע בן פרחיה שדחפו לישו הנוצרי בשתי ידיו.\u0004","ומפרשים: \u0003אלישע מאי היא\u0004 \u0005[מה היה]\u0006 המעשה, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויאמר נעמן\u0004 (לגיחזי) \u0003הואל קח ככרים\"\u0004 (מלכים ב ה, כג) \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויאמר אליו\u0004 (אלישע לגיחזי) \u0003לא לבי הלך כאשר הפך איש מעל מרכבתו לקראתך העת לקחת את הכסף ולקחת בגדים וזיתים וכרמים וצאן ובקר ועבדים ושפחות\"\u0004 (מלכים ב ה, כו).","ושואלים: \u0003ומי שקיל כולי האי\u0004 \u0005[והאם לקח\u0006 את \u0005כל זה]\u0006 הלא רק \u0003כסף ובגדים הוא דשקיל\u0004 \u0005[שלקח]!\u0006 \u0003אמר ר' יצחק: באותה שעה היה אלישע עוסק ב\u0004סוגיה של \u0003שמנה שרצים\u0004 המטמאים, \u0003אמר לו\u0004 לגיחזי: \u0003רשע, הגיע עת\u0004 עבורך \u0003ליטול\u0004 בעולם הזה \u0003שכר שמנה שרצים\u0004 שעסקת בסוגיה זו, וכנגד זה קיבל שמונה דברים. \u0003\"וצרעת נעמן תדבק בך ובזרעך לעולם\"\u0004 (מלכים ב ה, כז). בענין זה מביאים כי לאחר אותו ענין נאמר \u0003\"וארבעה אנשים היו מצרעים\"\u0004 (מלכים ב ז, ג) ועל כך \u0003אמר ר' יוחנן: זה גחזי ושלשת בניו.\u0004","נאמר \u0003\"ויבא אלישע דמשק\"\u0004 (מלכים ב ח, ז) ושואלים: \u0003למה הלך\u0004 לשם? \u0003אמר ר' יוחנן: שהלך להחזירו לגחזי בתשובה, ולא חזר\u0004 בו. \u0003אמר לו: חזור בך. אמר לו\u0004 גיחזי: \u0003כך מקובלני ממך, כל מי שחטא והחטיא את הרבים —\u0004 \u0003אין מספיקין בידו לעשות תשובה.\u0004","ושואלים: \u0003מאי עבד\u0004 \u0005[מה עשה]\u0006 גיחזי שהחטיא את הרבים? \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003אבן שואבת תלה לו לחטאת\u0004 (עגל) \u0003ירבעם, והעמידו\u0004 בדרך זו \u0003בין שמים לארץ,\u0004 ועל ידי כך היה נראה דבר מופלא והיו עובדים אותו יותר. \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]:\u0006 \u0003שם\u0004 קדוש \u0003חקק לה\u0004 לאותה עבודה זרה \u0003אפומה\u0004 \u0005[על פיה]\u0006 \u0003והיתה אומרת \"אנכי\" ו\"לא יהיה לך\".\u0004","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]:\u0006 \u0003רבנן דחה מקמיה\u0004 \u0005[חכמים דחה מלפניו]\u0006 ולא הניחם לבוא אל אלישע, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 לאחר אותה פרשה: \u0003\"ויאמרו בני הנביאים אל אלישע הנה נא המקום אשר אנחנו ישבים שם לפניך צר ממנו\"\u0004 (מלכים ב ו, א), \u0003מכלל\u0004 ש\u0003עד האידנא\u0004 \u0005[עכשיו]\u0006 \u0003לא הוה דחיק\u0004 \u0005[היה דחוק]\u0006 המקום, ומדוע — מפני שכל עוד היה גיחזי שם היה דוחה אותם.","\u0003יהושע בן פרחיה מאי היא\u0004 \u0005[מה היה]\u0006 המעשה — \u0003כדהוה קא קטיל ינאי מלכא לרבנן\u0004 \u0005[כאשר היה הורג ינאי המלך את החכמים],\u0006 \u0003שמעון בן שטח אטמינהו אחתיה\u0004 \u0005[הטמינה אותו אחותו]\u0006 שהיתה אשתו של ינאי, \u0003ואילו\u0004 \u0003ר' יהושע בן פרחיה אזל ערק\u0004 \u0005[הלך ברח]\u0006 \u0003לאלכסנדריא של מצרים. כי הוה שלמא\u0004 \u0005[כאשר נעשה שלום]\u0006 בין ינאי והחכמים, \u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003שמעון בן שטח\u0004 לר' יהושע מכתב זה: \u0003מני\u0004 (ממני) \u0003ירושלים עיר הקודש לך אלכסנדריא של מצרים: אחותי! בעלי שרוי בתוכך ואני יושבת שוממה. אמר\u0004 ר' יהושע בן פרחיה: \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 מרמז זה \u0003הוה ליה שלמא\u0004 \u0005[יש לו שלום]\u0006 ואפשר לחזור.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 ר' יהושע חזרה לארץ ישראל \u0003אקלע לההוא אושפיזא\u0004 \u0005[נזדמן לפונדק אחד]\u0006 \u0003קם קמייהו ביקרא שפיר, עבדי ליה יקרא טובא\u0004 \u0005[עמד לפניהם בכבוד יפה,\u0006 ו\u0005עשו לו כבוד הרבה],\u0006 \u0003יתיב וקא משתבח\u0004 \u0005[ישב\u0006 ר' יהושע בן פרחיה \u0005והיה משתבח]\u0006 בהם, ואומר: \u0003כמה נאה אכסניא זו! אמר ליה\u0004 \u0005[לו]\u0006 \u0003ישו הנוצרי\u0004 שהיה אחד מתלמידיו: \u0003רבי,\u0004 אבל \u0003עיניה\u0004 של האשה \u0003טרוטות\u0004 (זולגות דמעות). \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003רשע, בכך אתה עוסק\u0004 בהסתכלות בנשים? \u0003אפיק ארבע מאה שפורי ושמתיה\u0004 \u0005[הוציא ארבע מאות שופרות ונידה אותו].\u0006 \u0003כל יומא אתא לקמיה ולא קבליה\u0004 \u0005[כל יום היה בא\u0006 ישו \u0005לפניו ולא קיבל אותו\u0006 בחזרה\u0005].\u0006","\u0003יומא חד הוה קרי\u0004 \u0005[יום אחד היה קורא]\u0006 ר' יהושע בן פרחיה \u0003קרית\u0004 (קריאת) \u0003שמע, אתא לקמיה\u0004 \u0005[בא\u0006 ישו \u0005לפניו].\u0006 \u0003הוה בדעתיה לקבוליה\u0004 \u0005[היה בדעתו לקבלו]\u0006 בפעם זו, \u0003אחוי ליה בידיה\u0004 \u0005[הראה לו בידו]\u0006 שימתין, ואילו ישו \u0003סבר מדחא דחי ליה\u0004 \u0005[חשב\u0006 שהוא \u0005דוחה אותו]\u0006 לגמרי, \u0003אזל זקף לבינתא פלחא\u0004 \u0005[הלך העמיד לבינה\u0006 ו\u0005עבד אותה]\u0006 כעבודה זרה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יהושע בן פרחיה: \u0003חזור בך! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כך מקובלני ממך, כל החוטא ומחטיא את הרבים אין מספיקין בידו לעשות תשובה.\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003ישו הנוצרי כישף והסית והדיח והחטיא את ישראל.\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בן אלעזר אומר, יצר\u0004 הרע, \u0003תינוק, ואשה —\u0004 \u0003תהא שמאל דוחה וימין מקרבת,\u0004 שאם דוחים אותם יותר מדי יכול הדבר להביא לידי נזק.","\u0003נמצא ההורג\u0004 (הרוצח) \u0003עד שלא נערפה העגלה —\u0004 \u0003תצא\u0004 העגלה \u0003ותרעה בעדר,\u0004 ואין בה שום קדושה מיוחדת. אם נמצא \u0003משנערפה העגלה,\u0004 אף על פי שלא עשו את כל הטקס — אסורה בהנאה ו\u0003תקבר במקומה, ש\u0004הרי \u0003על ספק באתה מתחילתה\u0004 שלא היה ברור מי הרוצח — \u0003כיפרה ספיקה,\u0004 כלומר, סיימה את תפקידה \u0003והלכה לה\u0004 והריהי עגלה ערופה לכל דבר. \u0003נערפה העגלה ואחר כך נמצא ההורג —\u0004 \u0003הרי זה יהרג,\u0004 ואין אומרים שכבר נתכפר לו על ידי עריפת העגלה.","\u0003עד אחד אומר \"ראיתי את ההורג\" ועד אחד אומר \"לא ראית\", אשה אומרת \"ראיתי\" ואשה אומרת \"לא ראית\" —\u0004 \u0003היו עורפין\u0004 את העגלה, שכל זמן שאין עדות ברורה על הרוצח — מביאים עגלה על הספק. וכן אם \u0003עד אחד אומר \"ראיתי\" ושנים אומרים \"לא ראית\" —\u0004 \u0003היו עורפין,\u0004 שסומכים על השנים. \u0003שנים אומרים \"ראינו\" ואחד אומר להן \"לא ראיתם\" —\u0004 \u0003לא היו עורפין.\u0004","ועוד אמרו \u0003משרבו הרוצחנין בטלה עגלה ערופה. משבא אליעזר בן דינאי, ותחינה בן פרישה היה נקרא, חזרו לקרותו \"בן הרצחן\",\u0004 שכיון שכבר היו אנשים רוצחים מפורסמים ברבים — שוב לא היה מקום לעגלה ערופה.","ועוד אמרו \u0003משרבו המנאפים פסקו המים המרים\u0004 שלא השקו את הסוטות. \u0003ור' יוחנן בן זכאי\u0004 הוא ש\u0003הפסיקן שנאמר: \"לא אפקוד על בנותיכם כי תזנינה ועל כלותיכם כי תנאפנה כי הם\u0004 עם הזונות יפרדו","\u0003\"\u0004(הושע ד, יד), שהם עצמם היו נואפים. \u0003משמת יוסי בן יועזר איש צרידה ויוסי בן יהודה איש ירושלים —\u0004 \u0003בטלו האשכלות,\u0004 כלומר, הם היו אחרוני האשכולות, כאשר יבואר עניינם, \u0003שנאמר: \"אין אשכול לאכול בכורה אותה נפשי\"\u0004 (מיכה ז, א). ועוד בסיפור העבר: \u0003יוחנן כהן גדול העביר\u0004 (ביטל) את \u0003הודיית המעשר,\u0004 שמזמנו אין מתוודים עוד על ביעור המעשרות. \u0003אף הוא בטל את המעוררין ואת הנוקפין\u0004 שהיו במקדש."],["\u0003עד ימיו היה פטיש\u0004 של נפחים \u0003מכה בירושלים\u0004 בחול המועד, והוא ביטל את הדבר. \u0003ו\u0004עוד: \u0003בימיו אין צריך לשאול על הדמאי\u0004 (תבואה שאין יודעים בוודאות שהיא מעושרת), לפי שהכל היו מעשרים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מנין שאם נערפה העגלה ואחר כך נמצא ההורג שאין\u0004 עריפתה \u0003פוטרת אותו\u0004 מעונש — \u0003תלמוד לומר: \"ולארץ לא יכפר לדם אשר שפך בה כי אם בדם שפכו\"\u0004 (במדבר לה, לג).","שנינו: \u0003עד אחד אומר \"ראיתי את ההורג\"\u0004 והשני אומר \"לא ראית\" — היו עורפים. ומדייקים: \u0003טעמא\u0004 \u0005[הטעם]\u0006 דווקא ש\u0003מכחיש ליה\u0004 \u0005[אותו]\u0006 העד השני, \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003לא\u0004 היה \u0003מכחיש ליה\u0004 \u0005[אותו]\u0006 \u0003עד אחד —\u0004 \u0003מהימן\u0004 \u0005[נאמן]\u0006 בזה ואין עורפים.","\u0003מנהני מילי\u0004 \u0005[מניין הדברים הללו]?\u0006 ומשיבים, \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 נאמר בדין עגלה ערופה \u0003\"לא נודע מי הכהו\"\u0004 (דברים כא, א), ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003נודע מי הכהו, אפילו\u0004 ידע זאת \u0003אחד בסוף העולם —\u0004 \u0003לא היו עורפין. ר' עקיבא אומר: מנין לסנהדרין שראו\u0004 בעצמם \u0003אחד שהרג את הנפש ואין מכירין אותו,\u0004 כלומר, אין מזהים אותו בבירור, \u0003שלא היו עורפין —\u0004 \u0003תלמוד לומר: \"ועינינו לא ראו\"\u0004 (במדבר לה, ז), \u0003והלא ראו.\u0004","ושואלים: \u0003השתא דאמרת\u0004 \u0005[עכשיו שאתה אומר]\u0006 שבענין זה \u0003עד אחד מהימן\u0004 \u0005[נאמן],\u0006 אם כן \u0003אידך חד היכי מצי מכחיש ליה\u0004 \u0005[האחד האחר איך יכול להכחיש אותו]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003עולא: כל מקום שהאמינה תורה\u0004 ל\u0003עד אחד —\u0004 \u0003הרי כאן\u0004 עדותו נחשבת כעדות גמורה של \u0003שנים\u0004 עדים, \u0003ואין דבריו של אחד\u0004 מתקיימים \u0003במקום שנים!\u0004 ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 \u0003עולא: תני\u0004 \u0005[\u0006תקן ו\u0005שנה]:\u0006 \u0003לא היו עורפין\u0004 את העגלה. \u0003וכן אמר ר' יצחק: תני\u0004 \u0005[שנה]:\u0006 \u0003לא היו עורפין.\u0004","\u0003ו\u0004אילו \u0003ר' חייא אמר: תני\u0004 \u0005[שנה]:\u0006 \u0003היו עורפין.\u0004 ושואלים: \u0003ולר' חייא קשיא\u0004 \u0005[קשה]\u0006 מה שאמר \u0003עולא!\u0004 ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003כאן\u0004 במשנה, מדובר כשבאו שניהם \u0003בבת אחת\u0004 — מבטלים את העדות, ואילו \u0003כאן\u0004 בדברי עולא, מדובר כשבאו \u0003בזה אחר זה,\u0004 שלאחר שקיבלו כבר את עדותו של העד הראשון אין עד שני יכול לבטל את עדותו.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003עד אחד אומר \"ראיתי את ההורג\" ושנים אומרים \"לא ראית\" —\u0004 \u0003היו עורפין.\u0004 ונדייק מכאן: \u0003הא חד וחד\u0004 \u0005[הרי\u0006 אם באו \u0005אחד ואחד\u0006 אחריו\u0005]\u0006 \u0003לא היו עורפין,\u0004 אם כן \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003ר' חייא\u0004 שגרס במשנתנו \"עורפין\"!","ומשיבים: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 שכך אתה מדייק, \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את מה ששנינו ב\u0005סופה]\u0006 של המשנה: \u0003שנים אומרים \"ראינו\" ועד אחד אומר \"לא ראיתם\" —\u0004 \u0003לא היו עורפין,\u0004 ונדייק: \u0003הא חד וחד\u0004 \u0005[והרי\u0006 אם היו \u0005אחד ואחד] —\u0006 \u0003היו עורפין.\u0004 ואם כן הדיוקים בשני חלקי המשנה סותרים זה את זה!","\u0003אלא\u0004 צריך לפרש שאין לדייק כאן באופן זה: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 כולה לא בעדים כשרים מדברת אלא \u0003ב\u0004אנשים שהם \u0003פסולי עדות, וכ\u0004שיטת \u0003ר' נחמיה,\u0004 ש\u0003אמר: כל מקום שהאמינה תורה\u0004 לדברי \u0003עד אחד\u0004 ואין צורך בעדות גמורה של שני עדים \u0003הלך אחר רוב דעות,\u0004 כלומר, כשיש הכחשה בין העדויות, פוסקים כפי העדות שיש לה יותר תומכים, בין אם כשרים לעדות ובין אם לאו, \u0003ועשו\u0004 עדות \u0003שתי נשים\u0004 שהן בדרך כלל פסולות לעדות נגד \u0003איש אחד כ\u0004עדות \u0003שני אנשים באיש אחד.\u0004 זו שיטה אחת, ולפיה משנתנו עוסקת בעד אחד כשר מול שני עדים פסולים.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 ששיטת ר' נחמיה היא באופן אחר: \u0003כל היכא דאתא\u0004 \u0005[מקום שבא]\u0006 \u0003עד אחד כשר מעיקרא\u0004 \u0005[מתחילה],\u0006 \u0003אפילו מאה נשים\u0004 המכחישות אותו \u0003כי\u0004 \u0005[כמו]\u0006 עד \u0003אחד דמיין\u0004 \u0005[נחשבות].\u0006 \u0003והכא\u0004 \u0005[וכאן]\u0006 ששנינו: עד אחד אומר \"ראיתי\" ושנים אומרים \"לא ראית\" — עורפים, ומשמע שמבטלים את עדות הראשון, \u0003במאי עסקינן\u0004 \u0005[במה אנו עוסקים] —\u0006 \u0003כגון דאתאי\u0004 \u0005[שבאה]\u0006 \u0003אשה מעיקרא\u0004 \u0005[מתחילה]\u0006 והעידה שראתה את ההורג ובאות שתי נשים אחריה והעידו שלא ראתה. \u0003ותרצה\u0004 \u0005[ותקן]\u0006 לשיטה זו את דברי \u0003ר' נחמיה הכי\u0004 \u0005[כך],\u0006 \u0003ר' נחמיה אומר: כל מקום שהאמינה תורה\u0004 לדברי \u0003עד אחד —\u0004 \u0003הלך אחר רוב דעות, ועשו שתי נשים באשה אחת כשני אנשים באיש אחד. אבל שתי נשים\u0004 המעידות \u0003באיש אחד\u0004 כשהוא כשר לעדות — \u0003כי פלגא ופלגא דמי\u0004 \u0005[כמו חצי וחצי דומה]\u0006 הדבר, ולא במקרה כזה דיברה משנתנו.","\u0003ו\u0004שואלים: אם כן \u0003תרתי\u0004 \u0005[שני]\u0006 קטעים במשנה המחדשים אותו דין שב\u0003פסולי עדות\u0004 הולכים אחר רוב דעות, \u0003למה לי?\u0004 ומסבירים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003כי אזלינן בתר\u0004 \u0005[כאשר אנחנו הולכים אחר]\u0006 \u0003רוב דעות\u0004 בפסולים, הרי זה \u0003לחומרא\u0004 \u0005[להחמיר]\u0006 ולהצריך להביא עגלה ערופה, \u0003אבל לקולא\u0004 \u0005[להקל]\u0006 ולא להתחשב כלל בדעת היחיד שמכחיש את השנים שאומרים שראו, ולא להביא עגלה — \u0003לא,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין הבדל בזה.","שנינו במשנה ש \u0003משרבו הרוצחין\u0004 בטלה עגלה ערופה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003משרבו הרוצחנין בטלה עגלה ערופה.\u0004 וההסבר לכך: \u0003לפי שאינה באה אלא על הספק,\u0004 לכן \u0003משרבו הרוצחנין בגלוי\u0004 ויודעים מי הם הרוצחים — \u0003בטלה עגלה ערופה.\u0004","\u0003ועוד שנינו:\u0004 \u0003משרבו הנואפין\u0004 בטלו המים המרים. \u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 נאמר: \u0003\"ונקה האיש מעון\u0004 והאשה ההיא תשא את עוונה\" (במדבר ה, לא), ונדייק: \u0003בזמן שהאיש מנוקה מעון —\u0004 \u0003המים בודקין את אשתו,\u0004 ואולם אם \u0003אין האיש מנוקה מעון —\u0004 \u0003אין המים בודקין את אשתו.\u0004 \u0003ואומר: \"לא אפקוד על בנותיכם כי תזנינה\" כו'\u0004 (הושע ד, יד).","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 התוספת של \u0003ואומר?\u0004 שהרי לכאורה הדבר כבר נלמד מדברי התורה עצמם! ומסבירים: \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שמן הפסוק \"ונקה האיש מעוון\" נלמד כי \u0003עון דידיה\u0004 \u0005[שלו] —\u0006 \u0003אין\u0004 \u0005[כן]\u0006 הוא שגורם שלא תיבדק, אבל עוון \u0003דבניה ודבנתיה\u0004 \u0005[של בניו ושל בנותיו] —\u0006 \u0003לא, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 את הדבר ממה שנאמר \u0003\"לא אפקוד על\u0004 (בגלל) \u0003בנותיכם כי תזנינה ועל כלותיכם כי תנאפנה\"\u0004 (הושע ד, יד).","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003עון\u0004 ניאוף \u0003אשת איש —\u0004 \u0003אין\u0004 \u0005[כן],\u0006 שרק בגלל עוון כזה (\"תנאפנה\") אין המים בודקים, אבל \u0003עון\u0004 של מי שבעל \u0003פנויה —\u0004 \u0003לא,\u0004 לכן \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 מהמשך הכתוב \u0003\"כי הם עם הזנות יפרדו ועם הקדשות יזבחו\" וגו'\u0004 (הושע ד, יד).","כיון שהסבירו את הפסוק שואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש סופו \u0003\"ועם לא יבין ילבט\"? אמר ר' אלעזר: אמר להם נביא לישראל: אם אתם מקפידין על עצמכם —\u0004 \u0003מים בודקין נשותיכם, ואם לאו\u0004 \u0005[לא] —\u0006 \u0003אין המים בודקין נשותיכם,\u0004 ונמצא שאנשים מתלבטים ואינם יודעים אם חטאו נשיהם.","\u0003משרבו בעלי הנאה,\u0004 אנשים שמקבלים טובת הנאה מאחרים — \u0003נתעותו הדינין ונתקלקלו המעשים ואין נוח בעולם. משרבו רואי פנים בדין\u0004 שמטים את הדין לצד מסויים לפי גדולתו ומעלתו של הנידון — \u0003בטל \"לא תגורו\u0004 מפני איש\u0003\"\u0004 (דברים א, יז) \u0003ופסק \"לא תכירו\u0004 פנים במשפט\u0003\"\u0004 (דברים א, יז), \u0003ופרקו עול שמים, ונתנו עליהם עול בשר ודם.\u0004","\u0003משרבו לוחשי לחישות בדין\u0004 שהיו לוחשים ויועצים לדיינים — \u0003רבה חרון אף בישראל, ונסתלקה השכינה, משום שנאמר: \"\u0004אלהים ניצב בעדת אל \u0003בקרב אלהים ישפט\"\u0004 (תהלים פב, א), שהשכינה מצויה בין הדיינים וכשאין דנים כראוי הרי היא מסתלקת. \u0003משרבו\u0004 אלה ש\u0003\"אחרי בצעם\u0004 (כספם) \u0003לבם הלך\"\u0004 (יחזקאל לג, לא) — \u0003רבו \"האמרים לרע טוב ולטוב רע\"\u0004 (ישעיה ה, כ) כלומר, המתייחסים לרשעים כאילו היו צדיקים. \u0003משרבו האומרים לרע טוב ולטוב רע —\u0004 \u0003רבו \"הוי הוי\",\u0004 כלומר, צרות שזועקים עליהן \"הוי\", \u0003בעולם.\u0004","\u0003משרבו מושכי הרוק\u0004 שנוהגים מנהג גאווה בעצמם — \u0003רבו היהירים\u0004 בכלל, \u0003ונתמעטו התלמידים,\u0004 שכל אחד מתייהר לומר שאינו צריך ללמוד, \u0003ו\u0004לפיכך \u0003התורה חוזרת על לומדיה\u0004 לחפש מי שילמד אותה. ועוד, \u0003משרבו היהירים התחילו בנות ישראל להנשא ליהירים, שאין דורינו רואה אלא לפנים\u0004 בחיצוניות הדברים ואינו מסתכל בתוכנם.","ומקשים: \u0003איני\u0004 \u0005[\u0006וכי \u0005כך הוא]\u0006 שהבנות רוצות להינשא ליהירים?! \u0003והאמר מר\u0004 \u0005[והרי אמר החכם]:\u0006 \u0003האי מאן דמיהר\u0004 \u0005[מי שמתייהר,\u0006 מתגאה\u0005]\u0006 \u0003אפילו אאינשי ביתיה לא מיקבל\u0004 \u0005[על אנשי ביתו,\u0006 על אשתו, \u0005איננו מתקבל],\u0006 \u0003שנאמר: \"גבר יהיר ולא ינוה\"\u0004 (חבקוק ב, ה), כלומר, \u0003לא ינוה —\u0004 \u0003אפילו בנוה\u0004 (בבית) \u0003שלו\u0004 אינו מתקבל! מסבירים: \u0003מעיקרא קפצה עליה\u0004 \u0005[מתחילה קופצת עליו]\u0006 ורוצה להינשא לו משום שנראה לה כאדם גדול, \u0003לסוף\u0004 שהיא מכירה בו \u0003מיתזיל עלייהו\u0004 \u0005[נעשה מזולזל בעיניהן].\u0006","ועוד ממשיכה הברייתא: \u0003משרבו מטילי מלאי על בעלי בתים\u0004 שקבעו שבעלי בתים יתנו סכומים מסויימים להחזקת הדיינים — \u0003רבה השוחד והטיית משפט, ופסקה טובה. משרבו\u0004 אותם דיינים ומנהיגים שאומרים \u0003\"מקבלני טובתך\" ו\"מחזקני טובותיך\" —\u0004 \u0003רבו \"איש הישר בעיניו יעשה\"\u0004 (שופטים יז, ו), \u0003שפלים הוגבהו והגבוהים הושפלו, ומלכותא אזלא ונולא\u0004 \u0005[והמלכות הולכת ומתנוולת].\u0006 \u0003משרבו צרי עין וטורפי טרף\u0004 (אנשים הלהוטים אחר רווחים) — \u0003רבו מאמצי הלב וקופצי ידים מלהלוות, ועברו על מה שכתוב בתורה\u0004 \"לא תאמץ את לבבך ולא תקפוץ את ידך מאחיך האביון... \u0003השמר לך פן\u0004 יהיה דבר עם לבבך... ולא תתן לו\" (דברים טו, ט).","\u0003משרבו\u0004 הנשים שהיו נוהגות בפריצות \u0003\"נטויות גרון ומשקרות עינים\"\u0004 (ישעיה ג, טז) — \u0003רבו מים המרים\u0004 משום שרבתה הזנות, \u0003אלא שפסקו\u0004 לבסוף המים המרים מפני שרבתה הזנות כל כך. \u0003משרבו מקבלי מתנות —\u0004 \u0003נתמעטו הימים ונתקצרו השנים, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ושונא מתנת יחיה\"\u0004 (משלי טו, כז). \u0003משרבו זחוחי הלב\u0004 (אנשים המתגאים בליבם) — \u0003רבו מחלוקת בישראל. משרבו תלמידי שמאי והילל שלא שימשו כל צורכן\u0004 את רבותיהם — \u0003רבו מחלוקת בישראל, ונעשית תורה כשתי תורות. משרבו מקבלי צדקה מן הגוים —\u0004 \u0003היו ישראל למעלה והם למטה, ישראל לפנים והם לאחור\u0004 (כלומר, ההיפך, שישראל למטה, אלא שלא רצה להשתמש בלשון שהיא גנאי לישראל).","שנינו במשנה \u0003משמת יוסי בן יועזר\u0004 בטלו אשכולות. ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"אשכולות\"? אמר רב יהודה אמר שמואל,\u0004 הכוונה היא \u0003איש שהכל בו,\u0004 שיש בו כל דרכי תורה ומצוות. שנינו: \u0003יוחנן כהן גדול העביר הודיית המעשר כו'.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 עשה כן? \u0003אמר ר' יוסי בר' חנינא: לפי שאין נותנין אותו\u0004 את המעשר \u0003כתיקונו\u0004 ככתוב בתורה. ומדוע? \u0003דרחמנא אמר דיהבי\u0004 \u0005[שהתורה אמרה שיתנו]\u0006 מעשר ראשון \u0003ללוים\u0004"],["\u0003ואנן קא יהבינן\u0004 \u0005[ואנו נותנים\u0006 אותו\u0005]\u0006 \u0003לכהנים,\u0004 שקנס עזרא את הלויים שלא יקבלו מעשר ראשון מפני שלא עלו עימו מבבל לארץ ישראל. ולכן אינו יכול עוד לומר את הוידוי שנאמר בו \"עשיתי ככל אשר ציוויתני\" (דברים כו, יד), שהרי לא נתן ללויים.","ושואלים: \u0003ולודי\u0004 \u0005[ושיתוודה]\u0006 על \u0003שאר מעשרות\u0004 שאותם נתן כדין? \u0003אמר ריש לקיש: כל בית שאין מתודה על\u0004 הפרשת \u0003מעשר ראשון —\u0004 \u0003שוב אין מתודה על שאר מעשרות.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003אמר אביי: הואיל ופתח בו הכתוב תחילה\u0004 במעשר ראשון ללויים, שהרי נאמר \"וגם נתתיו ללוי ולגר ליתום ולאלמנה ככל מצוותך אשר ציויתני\" (דברים כו, יג).","ושואלים: \u0003מכלל\u0004 הדברים שאמרנו, שביטל ר' יוחנן את הוידוי על המעשרות, אתה לומד שעל כל פנים \u0003אפרושי הוו מפרשי\u0004 \u0005[שהיו מפרישים]\u0006 מעשר בימי יוחנן כהן גדול? \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אף הוא,\u0004 יוחנן כהן גדול, \u0003ביטל את הוידוי, וגזר על הדמאי.\u0004 ומדוע גזר — \u0003לפי ששלח\u0004 שליחים \u0003בכל גבול ישראל\u0004 ובדק \u0003וראה שאין\u0004 הכל \u0003מפרישין אלא תרומה גדולה בלבד, ו\u0004אילו \u0003מעשר ראשון ומעשר שני —\u0004 \u0003מקצתן\u0004 של אנשים \u0003מעשרין ומקצתן אין מעשרין.\u0004","\u0003אמר להם: בני, בואו ואומר לכם: כשם שתרומה גדולה יש בה עון מיתה\u0004 אם אוכל תבואה שלא הופרשה ממנה תרומה — \u0003כך תרומת מעשר\u0004 (אם לא הפרישו הלויים ממעשר ראשון שקיבלו ונתנוהו לכהנים) \u0003וטבל\u0004 (תבואה שלא הופרשו ממנה מעשרות) \u0003יש בהן עון מיתה.\u0004","וכיון שראה שיש ספק בדבר אם הפרישו מעשרותיהם \u0003עמד והתקין להם\u0004 תקנה זו של דמאי, שהיא: \u0003הלוקח פירות מעם הארץ\u0004 שלא ברור לנו אם הוא מעשר — \u0003מפריש מהן\u0004 מספק \u0003מעשר ראשון ומעשר שני. מעשר ראשון מפריש ממנה תרומת מעשר ונותנה לכהן, ו\u0004את \u0003מעשר שני עולה ואוכלו בירושלים.\u0004 אבל \u0003מעשר ראשון ומעשר עני\u0004 שמותרים באכילה לזרים ואין ללויים ולעניים אלא זכות ממונית בהם — \u0003המוציא מחבירו עליו הראיה,\u0004 ומכיון שאין הלויים או העניים יכולים להוכיח שאכן לא הופרש המעשר מתבואה זו — אינם יכולים להוציא ממנו את מעשרותיהם. ומכל מקום למדנו מכאן שלא היו כולם מפרישים מעשר בזמנו של יוחנן כהן גדול!","ומשיבים: \u0003תרתי\u0004 \u0005[שני\u0006 דברים\u0005]\u0006 \u0003תקן: ביטל וידוי\u0004 של \u0003חבירים,\u0004 שאפילו החברים המפרישים מעשרות לא יתוודו וידוי מעשר, \u0003וגזר על דמאי של עמי הארץ,\u0004 שמא אינם מפרישים.","שנינו במשנה: \u0003ואף הוא\u0004 יוחנן כהן גדול \u0003ביטל את המעוררים.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 הם\u0005]\u0006 \u0003מעוררים\u0004 אלה? \u0003אמר רחבה: בכל יום ויום שהיו עומדים לוים על דוכן\u0004 בבית המקדש \u0003ואומרים \"עורה למה תישן ה'\"\u0004 (תהלים מד, כד), \u0003אמר להן\u0004 יוחנן כהן גדול: \u0003וכי יש שינה לפני המקום\u0004 שאתם אומרים \"עורה\"? \u0003והלא כבר נאמר \"הנה לא ינום ולא יישן שומר ישראל\"\u0004 (תהלים קכא, ד)! \u0003אלא בזמן שישראל שרוין בצער ו\u0004אילו \u0003אומות העולם בנחת ושלוה —\u0004 \u0003לכך נאמר \"עורה למה תישן ה'\",\u0004 אבל כשאומרים זאת בכל בוקר מתפרש הדבר בדרך לא נכונה, ולכן ביטל את האמירה.","\u0003שנינו שיוחנן כהן גדול ביטל גם\u0004 \u0003את הנוקפים.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 הם\u0005]\u0006 \u0003\"נוקפים\"\u0004 אלה? \u0003אמר רב יהודה אמר שמואל: שהיו מסרטין\u0004 (עושים סריטה) \u0003לעגל\u0004 העומד לשחיטה \u0003בין קרניו, כדי שיפול דם בעיניו\u0004 ויהיה קל יותר לשחוט אותו. \u0003אתא איהו בטיל\u0004 \u0005[בא הוא\u0006 ו\u0005ביטל]\u0006 את הדבר \u0003משום דמיחזי כי מומא\u0004 \u0005[שנראה\u0006 הדבר \u0005כמו\u0006 שמטיל בו \u0005מום].\u0006","\u0003במתניתא תנא\u0004 \u0005[בברייתא שנה]\u0006 פירוש אחר ל\"נוקפין\": \u0003שהיו חובטין אותו\u0004 את העגל \u0003במקלות\u0004 להמם אותו לפני שחיטה \u0003כדרך שעושין אותו לפני עבודה זרה. אמר להם\u0004 יוחנן כהן גדול: \u0003עד מתי אתם מאכילין נבילות למזבח!\u0004 ושואלים: וכי \u0003נבילות\u0004 היו אלה?! \u0003הא שחיט להו\u0004 \u0005[הרי שוחט אותן]\u0006 ולא מתו מעצמם! \u0003אלא\u0004 הכוונה היא שהיו נעשות בכך \u0003טריפות,\u0004 ומדוע — \u0003שמא\u0004 מתוך המכות \u0003ניקב קרום של מוח\u0004 ונעשה העגל טריפה. לכן \u0003עמד והתקין להם טבעות בקרקע\u0004 שיקשרו את הבהמות שם ולא יצטרכו לאמצעים אחרים להקל על שחיטתן.","\u0003ועוד שנינו:\u0004 \u0003עד ימיו\u0004 של יוחנן כהן גדול \u0003היה פטיש מכה בירושלים.\u0004 ומסבירים: שמדובר \u0003בחולו של מועד,\u0004 ונראה כביזוי המועד.","\u0003ועוד שנינו:\u0004 \u0003כל ימיו לא היה אדם צריך לשאול על הדמאי.\u0004 ומעירים שזהו \u0003כדאמרן\u0004 \u0005[כמו שאמרנו]\u0006 שתיקן שיהיו מעשרים את הדמאי, ומשום כך אין אדם נזקק לשאול את חבירו אם תבואה זו מעושרת.","ועוד דברים שבטלו: \u0003משבטלה סנהדרין בטל\u0004 גם \u0003השיר מבית המשתאות,\u0004 שאין שרים עוד בסעודה על היין, \u0003שנאמר: \"בשיר לא ישתו יין\" וגו'\u0004 (ישעיה כד, ט).","\u0003משמתו נביאים הראשונים בטלו אורים ותומים. משחרב בית המקדש בטל השמיר ו\u0004בטל \u0003נופת צופים, ופסקו אנשי אמנה מישראל, שנאמר: \"הושיעה ה' כי גמר חסיד\u0004 כי פסו אמונים מבני אדם","\u0003\"\u0004(תהלים יב, ב). \u0003רבן שמעון בן גמליאל אומר: העיד ר' יהושע: מיום שחרב בית המקדש אין יום שאין בו קללה\u0004 מסוג זה או אחר, \u0003ולא ירד הטל לברכה, וניטל טעם הפירות. ר' יוסי אומר: אף ניטל שומן הפירות. ר' שמעון בן אלעזר אומר: הטהרה\u0004 שבטלה \u0003נטלה\u0004 מן הפירות \u0003את הטעם ואת הריח, המעשרות\u0004 שבטלו \u0003נטלו את שומן הדגן. וחכמים אומרים: הזנות והכשפים\u0004 הם ש\u0003כילו את הכל.\u0004","על תחילת המשנה שואלים: \u0003וממאי\u0004 \u0005[וממה,\u0006 מניין\u0005]\u0006 למדים אנו ש\u0003משבטלה סנהדרי כתיב\u0004 \u0005[נאמר]\u0006 הפסוק \"בשיר לא ישתו יין\" (ישעיה כד, ט)? \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 במקום אחר: \u0003\"זקנים משער שבתו בחורים מנגינתם\"\u0004 (איכה ה, יד), הרי שיש קשר בין ביטול (\"שבתו\") הסנהדרין (\"זקנים משער\") לבין הפסקת הנגינה (\"בחורים מנגינתם\").","\u0003אמר רב: אודנא דשמעא זמרא\u0004 \u0005[אוזן השומעת זמר] —\u0006 \u0003תעקר,\u0004 שאסור לשמוע זמר לאחר החורבן. \u0003אמר רבא:\u0004 אם יש \u0003זמרא בביתא\u0004 \u0005[זמר בבית] —\u0006 יש \u0003חורבא בסיפא\u0004 \u0005[חורבן על הסף],\u0006 \u0003שנאמר: \"קול ישורר בחלון חרב בסף כי ארזה ערה\"\u0004 (צפניה ב, יד).","ושואלים אגב כך: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 הנימוק \u0003\"כי ארזה ערה\"?\u0004 וכן \u0003אמר ר' יצחק:\u0004 הרי \u0003בית המסובך בארזים\u0004 הרי \u0003עיר הוא\u0004 וחזק ביותר! \u0003אלא\u0004 יש לפרש: \u0003אפילו בית המסובך\u0004 ומסוכך \u0003בארזים מתרועע\u0004 אם נשמע בו זמר. \u0003אמר רב אשי: שמע מינה\u0004 \u0005[למד מכאן]\u0006 \u0003כי מתחיל חורבא\u0004 \u0005[כאשר מתחיל החורבן] —\u0006 \u0003בסיפא\u0004 \u0005[בסף]\u0006 הוא \u0003מתחיל, שנאמר: \"חרב בסף\". ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 \u0003מהכא\u0004 \u0005[מכאן]\u0006 אנו למדים דבר זה, שכתוב \u0003\"ושאיה יכת שער\"\u0004 (ישעיה כד, יב), כלומר, השד הקרוי \"שאיה\", המחריב את הבתים, מכה בתחילה בשער. \u0003אמר מר בר רב אשי: לדידי חזי ליה\u0004 \u0005[אני בעצמי ראיתי אותו]\u0006 את השאיה \u0003ו\u0004היה \u0003מנגח\u0004 והורס \u0003כי תורא\u0004 \u0005[כמו שור].\u0006","\u0003אמר רב הונא: זמרא דנגדי ודבקרי\u0004 \u0005[זמר של מושכי האניות ושל מוליכי הבקר] —\u0006 \u0003שרי\u0004 \u0005[מותר],\u0006 משום שהשיר שלהם הוא כדי לתת קצב לעבודתם. \u0003דגרדאי\u0004 \u0005[של האורגים] —\u0006 \u0003אסיר\u0004 \u0005[אסור],\u0006 משום שאינם מזמרים אותו אלא להנאתם. מסופר: \u0003רב הונא בטיל זמרא\u0004 \u0005[ביטל\u0006 את מיני \u0005הזמר]\u0006 ובאה ברכה לכל, \u0003קם\u0004 \u0005[עמד]\u0006 מחיר \u0003מאה אווזי בזוזא\u0004 \u0005[אווזים בדינר]\u0006 \u0003ומאה סאה חיטי\u0004 \u0005[חיטים]\u0006 \u0003בזוזא\u0004 \u0005[בדינר]\u0006 \u0003ולא איבעי\u0004 \u0005[היה להם ביקוש]\u0006 אפילו במחיר כה זול, משום שהיה השפע מרובה. \u0003אתא\u0004 \u0005[בא]\u0006 \u0003רב חסדא\u0004 לאחר מכן \u0003זלזיל ביה\u0004 \u0005[זילזל בו]\u0006 באיסור זה, וכתוצאה מכך \u0003איבעאי אווזא בזוזא\u0004 \u0005[נצטרכו אווז\u0006 אחד \u0005בדינר\u0006 אחד\u0005]\u0006 \u0003ולא משתכח\u0004 \u0005[נמצא].\u0006","\u0003אמר רב יוסף:\u0004 אם \u0003זמרי גברי ועני נשי\u0004 \u0005[מזמרים הגברים ועונות הנשים]\u0006 — \u0003פריצותא\u0004 \u0005[פריצות\u0006 היא\u0005],\u0006 אם \u0003זמרי נשי ועני גברי\u0004 \u0005[מזמרות הנשים ועונים הגברים]\u0006 — הרי זה גורם להבערת היצר \u0003כאש בנעורת.\u0004 ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה]\u0006 אם מגדירים את הדברים כך או כך? הרי מדברי רב יוסף עולה ששניהם אסורים! ומשיבים: \u0003לבטולי הא מקמי הא\u0004 \u0005[לבטל זה מלפני זה]\u0006 כי אם אינו יכול לבטל את השירה בכלל — שיבטל תחילה את האופן החמור יותר, שהוא כאש בנעורת.","\u0003אמר ר' יוחנן: כל השותה בארבעה מיני זמר —\u0004 \u0003מביא חמש פורעניות לעולם, שנאמר: \"הוי משכימי בבקר שכר ירדפו מאחרי בנשף יין ידליקם והיה כנור ונבל תף וחליל ויין משתיהם ואת פעל ה' לא יביטו\"\u0004 (ישעיה ה, יא-יב) שמנויים שם ארבעה מיני כלי זמר (כינור, נבל, תוף וחליל),","\u0003מה כתיב\u0004 \u0005[נאמר]\u0006 \u0003אחריו: \"לכן גלה עמי מבלי דעת\"\u0004 (ישעיה ה, יג) — \u0003שגורמין גלות לעולם, \"וכבודו מתי רעב\"\u0004 (ישעיה ה, יג) — \u0003שמביאין רעב לעולם, \"והמונו צחה צמא\"\u0004 (ישעיה ה, יג) — \u0003שגורמין לתורה\u0004 המשולה למים \u0003שתשתכח מלומדיה, \"וישח אדם וישפל איש\"\u0004 (ישעיה ה, טו) — \u0003שגורמין שפלות לשונאו של הקדוש ברוך הוא\u0004 (בלשון נקיה: לקדוש ברוך הוא), \u0003ואין \"איש\" אלא הקדוש ברוך הוא\u0004 \u0003שנאמר: \"ה' איש מלחמה\"\u0004 (שמות טו, ג), \u0003\"ועיני גבהים תשפלנה\"\u0004 (ישעיה ה, טו) — \u0003שגורמין שפלות של ישראל,\u0004 הרי חמש פורעניות.","\u0003ומה,\u0004 איזה עונש, \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003אחריו —\u0004 \u0003\"לכן\u0004"],["\u0003הרחיבה שאול נפשה ופערה פיה לבלי חק וירד הדרה והמונה ושאונה ועלז בה\"\u0004 (ישעיה ה, יד), שלבסוף יורדים לשאול.","שנינו במשנה: \u0003משמתו נביאים הראשונים\u0004 בטלו אורים ותומים. ושואלים: \u0003מאן\u0004 \u0005[מי\u0006 הם\u0005]\u0006 \u0003\"נביאים הראשונים\"? אמר רב הונא: זה דוד ושמואל ושלמה,\u0004 ואחריהם לא היו עוד האורים והתומים. \u0003רב נחמן אמר:\u0004 כבר \u0003בימי דוד, זימנין סליק\u0004 \u0005[פעמים עלה\u0006 להם\u0005],\u0006 הצליחו לקבל תשובה באורים ותומים, \u0003וזימנין\u0004 \u0005[ופעמים]\u0006 \u0003לא סליק\u0004 \u0005[עלה]\u0006 ולא קיבלו תשובה, \u0003שהרי שאל צדוק\u0004 הכהן הגדול בימי דוד באורים ותומים — \u0003ועלתה לו,\u0004 קיבל תשובה, \u0003שאל אביתר —\u0004 \u0003ולא עלתה לו, שנאמר:\u0004 \u0003\"ויעל אביתר\"\u0004 (שמואל ב טו, כד) ופירשו — שנסתלק (עלה) משום כך מן הכהונה.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רבה בר שמואל: \"ויהי לדרש אלהים בימי זכריהו המבין בראת האלהים\"\u0004 (דברי הימים ב כו, ה), \u0003מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה שהיה מבין \u0003באורים ותומים\u0004 למרות שהיה אחרי שלמה המלך? ודוחים: \u0003לא, ב\u0004מראות ה\u0003נביאים\u0004 היה מבין אך לא באורים ותומים.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו בברייתא: \u0003משחרב בית המקדש ראשון בטלו ערי מגרש, ופסקו אורים ותומים, ופסק מלך מבית דוד.\u0004","\u0003ואם לחשך אדם לומר\u0004 שאורים ותומים לא פסקו, שהרי נאמר בראשית ימי בית שני \u0003\"ויאמר התרשתא להם אשר לא יאכלו מקדש הקדשים עד עמד כהן לאורים ולתמים\u0004 (עזרא ב, סג), שלכאורה נראה שהיה זה רק ענין של המתנה, עד שיבנה בית המקדש השני, \u0003[אמור לו]\u0004 שאין הדחיה לזמן מועט וקצוב, אלא \u0003כאדם שאומר לחבירו\u0004 על דבר שיתרחש אי פעם בעתיד הרחוק \u0003\"עד שיחיו מתים ויבא משיח בן דוד\".\u0004 ומכל מקום מפורש בברייתא כי כל זמן שהיה בית ראשון קיים לא פסקו אורים ותומים!","\u0003אלא אמר רב נחמן בר יצחק: מאן\u0004 \u0005[מי\u0006 הם\u0005]\u0006 \u0003\"נביאים הראשונים\"\u0004 שנאמר שמשמתו בטלו אורים ותומים — \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מחגי זכריה ומלאכי,\u0004 שנביאים \u0003אחרונים נינהו\u0004 \u0005[הם].\u0006 \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 \u0003משמתו חגי זכריה ומלאכי נסתלקה רוח הקודש\u0004 של נבואה גלויה \u0003מישראל.\u0004 הרי שהם היו הנביאים האחרונים. \u0003ואף על פי כן היו משתמשים בבת קול\u0004 משמים שהיתה נשמעת להם, כגון המסופר","\u0003שפעם אחת היו מסובין\u0004 חכמים \u0003בעליית בית גוריא ביריחו, נתנה עליהן בת קול מן השמים ואמרה: יש בכם אדם אחד שראוי שתשרה שכינה עליו\u0004 כנביא, \u0003אלא שאין דורו ראוי לכך. נתנו\u0004 המצויים שם \u0003עיניהם בהלל הזקן, וכשמת הספידוהו\u0004 בנוסח: \u0003הי חסיד, הי עניו, תלמידו של עזרא.\u0004","\u0003ושוב פעם אחרת,\u0004 דורות לאחר מכן, כש\u0003היו\u0004 חכמים \u0003מסובין בעלייה ביבנה, נתנה להן בת קול מן השמים ואמרה להן: יש בכם אדם אחד שראוי שתשרה שכינה עליו, אלא שאין דורו זכאין לכך, נתנו\u0004 החכמים \u0003עיניהם בשמואל הקטן, וכשמת הספידוהו\u0004 בנוסח: \u0003הי עניו, הי חסיד, תלמידו של הלל.\u0004","\u0003ואף הוא\u0004 שמואל הקטן \u0003אמר בשעת מיתתו\u0004 דברי נבואה: \u0003שמעון,\u0004 רבן שמעון בן גמליאל, \u0003וישמעאל,\u0004 ר' ישמעאל בן אלישע כהן גדול — \u0003לחרבא\u0004 \u0005[לחרב]\u0006 יהיו, \u0003וחברוהי\u0004 \u0005[וחבריהם] —\u0006 \u0003לקטלא\u0004 \u0005[למוות],\u0006 \u0003ושאר עמא\u0004 \u0005[העם] —\u0006 \u0003לביזא\u0004 \u0005[לביזה],\u0006 \u0003ועקן סגיאין עתידין למיתי\u0004 \u0005[וצרות גדולות עתידות לבוא]\u0006 \u0003על עמא\u0004 \u0005[העם].\u0006 ומספרים: \u0003ואף על ר' יהודה בן בבא בקשו לומר\u0004 בהספדו נוסח \u0003\"הי חסיד הי עניו\", אלא שנטרפה שעה\u0004 ולא יכלו לעשות זאת, מפני \u0003שאין מספידין על הרוגי מלכות,\u0004 ור' יהודה בן בבא מהרוגי מלכות היה.","שנינו במשנה: \u0003משחרב בית המקדש בטל השמיר כו'. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שמיר\u0004 ששנינו הוא זה \u0003שבו\u0004 (בעזרתו) \u0003בנה שלמה את בית המקדש, שנאמר:\u0004 \u0003\"והבית בהבנתו אבן שלמה מסע נבנה\"\u0004 (מלכים א ו, ז) — \u0003הדברים\u0004 הללו \u0003ככתבן,\u0004 כלומר, לקחו אבנים שלימות וחתכון על ידי שמיר ובהן בנו, אלו \u0003דברי ר' יהודה.\u0004","\u0003אמר לו ר' נחמיה: וכי אפשר לומר כן? והלא כבר נאמר \"כל אלה אבנים יקרת\u0004 כמדות גזית \u0003מגררות במגרה\"\u0004 (מלכים א ז, ט), משמע שהאבנים לא היו כבריאתן, אלא תיקנו אותן במגרה שהיא כלי ברזל! \u0003אם כן מה תלמוד לומר\u0004 \u0003\"\u0004ומקבות והגרזן כל כלי ברזל \u0003לא נשמע בבית בהבנתו\"\u0004 \u0003(מלכים א ו, ז) —\u0004 \u0003שהיה מתקין,\u0004 מסתת את האבנים, \u0003מבחוץ\u0004 (מחוץ להר הבית), \u0003ומכניס מבפנים,\u0004 ובתוך הבית אכן לא השתמשו בברזל. \u0003אמר רבי: נראין דברי ר' יהודה באבני מקדש\u0004 שלא היו מתקנים אותן בברזל, \u0003ודברי ר' נחמיה באבני ביתו\u0004 של המלך.","ושואלים: \u0003ור' נחמיה,\u0004 הסבור שהיו משתמשים לבניית המקדש אף בכלי ברזל, \u0003שמיר\u0004 אם כן \u0003למאי אתא\u0004 \u0005[למה בא],\u0006 לשם מה היה דרוש? ומשיבים: \u0003מיבעי ליה לכדתניא\u0004 \u0005[צריך\u0006 היה \u0005אותו, לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003אבנים הללו\u0004 שבחושן ובאפוד, שצריכים לכתוב עליהן את שמות השבטים \u0003אין כותבין אותן בדיו —\u0004 \u0003משום שנאמר:\u0004 \u0003\"פתוחי חותם\"\u0004 (שמות כח, כא), לומר שצריך שיהיו השמות חקוקים באבן, \u0003ואין מסרטין עליהם באיזמל, משום שנאמר:\u0004 \u0003\"במלואתם\"\u0004 (שמות כח, כ) שצריכות האבנים להישאר במילואן בלי חסרון,","\u0003אלא כותב עליהם\u0004 את האותיות \u0003בדיו, ומראה להן,\u0004 כלומר, שם כנגדן בלא לנגוע בהן \u0003שמיר מבחוץ, והן נבקעות מאליהן\u0004 לפי סימני הדיו, \u0003כתאינה זו שנבקעת בימות החמה ואינה חסירה כלום, וכבקעה,\u0004 שדה, \u0003זו שנבקעת בימות הגשמים ואינה חסירה כלום.\u0004 והשמיר היה איפוא בשביל חקיקות אלה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שמיר זה —\u0004 \u0003ברייתו,\u0004 גודלו, \u0003כשעורה, ומששת ימי בראשית נברא, ואין כל דבר קשה יכול לעמוד בפניו. במה משמרין אותו\u0004 שלא ישבור כל דבר — \u0003כורכין אותו בספוגין של צמר, ומניחין אותו באיטני\u0004 (בכלי) \u0003של אבר\u0004 (עופרת) \u0003מליאה סובי\u0004 (סובין של) \u0003שעורין,\u0004 שכל אלה רכים ואין השמיר שובר אותם.","\u0003אמר ר' אמי: משחרב מקדש ראשון בטלה שירא פרנדא\u0004 (סוג של משי) \u0003וזכוכית לבנה. תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003משחרב מקדש ראשון בטלה שירא פרנדא וזכוכית לבנה ורכב ברזל, ויש אומרים:\u0004 בטל \u0003אף יין קרוש\u0004 (שנעשה מוצק) \u0003הבא משניר\u0004 (החרמון), \u0003הדומה\u0004 לאחר קרישתו \u0003כעיגולי דבילה.\u0004","\u0003שנינו במשנה שבטלה\u0004 \u0003נופת צופים.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 \u0003\"נופת צופים\"? אמר רב: סולת שצפה על גבי נפה,\u0004 כלומר, שהיא עבה ונשארת על גבי הנפה, \u0003ודומה\u0004 בטעמה \u0003לעיסה שנילושה בדבש ושמן. ולוי אמר\u0004 שנופת צופים היא \u0003שתי ככרות הנדבקות בתנור ותופחות ובאות עד שמגיעות זו לזו. ור' יהושע בן לוי אמר: זה דבש הבא מן הציפיא\u0004 (מקומות גבוהים). ומסבירים: \u0003מאי משמע\u0004 \u0005[מה המשמעות],\u0006 כלומר, מה הקשר בין הדברים — \u0003כדמתרגם\u0004 \u0005[כפי ש\u0006היה \u0005מתרגם]\u0006 \u0003רב ששת\u0004 את הפסוק \"כאשר תעשינה הדבורים\" (דברים א, מד) — \u0003כמא דנתזן דבריאתה ושייטן ברומי עלמא ומתיין דובשא מעישבי טורא\u0004 \u0005[כמו שמתפזרות הדבורים ושטות ברום העולם ומביאות דבש מעשבי ההר].\u0006","\u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במשנה: \u0003כל\u0004 דבר \u0003הנצוק —\u0004 \u0003טהור,\u0004 כלומר, גם אם יוצקים אותו לכלי טמא אין הזרם של הנוזל נחשב חיבור לטמא את מה שבתוך הכלי הטהור ממנו נוצק, \u0003חוץ מדבש זיפים והצפיחים\u0004 שמרוב צמיגותם אינם נחשבים לנוזל. ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"זיפים\"? אמר ר' יוחנן: דבש\u0004 מובחר כל כך \u0003שמזייפין בו,\u0004 שמערבים בתוכו חומרים אחרים, ואין הדבר מורגש. \u0003וריש לקיש אמר: על שם מקומו\u0004 הוא נקרא, \u0003כדכתיב\u0004 \u0005[כמו שנאמר]\u0006 ברשימת ערי יהודה \u0003\"זיף וטלם ובעלות\"\u0004 (יהושע טו, כד).","\u0003כיוצא בדבר אתה אומר\u0004 על הפסוק \u0003\"בבוא הזיפים ויאמרו לשאול הלא דוד\" וגו'\u0004 (תהלים נד, ב) שואלים: \u0003מאי\u0004 \u0005[מה\u0006 הם\u0005]\u0006 \u0003\"זיפים\"\u0004 שהוזכרו בפסוק זה? \u0003אמר ר' יוחנן:\u0004 כינוי של \u0003בני אדם המזייפין\u0004 (המשקרים) \u0003דבריהם. ור' אלעזר אומר: על שם מקומן\u0004 הם נקראים, \u0003כדכתיב\u0004 \u0005[כמו שנאמר]\u0006 \u0003\"זיף וטלם ובעלות\".\u0004","\u0003נאמר במשנה: משחרב בית המקדש...\u0004 \u0003ופסקו אנשי אמנה. אמר ר' יצחק: אלו בני אדם שהן מאמינין בהקדוש ברוך הוא\u0004 ובוטחים בו בכל מעשיהם. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 \u0003בברייתא\u0004\u0005],\u0006 \u0003ר' אליעזר הגדול אומר: כל מי שיש לו פת בסלו\u0004 לאכול היום \u0003ואומר \"מה אוכל למחר\",\u0004 שאין לו דרך למצוא פת למחר — \u0003אינו אלא מקטני אמנה,\u0004 כי צריך אדם להאמין שהקדוש ברוך הוא יספק לו את מזונו.","\u0003והיינו\u0004 \u0005[וזהו]\u0006 ש\u0003אמר ר' אלעזר: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"כי מי בז ליום קטנות\"\u0004 (זכריה ד, י) — \u0003מי גרם לצדיקים שיתבזבז שולחנן\u0004 (שכרם שנותנים להם) \u0003לעתיד לבא —\u0004 \u0003קטנות שהיה בהן,\u0004 ומהי? \u0003שלא האמינו בהקדוש ברוך הוא\u0004 אמונה שלימה, \u0003רבא אמר:\u0004 \"מי בז ליום קטנות\" — \u0003אלו קטני בני רשעי ישראל\u0004 בניהם של אנשים רשעים מישראל, המתים בעודם קטנים,"],["\u0003שמבזבזין\u0004 (בוזזים, קורעים) \u0003דין אביהם לעתיד לבוא.\u0004 ש\u0003אומרים\u0004 הבנים \u0003לפניו\u0004 בעת שדן הקדוש ברוך הוא את אבותיהם: \u0003רבונו של עולם, מאחר שאתה עתיד ליפרע מהן,\u0004 מהאבות בעולם הבא על רשעותם, אם כן \u0003למה הקהיתה שיניהם בם,\u0004 שציערתם כבר בחייהם, במותם של הבנים? ואם כן מותם של הבנים הוא כפרה לאבות.","\u0003אמר ר' אילעא בר יברכיה: אלמלא תפלתו של דוד\u0004 שהתפלל על כך, \u0003היו כל ישראל מוכרי רבב\u0004 (שומן), כלומר, עוסקים במלאכות בזויות בלבד, \u0003שנאמר:\u0004 \u0003\"שיתה ה' מורה להם\"\u0004 (תהלים ט, כא), כלומר, שיתן ה' להם כבוד. \u0003ואמר ר' אילעא בר יברכיה: אלמלא תפלתו של חבקוק\u0004 הנביא \u0003היו שני תלמידי חכמים מתכסים בטלית אחת\u0004 מרוב עוני, \u0003ועוסקין\u0004 כך \u0003בתורה, שנאמר:\u0004 \u0003\"ה' שמעתי שמעך יראתי ה' פעלך בקרב שנים חייהו\"\u0004 (חבקוק ג, ב), ש\"פעלך (תורתך) בקרב שנים\". \u0003אל תקרא \"בקרב שנים\" אלא \"בקרוב שנים\"\u0004 כשהיא נלמדת על ידי שנים המתקרבים יחד בכיסוי אחד, ודאג חבקוק שלא יבוא מצב כזה, והתפלל שיבטל הקדוש ברוך הוא גזירה זו.","\u0003ואמר ר' אילעא בר יברכיה: שני תלמידי חכמים המהלכין בדרך ואין ביניהן דברי תורה\u0004 ומשוחחים בדברים אחרים — \u0003ראוין לישרף באש, שנאמר\u0004 באליהו ואלישע תלמידו: \u0003\"ויהי המה הלכים הלוך ודבר והנה רכב אש\u0004 וסוסי אש ויפרידו בין שניהם\u0003\"\u0004 (מלכים ב ב, יא), \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 משום \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003דיבור\u0004 ביניהם, שודאי היה זה דיבור של קדושה, \u0003הא ליכא\u0004 \u0005[הרי\u0006 אם \u0005לא היה]\u0006 \u0003דיבור —\u0004 \u0003ראוין\u0004 היו \u0003לישרף\u0004 ברכב אש זה.","\u0003ואמר ר' אילעא בר יברכיה: שני תלמידי חכמים הדרין בעיר אחת ואין נוחין זה לזה בהלכה\u0004 אלא רבים זה עם זה — \u0003אחד\u0004 מהם \u0003מת ואחד גולה, שנאמר:\u0004 \u0003\"לנס שמה רוצח אשר ירצח את רעהו בבלי דעת\"\u0004 (דברים ד, מב), \u0003ואין דעת אלא תורה, שנאמר:\u0004 \u0003\"נדמו עמי מבלי הדעת\"\u0004 (הושע ד, ו).","\u0003אמר ר' יהודה בריה\u0004 \u0005[בנו]\u0006 \u0003של\u0004 \u0003ר' חייא: כל תלמיד חכם העוסק בתורה מתוך הדחק\u0004 של עוני — \u0003תפלתו נשמעת, שנאמר:\u0004 \u0003\"כי עם בציון ישב בירושל ם בכו לא תבכה חנון יחנך לקול זעקך כשמעתו ענך\"\u0004 (ישעיה ל, יט), \u0003וכתיב בתריה\u0004 \u0005[ונאמר אחריו]:\u0006 \u0003\"ונתן לכם ה' לחם צר ומים לחץ\"\u0004 (ישעיה ל, כ), משמע שהיושבים ועוסקים בתורה (\"עם בציון ישב\") ואוכלים לחם צר מתחננים וה' שומע לקולם.","\u0003ר' אבהו אומר:\u0004 תלמיד חכם כזה \u0003משביעין אותו מזיו שכינה, שנאמר\u0004 בהמשך: \u0003\"והיו עיניך ראות את מוריך\"\u0004 (ישעיה ל, כ). \u0003ר' אחא בר חנינא אמר: אף אין הפרגוד\u0004 (מסך המסתיר) שלפני השכינה \u0003ננעל בפניו, שנאמר:\u0004 \u0003\"ולא יכנף\u0004 (יתכסה) \u0003עוד מוריך\"\u0004 (ישעיה ל, כ).","במשנה נאמר ש \u0003רבן שמעון בן גמליאל אומר משום\u0004 (בשם) \u0003ר' יהושע: מיום שחרב בית המקדש אין\u0004 לך יום שאין בו קללה. \u0003אמר רבא: בכל יום ויום מרובה קללתו משל חבירו, שנאמר\u0004 בפרשת הקללות: \u0003\"בבקר תאמר מי יתן ערב ובערב תאמר מי יתן בקר\"\u0004 (דברים כח, סז), וצריכים לבאר \u0003הי\u0004 \u0005[איזה]\u0006 \u0003בקר\u0004 הוא זה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שאומרים בערב מי יתן \u0003בקר\u0004 ש\u0003למחר, מי ידע מאי הוי\u0004 \u0005[האם יודע מה יהיה]\u0006 בבוקר של מחר שהוא מצפה לו? \u0003אלא\u0004 ודאי הכוונה לבוקר \u0003דחליף\u0004 \u0005[שחלף],\u0006 שבערב אומרים מי יתן את הבוקר שהיה, מפני שהערב כבר גרוע יותר מן הבוקר.","ושואלים: \u0003ואלא\u0004 אם הכול פוחת ויורד כך, \u0003עלמא אמאי קא מקיים\u0004 \u0005[העולם על מה\u0006 הוא \u0005מתקיים]?\u0006 ומשיבים: \u0003אקדושה דסידרא\u0004 \u0005[על קדושה ש\u0006אומרים על \u0005סדר\u0006 התפלה\u0005]\u0006 בסוף \"ובא לציון גואל\", שאומרים קדושה של המלאכים ומתרגמים אותה, \u0003ו\u0004על \u0003\"יהא שמיה רבא\"\u0004 שאומרים אותו בסוף דברי \u0003אגדתא\u0004 \u0005[אגדה],\u0006 \u0003שנאמר:\u0004 \u0003\"ארץ עפתה כמו אפל צלמות ולא סדרים\"\u0004 (איוב י, כב), \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003יש סדרים\u0004 סדרי תפילה ולימוד — \u0003תופיע מאופל\u0004 תצא הארץ מן האפילה.","שנינו במשנה, כי משחרב המקדש \u0003לא ירד טל לברכה וניטל טעם פירות וכו'. תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003ר' שמעון בן אלעזר\u0004 \u0003אומר: טהרה\u0004 שבטלה — \u0003בטלה טעם וריח, מעשר\u0004 שבטל — \u0003ביטל שומן דגן.\u0004","מסופר: \u0003רב הונא אשכח תומרתא דחינוניתא\u0004 \u0005[מצא תמרה ריחנית],\u0006 \u0003שקלה, כרכה בסודריה\u0004 \u0005[לקח אותה\u0006 ו\u0005כרך אותה בסודרו].\u0006 \u0003אתא\u0004 \u0005[בא]\u0006 \u0003רבה בריה\u0004 \u0005[בנו],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 הבן: \u0003מורחינא ריחא דחינוניתא\u0004 \u0005[מריח אני ריח של\u0006 תמרה \u0005ריחנית].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב הונא: \u0003בני, טהרה יש בך,\u0004 לא בטל לגביך הריח. \u0003יהבה ניהליה\u0004 \u0005[נתן לו אותה].\u0006 \u0003אדהכי אתא\u0004 \u0005[בינתיים בא]\u0006 \u0003אבא בריה\u0004 \u0005[בנו]\u0006 של רבה, \u0003שקלה, יהבה ניהליה\u0004 \u0005[לקח\u0006 רבה את התמרה ו\u0005נתן אותה לו\u0006 לבנו\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב הונא לרבה: \u0003בני, שמחת את לבי\u0004 בטהרתך, \u0003והקהיתה את שיני\u0004 שנראה שבנך חביב עליך יותר. ומעירים: \u0003היינו דאמרי אינשי\u0004 \u0005[זהו שאומרים אנשים]\u0006 בפתגם עממי: \u0003רחמי דאבא\u0004 \u0005[אהבת האב]\u0006 — \u0003אבני\u0004 \u0005[על הבנים\u0006 שלו\u0005],\u0006 \u0003רחמי דבני\u0004 \u0005[אהבת הבנים] —\u0006 \u0003אבני דהוו ליה\u0004 \u0005[על הבנים שיש להם]\u0006 יותר מאהבת אביהם.","מסופר: \u0003רב אחא בר יעקב איטפל ביה\u0004 \u0005[טיפל בו]\u0006 \u0003ברב יעקב בר ברתיה\u0004 \u0005[בן בתו]\u0006 שהיה יתום. \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003גדל\u0004 הנכד \u0003אמר ליה\u0004 \u0005[לו]\u0006 סבו פעם אחת: \u0003אשקיין מיא\u0004 \u0005[השקה אותי מים].\u0006 \u0003אמר לו: לאו בריך אנא\u0004 \u0005[אין אני בנך]\u0006 ואין אני מחוייב על פי הדין בכבודך. ואומרים: \u0003והיינו דאמרי אינשי\u0004 \u0005[וזהו שאומרים אנשים]\u0006 בפתגמם: \u0003רבי רבי, בר ברתך אנא\u0004 \u0005[גדל גדל\u0006 את הנכד, ולבסוף יאמר לך: \u0005בן בתך אני]\u0006 ואינני חייב לדאוג לך.","\u0003בפולמוס\u0004 (מלחמה) \u0003של אספסיינוס גזרו על עטרות חתנים,\u0004 שלא יתעטרו החתנים בעטרות, \u0003ועל האירוס\u0004 (כלי זמר) שלא ינגנו בו.","\u0003בפולמוס של טיטוס גזרו\u0004 איסור גם \u0003על עטרות כלות, ו\u0004גזרו \u0003שלא ילמד אדם את בנו יוונית.\u0004","\u0003בפולמוס האחרון\u0004 של בר כוכבא \u0003גזרו שלא תצא הכלה באפריון בתוך העיר, ורבותינו התירו שתצא הכלה באפריון בתוך העיר\u0004 משום צניעות.","ועוד על דברים שבטלו: \u0003משמת ר' מאיר בטלו מושלי משלים. משמת בן עזאי בטלו השקדנים. משמת בן זומא בטלו הדרשנים. משמת ר' עקיבא בטל כבוד התורה. משמת ר' חנינא בן דוסא בטלו אנשי מעשה\u0004 (בעלי מופת). \u0003משמת ר' יוסי קטנתא פסקו חסידים. ולמה נקרא שמו \"קטנתא\" —\u0004 \u0003שהיה קטנתא של חסידים,\u0004 כלומר, היה מקטנם ואחרוניהם של החסידים.","\u0003משמת ר' יוחנן בן זכאי בטל זיו החכמה. משמת רבן גמליאל הזקן בטל כבוד התורה, ומתה טהרה ופרישות. משמת ר' ישמעאל בן פאבי בטלה זיו הכהונה. משמת רבי בטל ענוה ויראת חטא.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ר' פנחס בן יאיר אומר: משחרב בית המקדש בושו חברים\u0004 (תלמידי חכמים) \u0003ובני חורין\u0004 (מיוחסים), \u0003וחפו ראשם, ונדלדלו אנשי מעשה, וגברו בעלי זרוע ובעלי לשון, ואין דורש ואין מבקש ואין שואל\u0004 על יראת שמים,","\u0003על מי לנו להשען —\u0004 \u0003על אבינו שבשמים\u0004 בלבד.","\u0003ר' אליעזר הגדול אומר: מיום שחרב בית המקדש\u0004 היתה ירידת הדורות; \u0003שרו חכימיא למהוי כספריא\u0004 \u0005[החלו החכמים להיות כמו הסופרים,\u0006 מלמדי תינוקות\u0005],\u0006 \u0003וספריא כחזניא\u0004 \u0005[והסופרים כמו שמשים],\u0006 \u0003וחזניא כעמא דארעא\u0004 \u0005[והחזנים כעמי הארץ],\u0006 \u0003ועמא דארעא\u0004 \u0005[ועמי הארץ]\u0006"],["\u0003אזלא ודלדלה\u0004 \u0005[הולכים ודלים],\u0006 \u0003ואין שואל ואין מבקש, על מי יש להשען —\u0004 \u0003על אבינו שבשמים.\u0004","ועוד אמר: \u0003בעקבות משיחא\u0004 \u0005[המשיח],\u0006 בסמוך לבואו, \u0003חוצפא יסגא\u0004 \u0005[החוצפה תיגדל]\u0006 \u0003ויוקר יאמיר\u0004 (יגדל). \u0003הגפן\u0004 אמנם \u0003תתן פריה\u0004 אבל \u0003היין\u0004 יהיה \u0003ביוקר, ומלכות תהפך למינות ואין תוכחת,\u0004 אין מי שיוכיח על כך. \u0003בית וועד\u0004 החכמים \u0003יהיה ל\u0004מקום \u0003זנות, והגליל יחרב, והגבלן\u0004 (הגולן) \u0003ישום\u0004 (יהיה שומם), \u0003ואנשי הגבול יסובבו מעיר לעיר\u0004 בנדודיהם לבקש צדקה \u0003ולא יחוננו,\u0004","\u0003וחכמות סופרים תסרח\u0004 (תימאס), \u0003ויראי חטא ימאסו, והאמת תהא נעדרת. נערים פני זקנים ילבינו, זקנים יעמדו מפני קטנים,\u0004 ואף חיי המשפחה יהרסו — \u0003בן מנוול אב, בת קמה\u0004 (מתקוממת) \u0003באמה, כלה בחמתה, איבי איש אנשי ביתו, פני הדור\u0004 יהיו \u0003כפני הכלב, הבן אינו מתבייש\u0004 עוד \u0003מאביו, ועל מה יש לנו להשען\u0004 אחרי כל אלה — \u0003על אבינו שבשמים.\u0004","\u0003אמר רב:\u0004 מה שנאמר שביטלו את העטרות \u0003לא שנו אלא\u0004 עטרות \u0003של מלח וגפרית, אבל\u0004 עטרות \u0003של הדס ושל וורד —\u0004 \u0003מותר. ושמואל אומר: אף\u0004 עטרות \u0003של הדס ושל וורד אסור,\u0004 אבל \u0003של קנים ושל חילת\u0004 (סוף) — \u0003מותר. ולוי אמר: אף\u0004 עטרות \u0003של קנים ושל חילת אסור. וכן תני\u0004 \u0005[שנה]\u0006 \u0003לוי במתניתיה\u0004 \u0005[בברייתא שלו]:\u0006 \u0003אף של קנים ושל חילת אסור.\u0004","שנינו במשנה שגזרו על עטרות חתנים \u0003ועל האירוס.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 הוא\u0005]\u0006 \u0003\"אירוס\"\u0004 זה? \u0003אמר ר' אלעזר: טבלא דחד פומא\u0004 \u0005[תוף של פה אחד]\u0006 שמקישים בו. מסופר: \u0003רבה בר רב הונא עבד ליה לבריה טנבורא\u0004 \u0005[עשה לו, לבנו טמבור],\u0006 \u0003אתא אבוה תבריה\u0004 \u0005[בא אביו,\u0006 רב הונא, ו\u0005שבר אותו],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מיחלף בטבלא דחד פומא\u0004 \u0005[\u0006הרי זה \u0005מתחלף בתוף של פה אחד]\u0006 ויבואו להתירו, \u0003זיל עביד ליה\u0004 \u0005[לך עשה לו]\u0006 תוף קטן \u0003אפומא דחצבא\u0004 \u0005[על פיו של כד]\u0006 \u0003או אפומא דקפיזא\u0004 \u0005[על פי סאה]\u0006 שמודדים בה, ולא תוף ממש.","עוד שנינו במשנה: \u0003בפולמוס של טיטוס גזרו על עטרות כלות וכו'.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 הן\u0005]\u0006 \u0003\"עטרות כלות\"\u0004 אלה? \u0003אמר רבה בר בר חנה אמר ר' יוחנן: עיר,\u0004 עטרה מצוירת, \u0003של זהב\u0004 שהיו מתקשטות בה הנשים. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003איזהו עטרות כלות —\u0004 \u0003עיר של זהב, אבל עושה אותה\u0004 את העטרת לכלה במקום זה \u0003כיפה של מילת\u0004 (צמר משובח).","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003אף על חופת חתנים גזרו.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"חופת חתנים\"?\u0004 שוודאי לא בטלו את חופות הנישואין. ומשיבים: הכוונה היא ל\u0003זהורית המוזהבות\u0004 (בגדים צבועים בצבע אדום וזהורית, ומקושטים בזהב) שהיו תולים בחופה. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003אלו הן חופת חתנים\u0004 שגזרו עליה — \u0003זהורית המוזהבות, אבל עושה פפירית\u0004 (מבנה של גומא) \u0003ותולה בה כל מה שירצה.\u0004 שנינו במשנה שבפולמוס של טיטוס גזרו \u0003שלא ילמד את בנו יוונית. תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 כיצד נגזרה הגזירה: \u0003כשצרו מלכי בית חשמונאי זה על זה\u0004 במלחמת האחים שלהם \u0003היה הורקנוס מבחוץ\u0004 לירושלים וצר עליה, \u0003ואריסטובלוס מבפנים. בכל יום ויום היו משלשלין\u0004 מתוך העיר \u0003דינרים בקופה, ומעלין להן\u0004 אותם שבחוץ בהמות להקרבת ה\u0003תמידים\u0004 במקדש.","","\u0003היה שם\u0004 בירושלים \u0003זקן אחד שהיה מכיר בחכמת יוונית, לעז להם\u0004 לאלו שבחוץ \u0003בחכמת יוונית, אמר להן: כל זמן שעוסקים\u0004 בפנים \u0003בעבודה\u0004 שבמקדש \u0003אין נמסרין בידכם.\u0004 כיון ששמעו כך, \u0003למחר שלשלו להם\u0004 מבפנים \u0003דינרים בקופה והעלו להם\u0004 מבחוץ \u0003חזיר. כיון שהגיע\u0004 החזיר \u0003לחצי\u0004 גובה ה\u0003חומה, נעץ\u0004 בה את \u0003צפרניו\u0004 (טלפיו), \u0003נזדעזעה ארץ ישראל ארבע מאות פרסה.\u0004","\u0003אותה שעה\u0004 שראו חכמים דבר זה \u0003אמרו: ארור אדם שיגדל חזירים, וארור אדם שילמד לבנו חכמת יוונית. ועל אותה שנה\u0004 שנחרבה בה הארץ \u0003שנינו: מעשה ובא עומר מגגות צריפים, ושתי הלחם מבקעת עין סוכר,\u0004 שלא נמצא אלא במקומות רחוקים אלה. מן המשנה ומן המעשה המסופר בברייתא עולה שאסור ללמוד יוונית.","ומקשים: \u0003איני\u0004 \u0005[האם כן הוא]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבי: בארץ ישראל\u0004 דיבור ב\u0003לשון סורסי\u0004 (ארמית של ארץ ישראל) \u0003למה? אלא אי\u0004 \u0005[או]\u0006 שידברו ב\u0003לשון הקודש\u0004 שהיא לשוננו, \u0003אי\u0004 \u0005[או]\u0006 ב\u0003לשון יוונית\u0004 שהיא יפה. \u0003ו\u0004כן \u0003אמר רב יוסף\u0004 כיוצא בזה: \u0003בבבל לשון ארמי\u0004 שהיא לשון העם המדוברת \u0003למה? אלא או\u0004 ידברו \u0003לשון הקודש, או לשון פרסי\u0004 שהיא לשון הממשלה!","ומשיבים: יש להבדיל: \u0003לשון יוונית לחוד\u0004 היא מותרת, \u0003וחכמת יוונית לחוד\u0004 ואותה אסרו.","ושואלים: \u0003וחכמת יוונית מי אסירא\u0004 \u0005[האם\u0006 היא \u0005אסורה]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יהודה אמר שמואל משום\u0004 (בשם) \u0003רבן שמעון בן גמליאל: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"עיני עוללה לנפשי מכל בנות עירי\"\u0004 (איכה ג, נא) — \u0003אלף ילדים\u0004 (אנשים צעירים) \u0003היו בבית אבא\u0004 (בבית הנשיאים), \u0003חמש מאות\u0004 מהם \u0003למדו תורה, וחמש מאות למדו חכמה יוונית, ולא נשתייר מהן\u0004 לאחר מלחמת בר כוכבא \u0003אלא אני כאן, ובן אחי אבא\u0004 שחי \u0003בעסיא,\u0004 והרי שמותר ללמוד חכמה יוונית, שאם לא כן וודאי לא היו לומדים אותה בבית הנשיא!","ומשיבים: \u0003שאני\u0004 \u0005[שונים]\u0006 אנשים \u0003של בית רבן גמליאל,\u0004 ש\u0003קרובין למלכות הוו\u0004 \u0005[היו],\u0006 והיו זקוקים לחכמה יוונית כדי לשוחח בה עם גדולי המלכות. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 מי ש\u0003מספר קומי,\u0004 שמגדל שיער ארוך מאחוריו, \u0003הרי זה מדרכי האמורי\u0004 ואסור. ואולם \u0003אבטולוס בן ראובן התירו\u0004 לו \u0003לספר קומי,\u0004 מפני \u0003שהוא קרוב למלכות.\u0004 וכן \u0003של בית רבן גמליאל התירו להן חכמה יוונית מפני שקרובין למלכות.\u0004","שנינו: \u0003בפולמוס האחרון גזרו שלא תצא כלה באפריון\u0004 אבל רבותינו התירו. ומסבירים \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 התירו לשאת את הכלה באפריון — \u0003משום צניעותא\u0004 \u0005[צניעות]\u0006 שיש בדבר.","עוד שנינו: \u0003משמת רבן יוחנן\u0004 בן זכאי \u0003בטלה החכמה. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003משמת ר' אליעזר נגנז ספר תורה,\u0004 שהיה בקי בכל מכמני התורה שהיו שמורים בזכרונו. \u0003משמת ר' יהושע בטלה עצה ומחשבה\u0004 שהוא היה חכם ופיקח שבישראל, \u0003משמת ר' עקיבא בטלו זרועי תורה\u0004 (כוחה של תורה) בדרשת המקראות לכל פרטיהם \u0003ונסתתמו מעיינות החכמה.\u0004 \u0003משמת ר' אלעזר בן עזריה בטלו עטרות חכמה, ש\"עטרת חכמים עשרם\"\u0004 (משלי יד, כד) והוא היה גם גדול בתורה וגם גדול בעושר. \u0003משמת ר' חנינא בן דוסא בטלו אנשי מעשה\u0004 (בעלי מופת). \u0003משמת אבא יוסי בן קטונתא בטלו חסידים, ולמה נקרא שמו אבא יוסי בן קטונתא —\u0004 \u0003שהיה מקטני חסידים.\u0004","","\u0003משמת בן עזאי בטלו השקדנין, משמת בן זומא בטלו הדרשנין, משמת רבן שמעון בן גמליאל עלה גובאי\u0004 (ארבה) על הארץ \u0003ורבו צרות. משמת רבי הוכפלו צרות.\u0004","שנינו: \u0003משמת רבי בטלה ענוה ויראת חטא. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף לתנא\u0004 \u0005[לחוזר המשניות]\u0006 ששנה לפניו את המשנה: \u0003לא תיתני\u0004 \u0005[תשנה]\u0006 שבטלה \u0003ענוה,\u0004 כיון \u0003דאיכא\u0004 \u0005[שיש]\u0006 — \u0003אנא\u0004 \u0005[אני],\u0006 שאני עניו. ובדומה לזה \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן לתנא\u0004 \u0005[לחוזר המשניות]:\u0006 \u0003לא תיתני\u0004 \u0005[תשנה]\u0006 שבטלה \u0003יראת חטא,\u0004 כיון \u0003דאיכא\u0004 \u0005[שיש]\u0006 — \u0003אנא\u0004 \u0005[אני],\u0006 שאני ירא חטא.",""]]};
